class FajrCallTest(unittest.TestCase):
    """Fajr has its own call, because the words at dawn are not the same."""

    def window(self, **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(**{"theme": "light", "recitation": False, "azaan": True,
                                   **settings}),
                       scale=1.0, save_settings=False)
        w.resize(1920, 1080)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_fajr_has_a_recording_of_its_own(self):
        w = self.window()
        self.assertEqual("azaan-fajr.mp3", w.azaan_for("fajr").name)

    def test_the_other_four_share_the_ordinary_one(self):
        w = self.window()
        for prayer in ("dhuhr", "asr", "maghrib", "isha"):
            self.assertEqual("azaan.mp3", w.azaan_for(prayer).name, prayer)

    def test_calling_fajr_plays_the_fajr_recording(self):
        w = self.window()
        played = []

        class Player:
            volume = 80
            playing = True

            def play(self, path):
                played.append(Path(path).name)
                return True

            def stop(self):
                pass
        w.call = Player()
        w.call_to_prayer("fajr")
        settle()
        self.assertEqual(["azaan-fajr.mp3"], played)
        self.assertIsNotNone(w.call_box, "and the notice still says it is time")
        w.end_the_call()
        settle()

    def test_with_no_fajr_recording_it_stays_silent_rather_than_saying_the_wrong_words(self):
        """The fallback that was the whole behaviour before the recording arrived, and is still
        right: the notice appears, nothing is said, because the ordinary call says words that do
        not belong to Fajr.

        This used to replace azaan_for with a stub that returned None, which tested the stub and
        not the app -- deleting the real fallback broke nothing. So it gives the window a folder
        holding only the ordinary recording and asks the real method.
        """
        import shutil
        import tempfile
        w = self.window()
        room = Path(tempfile.mkdtemp())
        self.addCleanup(lambda: shutil.rmtree(room, ignore_errors=True))
        (room / "audio").mkdir()
        shutil.copy(ASSETS / "audio" / "azaan.mp3", room / "audio" / "azaan.mp3")
        w.assets = room
        self.assertIsNone(w.azaan_for("fajr"), "Fajr must not be given the ordinary call")
        self.assertEqual("azaan.mp3", w.azaan_for("isha").name, "the others still have theirs")

        played = []

        class Player:
            volume = 80
            playing = False

            def play(self, path):
                played.append(Path(path).name)
                return True

            def stop(self):
                pass
        w.call = Player()
        w.call_to_prayer("fajr")
        settle()
        self.assertEqual([], played)
        self.assertIsNotNone(w.call_box, "but the mat still says it is time")
        w.end_the_call()
        settle()

    def test_a_prayer_with_no_recording_at_all_is_still_announced(self):
        """A half-copied mat has no audio. It should still put the notice up."""
        import tempfile
        w = self.window()
        w.assets = Path(tempfile.mkdtemp())
        self.addCleanup(lambda: __import__("shutil").rmtree(w.assets, ignore_errors=True))
        for prayer in ("fajr", "dhuhr"):
            self.assertIsNone(w.azaan_for(prayer), prayer)
        w.call_to_prayer("dhuhr")
        settle()
        self.assertIsNotNone(w.call_box)
        w.end_the_call()
        settle()


class MatchedButtonsTest(unittest.TestCase):
    """The play button is sized off Back beside it, in every language.

    It used to match Back exactly. It is now square and twice Back's height, because the mark on
    it was asked for twice as big -- but it is still MEASURED from Back rather than written down
    as a number, which is the part that cannot be done in the stylesheet."""

    def window(self, **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(**{"theme": "light", "recitation": True, **settings}),
                       scale=1.0, save_settings=False)
        w.resize(1920, 1080)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_they_are_the_same_size_whatever_the_word_for_back_is(self):
        """It cannot be done in the stylesheet: Back is Retour in French and Volver in Spanish,
        so its width is only known once it has been styled and laid out, while the glyph is
        always one character. Setting it while building the screen did nothing at all, because
        the stylesheet had not been applied yet."""
        for lang in ("en", "fr", "es", "ur"):
            w = self.window(lang=lang)
            w.open_surah(2)
            settle()
            r = w.reader
            self.assertEqual(r.back_button.height() * 2, r.recite_button.height(),
                             f"in {lang}: Back is {r.back_button.size()}, "
                             f"play is {r.recite_button.size()}")
            self.assertEqual(r.recite_button.height(), r.recite_button.width(),
                             f"in {lang}: the play button is not square")
            self.assertGreater(r.recite_button.width(), 0)
            w.close()
            settle()

    def test_they_stay_matched_when_the_window_is_resized(self):
        w = self.window()
        w.open_surah(2)
        settle()
        w.resize(1280, 800)
        settle()
        r = w.reader
        self.assertEqual(r.back_button.height() * 2, r.recite_button.height())
        self.assertEqual(r.recite_button.height(), r.recite_button.width())


class TwoMosquesTest(unittest.TestCase):
    """The kalima menu and the front door show the same building in the same place.

    Measured off the drawn screens, not off the asset files: what matters is where the minarets
    and the dome land once each screen has laid itself out, banner and all."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="light", recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        settle()
        # The birds drift and the stars twinkle, and both are drawn in the same white as the
        # building. Left in, the topmost ink in a band is whichever bird happens to be passing.
        for screen in (w.mosque, *(menu.mosque for menu in w.arch_menus.values())):
            screen.sky.birds = []
            screen.sky.stars = []
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    @staticmethod
    def landmarks(w):
        """Where the minaret tips and the top of the dome are on screen, in window pixels.

        The ink is whatever stands out from the page: dark lines on the white screen, bright
        ones on the black. This used to look for dark pixels only. On the night screen that is
        every pixel, so it found row 110 -- the first row it looked at -- and averaged 480
        pixels of empty sky. Both screens gave the same meaningless number and the test passed
        without ever having measured a minaret.

        The sun is skipped by colour: it is the one thing up there that is not a shade of grey.
        The birds and stars are cleared by the window above, because they move.
        """
        image = w.grab().toImage()
        wide, tall = image.width(), image.height()
        from salaah import theme
        night = theme.palette().dark
        ink = [[False] * wide for _ in range(tall)]
        for y in range(110, tall):              # below the banner, which is black all through
            row = ink[y]
            for x in range(wide):
                colour = QtGui.QColor(image.pixel(x, y))
                total = colour.red() + colour.green() + colour.blue()
                spread = (max(colour.red(), colour.green(), colour.blue())
                          - min(colour.red(), colour.green(), colour.blue()))
                row[x] = (total > 450 if night else total < 330) and spread < 40
        found = {}
        for name, low, high in (("left", 0, wide // 4), ("dome", wide // 4, 3 * wide // 4),
                                ("right", 3 * wide // 4, wide)):
            top = next((y for y in range(110, tall)
                        if any(ink[y][low:high])), None)
            if top is None:
                return None
            xs = [x for x in range(low, high) if ink[top][x]]
            found[name] = (sum(xs) // len(xs), top)
        return found

    def measured(self, w, tries=12):
        """landmarks(), given time to become measurable.

        Not a lowered bar: it still fails if the drawing never appears, and every number it
        then checks is checked as strictly as before. It is a wait, and it is here because
        this test failed once in a full run and passed on its own twice and in the next full
        run -- the signature settle() describes in its own docstring, a grab taken before the
        queued work behind it had finished. Five rounds of events is enough on an idle machine
        and is not a promise; a drawing that is actually there arrives within one or two more.
        """
        for _ in range(tries):
            found = self.landmarks(w)
            if found is not None:
                return found
            settle()
        return None

    def test_the_minarets_and_dome_land_in_the_same_place_across_the_family(self):
        """Every mosque on the mat is the same building drawn again, so the minarets and the
        dome have to land on the same pixels wherever you are.

        The kalima menu is back in this check in 1.64. It was taken out in 1.63 -- the rest of
        the mat had been redrawn and it had not, so it no longer lined up -- with a note and a
        test whose job was to fail the moment Harry replaced it. He has, so this is what that
        reminder was for.
        """
        w = self.window()
        w.stack.setCurrentWidget(w.home)
        settle()
        mosque = self.measured(w)
        self.assertIsNotNone(mosque, "nothing measurable on the mosque itself")

        def compare(what, found):
            self.assertIsNotNone(found, f"{what}: nothing measurable on screen")
            for part in ("left", "right", "dome"):
                across = abs(found[part][0] - mosque[part][0])
                down = abs(found[part][1] - mosque[part][1])
                self.assertLess(across, 25, f"{what}: {part} is {across}px across")
                self.assertLess(down, 25, f"{what}: {part} is {down}px down")

        for prayer in ("fajr", "isha"):
            with self.subTest(prayer):
                w.open_prayer(prayer)
                page = getattr(w, "prayer_mosque", None)
                self.assertIsNotNone(page, f"{prayer} did not open on a drawing")
                page.sky.birds = []
                page.sky.stars = []
                settle()
                compare(prayer, self.measured(w))

        with self.subTest("the kalima menu"):
            w.open_corner("kalima")
            settle()
            compare("the kalima menu", self.measured(w))

    def test_every_drawing_is_one_size(self):
        """A drawing of another size does not get clipped -- MosqueScreen scales it to fit --
        it sits smaller and higher than the one before it, which is how this was noticed.

        All of them again since 1.64, the kalima menu included."""
        sizes = {QtGui.QImage(str(ASSETS / f / "mosque.png")).size()
                 for f in ["mosque", "kalima"] + [f"prayers/{p}" for p in PRAYERS]}
        self.assertEqual(1, len(sizes), f"the drawings are not all one size: {sizes}")

    def test_the_arch_menu_has_no_bar_of_its_own_stealing_height(self):
        """It used to carry a Main screen button in a row above the mosque, which pushed the
        drawing down and made it shorter than the front door's."""
        w = self.window()
        menu = w.arch_menus["kalima"]
        self.assertEqual(menu.mosque.height(), menu.height(),
                         "something above the mosque is taking height from it")


class SettingsScreenTest(unittest.TestCase):
    """The Settings screen after the tidy: the same strip over it as the rest of the mat, the
    wordy choices as pickers, the ring's circle, and the foot pushed apart."""

    def window(self, **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(**{"theme": "light", "recitation": False, "place": "Bury",
                                   **settings}),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        settle()
        w.open_settings()
        w.tick()                 # the clock is what writes the strip's words
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def banner(self, w):
        strips = [x for x in w.settings_screen.findChildren(QtWidgets.QWidget)
                  if x.objectName() == "banner"]
        self.assertEqual(1, len(strips), "one strip over Settings, no more and no fewer")
        return strips[0]

    def test_settings_wears_the_same_strip_as_the_rest_of_the_mat(self):
        """It was the one screen with a bare white top. It now says where you are, when the
        prayers are and how loud it is, exactly as the Knowledge Corner does."""
        w = self.window()
        strip = self.banner(w)
        self.assertEqual(0, strip.mapTo(w.settings_screen, QtCore.QPoint(0, 0)).y(),
                         "the strip is the top of the screen, not a row part way down")
        said = [x for x in strip.findChildren(QtWidgets.QLabel)
                if x.objectName() == "bannerText"]
        self.assertEqual(1, len(said))
        self.assertIn("Bury", said[0].text())
        for prayer in ("fajr", "dhuhr", "asr", "maghrib", "isha"):
            self.assertIn(w.t(f"prayer.{prayer}"), said[0].text(), prayer)
        self.assertEqual(1, len(strip.findChildren(QtWidgets.QSlider)), "and how loud it is")

    def test_the_strip_carries_the_way_home_and_no_cog(self):
        """A cog on the Settings banner would be a button back to the screen you are on."""
        from salaah.mosque import GearButton
        w = self.window()
        strip = self.banner(w)
        self.assertEqual([], strip.findChildren(GearButton), "no cog on Settings' own strip")
        home = [b for b in strip.findChildren(QtWidgets.QPushButton)
                if b.objectName() == "mainScreen"]
        self.assertEqual(1, len(home), "the way home is on the strip now")
        home[0].click()
        settle()
        self.assertIs(w.welcome, w.stack.currentWidget())

    def test_it_is_told_apart_from_the_page_underneath_it(self):
        """Rendered rather than read off the layout: a strip that lays out correctly and
        cannot be told from the page underneath it is not a strip.

        THE CLAIM IS THE SAME ONE AS BEFORE; WHAT SATISFIES IT HAS CHANGED. Until 2.07 this
        counted dark pixels, because the strip was painted `chip` -- black over a white page --
        and 70% of it being dark was the same statement as it being a band of its own. In 2.07
        the strip takes the mat's own theme at Harry's asking, so it is white on a white page
        and black on a black one, and the old count reads 5%.

        That is not a threshold to lower. A strip the colour of the page really is the fault
        this test was written to catch, which is why it was put to Harry rather than quietly
        retired, and he chose a hairline under it over leaving it merged. So the test now asks
        what it always meant to ask -- is this strip separable from the page -- and the answer
        is the rule at its foot. Measured in both themes, because "is dark" was never going to
        survive a strip that is deliberately light.
        """
        from salaah import theme
        from salaah.ui import BANNER_RULE
        for mode in ("light", "dark"):
            w = self.window(theme=mode)
            with self.subTest(mode):
                strip = self.banner(w)
                where = strip.mapTo(w, QtCore.QPoint(0, 0))
                image = w.grab().toImage()
                line = QtGui.QColor(theme.palette().line)
                foot = where.y() + strip.height() - 1
                xs = [x for x in range(where.x() + 4, where.x() + strip.width() - 4, 37)]
                self.assertTrue(xs, "the strip has no width to measure")
                for x in xs:
                    self.assertEqual(line.rgb(), QtGui.QColor(image.pixel(x, foot)).rgb(),
                                     f"at x={x} the foot of the strip is "
                                     f"{QtGui.QColor(image.pixel(x, foot)).name()}, "
                                     f"not the {theme.palette().line} rule")
                # It separates: different from the strip above it AND from the page below it.
                above = QtGui.QColor(image.pixel(xs[0], where.y() + 4))
                below = QtGui.QColor(image.pixel(xs[0], where.y() + strip.height() + 4))
                self.assertNotEqual(line.rgb(), above.rgb(), "the rule is the strip's colour")
                self.assertNotEqual(line.rgb(), below.rgb(), "the rule is the page's colour")
                self.assertGreater(abs(line.lightness() - above.lightness()), 10,
                                   "the rule does not read against the strip")
                thick = [y for y in range(where.y(), where.y() + strip.height())
                         if QtGui.QColor(image.pixel(xs[0], y)).rgb() == line.rgb()]
                self.assertEqual(w.px(BANNER_RULE), len(thick),
                                 f"the rule is {len(thick)}px, not {w.px(BANNER_RULE)}")

    def test_the_lettering_is_a_picker_and_picking_changes_it(self):
        w = self.window()
        box = w.font_picker
        self.assertIsInstance(box, QtWidgets.QComboBox)
        faces = [box.itemData(i) for i in range(box.count())]
        self.assertGreater(len(faces), 1)
        other = next(f for f in faces if f != w.settings.arabic_font)
        box.setCurrentIndex(faces.index(other))
        box.activated.emit(faces.index(other))       # what a finger on the list does
        settle()
        self.assertEqual(other, w.settings.arabic_font, "picking a face did not change it")

    def test_the_edge_of_the_screen_row_has_gone(self):
        """Harry: "get rid of edge of the screen option completely - not needed". It was a
        remedy for a monitor that cuts its edges off, which is a television's problem; a Pi
        that ever meets one has overscan settings of its own in config.txt.

        Checked on the screen rather than on the attribute, because the point of taking it out
        was the room it was using: a row that is gone from the object and still drawn is a row
        that still costs 115 points of a page with none to spare.
        """
        w = self.window()
        self.assertFalse(hasattr(w, "inset_picker"), "the picker is still built")
        said = [x.text() for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                if x.isVisible()]
        self.assertNotIn("Edge of the screen", said)
        for words in said:
            self.assertNotIn("cuts off an edge", words, "its explanation is still on the page")
        from salaah.settings import Settings
        self.assertFalse(hasattr(Settings(), "inset"), "the setting itself is still there")

    def test_the_ring_has_a_filled_circle_that_follows_the_connection(self):
        from salaah.ui import BRICK, MINT
        w = self.window()
        # The ring is named on a box in the two-column block since 1.83, not on a heading over
        # a row of its own. Checked where it now is rather than dropped: what matters is that
        # the mat still calls it by Harry's name for it.
        boxes = [b.text() for b in w.settings_screen.findChildren(QtWidgets.QPushButton)
                 if b.objectName() == "pill"]
        self.assertIn("MySalaah Ring", boxes)
        heads = [x.text() for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                 if x.objectName() == "settingHead"]
        self.assertNotIn("Bluetooth buttons", heads)

        self.assertEqual(BRICK, w.ring_dot.color.name().upper(), "red with nothing paired")
        w.on_devices(["MySalaah Ring"])
        settle()
        self.assertEqual(MINT, w.ring_dot.color.name().upper(), "green once it is connected")
        self.assertIn("MySalaah Ring", w.devices_label.text())
        w.on_devices([])
        settle()
        self.assertEqual(BRICK, w.ring_dot.color.name().upper(), "red again when it goes")

    def test_the_circle_is_beside_the_words_and_actually_filled_in(self):
        """Drawn, not just built: the circle is painted by hand rather than styled, so the test
        looks at the pixels in the middle of it."""
        from salaah.ui import MINT
        w = self.window()
        w.on_devices(["MySalaah Ring"])
        settle()
        dot, words = w.ring_dot, w.devices_label
        self.assertTrue(dot.isVisible() and words.isVisible())
        gap = words.mapTo(w, words.rect().center()).x() - dot.mapTo(w, dot.rect().center()).x()
        self.assertGreater(gap, 0, "the circle goes before the words")
        # Measured to the NAME now, not to the value. Since 1.83 the row is circle, box, value
        # in three columns, so the value sits a box-width further out and the old 400 was
        # measuring across a column that did not used to be there. What the circle has to be
        # beside is the thing it is answering about, which is the box with the name on it.
        named = w.ring_button
        near = named.mapTo(w, named.rect().center()).x() - dot.mapTo(w, dot.rect().center()).x()
        self.assertGreater(near, 0, "the circle goes before the name")
        self.assertLess(near, w.px(400), "and beside it, not across the page")
        self.assertLess(gap, w.px(900), "the value is still on the same line, not a page away")
        middle = dot.grab().toImage().pixel(dot.width() // 2, dot.height() // 2)
        self.assertEqual(MINT, QtGui.QColor(middle).name().upper(),
                         "the circle is solid, not an outline")

    def test_the_update_button_sits_in_the_bottom_right_corner(self):
        w = self.window()
        button = w.update_button
        version = next(x for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                       if x.text().startswith("Version "))
        screen = w.settings_screen
        self.assertGreater(button.mapTo(screen, button.rect().center()).x(), screen.width() * 0.75,
                           "hard against the right-hand edge")
        self.assertLess(version.mapTo(screen, version.rect().center()).x(), screen.width() * 0.25,
                        "and the version left where it was")
        self.assertGreater(button.mapTo(screen, button.rect().center()).y(),
                           screen.height() * 0.85, "in the foot, not part way up")

    def test_the_version_no_longer_says_the_app_name_twice(self):
        from salaah import __version__
        w = self.window()
        said = [x.text() for x in w.settings_screen.findChildren(QtWidgets.QLabel)]
        self.assertIn(f"Version {__version__}", said)
        self.assertNotIn(f"Salaah version {__version__}", said)

    def test_the_screen_mode_setting_is_called_the_mode_not_the_colours(self):
        w = self.window()
        heads = [x.text() for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                 if x.objectName() == "settingHead"]
        self.assertIn("Screen mode", heads)
        self.assertNotIn("Screen colours", heads)

    def test_every_pack_renamed_the_same_three_things(self):
        """Six packs, one screen: if one of them still says the old words the screen changes
        meaning when the language does."""
        import json
        for lang in sorted(full_packs(available_packs(ASSETS))):
            ui = json.loads((ASSETS / "content" / "packs" / lang / "pack.json")
                            .read_text(encoding="utf-8"))["ui"]
            self.assertEqual("MySalaah Ring", ui["settings.buttons"], lang)
            self.assertNotIn("Bluetooth", ui["settings.buttons"], lang)
            self.assertIn("{number}", ui["settings.version"], lang)
            self.assertNotIn("Salaah", ui["settings.version"], lang)


class AzaanScreenTest(unittest.TestCase):
    """The call to prayer on the screen: the muezzin, the words, and the red following them."""

    def window(self, **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(**{"theme": "dark", "recitation": False, "place": "Bury",
                                   "azaan": True, **settings}),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def box(self, w, prayer="fajr", recording="azaan-fajr.mp3"):
        from salaah.call import CallBox
        b = CallBox(w, prayer, recording, w.adhan)
        b.show()
        settle()
        self.addCleanup(lambda: (b.close(), b.deleteLater(), settle()))
        return b

    # Which screen each part of the call goes on

    def two_screens(self, **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(**{"theme": "dark", "recitation": False, "place": "Bury",
                                   "azaan": True, **settings}),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(1024, 600)
        w.side.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_the_muezzin_goes_to_the_small_screen_and_the_words_keep_the_big_one(self):
        """Harry, 12 November 2026: "could the gif be moved to the 7in posture screen
        instead. this way the text / translation will have the main screen to itself."

        The 7in is free at that moment -- it shows postures during a prayer and the Knowledge
        Corner between them, and the call comes before the prayer.

        THE THING THAT WOULD HAVE SUNK THIS is not visible in the layout: the call box is
        MODAL, and a modal dialog blocks input to every other window in the application. It
        blocks input and not painting, so the 7in keeps drawing and its timers keep firing --
        measured before any of this was built, and nothing on the companion is pressable
        anyway. That is why this test asserts the film is RUNNING rather than merely mounted.
        """
        w = self.two_screens()
        box = self.box(w)
        self.assertIsNotNone(box.companion, "nothing was built for the 7in")
        self.assertIs(w.side.stack.currentWidget(), box.companion,
                      "the 7in is not showing the call")
        self.assertFalse(box.drawing.isVisible(),
                         "the muezzin is still on the big screen as well")
        self.assertTrue(box.companion_drawing.there, "no muezzin on the 7in")
        self.assertTrue(box.companion_drawing.moving, "the muezzin on the 7in is not moving")

    def test_the_small_screen_shows_the_prayer_above_the_muezzin(self):
        """The name centred along the top, the picture directly under it -- which prayer,
        then the man calling it, in the order they are read."""
        w = self.two_screens()
        box = self.box(w, prayer="dhuhr")
        said = [x for x in box.companion.findChildren(QtWidgets.QLabel) if x.text().strip()]
        self.assertEqual(1, len(said), "the 7in should carry the prayer's name and nothing else")
        self.assertEqual(w.t("prayer.dhuhr"), said[0].text())
        self.assertEqual(Qt.AlignmentFlag.AlignCenter, said[0].alignment() & Qt.AlignmentFlag.AlignCenter)
        self.assertLess(said[0].y(), box.companion_drawing.y(),
                        "the muezzin is not below the name")

    def test_the_7in_is_handed_back_when_the_call_ends(self):
        """A film left running is a timer waking the Pi ten times a second to repaint
        something nobody can see, and this mat calls five times a day for months."""
        w = self.two_screens()
        box = self.box(w)
        self.assertIs(w.side.stack.currentWidget(), box.companion)
        box.accept()
        settle()
        self.assertIsNot(w.side.stack.currentWidget(), box.companion,
                         "the 7in was never given back")
        self.assertFalse(box.companion_drawing.moving,
                         "the muezzin is still being repainted after the call")

    def test_a_mat_with_one_screen_keeps_the_muezzin_where_he_was(self):
        """Moving him to a screen that does not exist would simply lose him: a mat with one
        display would have gone from a picture and the words to the words alone, which
        nobody asked for."""
        w = self.window()           # no side screen
        box = self.box(w)
        self.assertIsNone(box.companion, "a companion was built with no screen to put it on")
        self.assertTrue(box.drawing.isVisible(), "the muezzin has gone from the only screen")
        said = [x.text() for x in box.findChildren(QtWidgets.QLabel)]
        self.assertTrue([t for t in said if w.t("prayer.fajr") in t],
                        f"nothing says which prayer it is: {said}")

    def test_the_words_are_bigger_when_they_have_the_screen_to_themselves(self):
        """And the room they grow into is the Stop button's old ROW, not the muezzin's column.

        That is worth pinning, because the obvious reading is wrong and I had it wrong first:
        the Arabic is set one line to a row and sized to the HEIGHT of its row, so the 550px
        of width the picture gave back bought nothing at all -- measured against the published
        2.22, the rows came out at 98px either way. What freed real room was taking the name
        and the lone Stop button out of a row 120px tall and floating the button in the
        corner.
        """
        big = self.box(self.two_screens())
        small = self.box(self.window())
        mine = [x for x in big.findChildren(QtWidgets.QLabel)
                if x.objectName() == "callMeaning"][0]
        theirs = [x for x in small.findChildren(QtWidgets.QLabel)
                  if x.objectName() == "callMeaning"][0]
        self.assertGreater(mine.font().pixelSize(), theirs.font().pixelSize(),
                           "the meanings did not grow with the room")
        self.assertGreater(max(a.height() for a in big.boxes.values()),
                           max(a.height() for a in small.boxes.values()),
                           "the Arabic did not grow with the room")

    def test_the_floating_stop_never_sits_on_the_words(self):
        """It is out of the layout, so nothing stops it overlapping except the margin the
        lines keep for it. Checked in every language, because how wide Stop is depends on the
        word: Arreter in French, and a phrase in Urdu."""
        for lang in sorted(full_packs(available_packs(ASSETS))):
            with self.subTest(lang):
                w = self.two_screens(lang=lang)
                box = self.box(w)
                button = box.stop_button
                widest = max(a.x() + a.width() for a in box.boxes.values())
                self.assertLessEqual(widest, button.x(),
                                     f"{lang}: the Arabic runs under the Stop button")
                self.assertLessEqual(button.x() + button.width(), box.width(),
                                     f"{lang}: Stop hangs off the edge of the screen")

    # The words

    def test_the_call_has_its_words_and_every_language_the_app_speaks(self):
        import json
        raw = json.loads((ASSETS / "content" / "azaan" / "adhan.json").read_text(encoding="utf-8"))
        # The six the mat is written in. Arabic only shows the call with nothing under it --
        # see AdhanScreen.meaning_language -- so there is no Arabic meaning to be missing.
        langs = set(full_packs(available_packs(ASSETS)))
        for line in raw["lines"]:
            self.assertTrue(line["arabic"].strip(), line["key"])
            missing = [lang for lang in langs if not line.get("text", {}).get(lang, "").strip()]
            self.assertEqual([], missing, f"{line['key']} has no meaning in {missing}")

    def test_the_call_covers_the_screen_but_for_the_strip(self):
        """It was 88% by 92% -- a box on top of the mat with prayer times showing round the
        edge. The call is not a message about something else happening; it is what the mat is
        doing, so it takes the screen. All but the strip across the top, which Harry asked to
        keep in 1.69: during the call that is the one thing worth seeing behind it."""
        w = self.window()
        b = self.box(w)
        strip = w.banner_height()
        self.assertEqual(QtCore.QSize(w.width(), w.height() - strip), b.size(),
                         "the call is still a box in the middle of the screen")
        self.assertEqual(QtCore.QPoint(w.x(), w.y() + strip), b.pos())

    def test_stop_is_a_big_square_in_the_top_corner(self):
        """Harry asked for it moved off the bottom. On a full screen the bottom edge is a long
        way from a thumb, and this is the one thing on the screen to press -- at the one moment
        somebody wants it, which is when the mat has started calling out in a quiet house."""
        w = self.window()
        b = self.box(w)
        stop = b.stop_button
        self.assertTrue(stop.isVisible())
        self.assertEqual(stop.width(), stop.height(), f"not square: {stop.size()}")
        self.assertGreaterEqual(stop.width(), 90, "too small to aim at in a hurry")
        # Top right of the box, not the bottom.
        middle = stop.mapTo(b, stop.rect().center())
        self.assertLess(middle.y(), b.height() * 0.25, "it is not at the top")
        self.assertGreater(middle.x(), b.width() * 0.75, "it is not on the right")

    def test_stop_is_square_in_every_language_it_is_labelled_in(self):
        """The word is Arrêter in French and رک جائیں in Urdu, so a size written into the
        stylesheet would clip the long ones. It is measured against the screen instead."""
        for lang in ("en", "fr", "ur", "zh"):
            with self.subTest(lang):
                w = self.window(lang=lang)
                stop = self.box(w).stop_button
                self.assertEqual(stop.width(), stop.height(), f"{lang}: {stop.size()}")
                self.assertGreaterEqual(stop.width(), stop.sizeHint().width() * 0.5,
                                        "the label will not fit in it")

    def test_fajr_carries_the_line_the_other_four_do_not(self):
        w = self.window()
        ordinary = w.adhan.shown("azaan.mp3")
        fajr = w.adhan.shown("azaan-fajr.mp3")
        self.assertNotIn("nawm", ordinary, "the dawn line must not be called at Dhuhr")
        self.assertIn("nawm", fajr, "the dawn line is what makes the Fajr call different")
        self.assertEqual([k for k in fajr if k != "nawm"], ordinary,
                         "the two calls are otherwise the same lines in the same order")

    def test_the_lines_shown_are_the_distinct_ones_not_the_repeats(self):
        """The call says most lines twice. Printing it twice would be a wall of the same words;
        the line is shown once and lights again when it is called again."""
        w = self.window()
        self.assertEqual(14, len(w.adhan.order("azaan-fajr.mp3")), "fourteen stretches are called")
        self.assertEqual(7, len(w.adhan.shown("azaan-fajr.mp3")), "seven distinct lines")

    # The timings, measured off the recording

    def test_the_fajr_timings_run_in_order_and_stay_inside_the_recording(self):
        import json
        raw = json.loads((ASSETS / "content" / "azaan" / "times.json").read_text(encoding="utf-8"))
        known = raw["azaan-fajr.mp3"]
        lines = known["lines"]
        self.assertEqual(14, len(lines))
        last = 0
        for row in lines:
            self.assertGreaterEqual(row["start"], last, f"{row['key']} starts before the one before")
            self.assertGreater(row["end"], row["start"], row["key"])
            last = row["end"]
        self.assertLess(lines[-1]["end"], 211_000, "past the end of a 210-second recording")

    def test_every_word_of_a_line_has_a_time_inside_that_line(self):
        w = self.window()
        import json
        known = json.loads((ASSETS / "content" / "azaan" / "times.json")
                           .read_text(encoding="utf-8"))["azaan-fajr.mp3"]
        for row in known["lines"]:
            words = w.adhan.line(row["key"])["arabic"].split()
            self.assertEqual(len(words), len(row["words"]),
                             f"{row['key']}: {len(row['words'])} times for {len(words)} words")
            for a, b in row["words"]:
                self.assertGreaterEqual(a, row["start"], row["key"])
                self.assertLessEqual(b, row["end"] + 1, row["key"])

    def test_the_word_being_called_is_found_from_the_clock(self):
        w = self.window()
        import json
        known = json.loads((ASSETS / "content" / "azaan" / "times.json")
                           .read_text(encoding="utf-8"))["azaan-fajr.mp3"]
        for row in known["lines"]:
            for i, (a, b) in enumerate(row["words"]):
                middle = (a + b) / 2000.0
                self.assertEqual((row["key"], i), w.adhan.at("azaan-fajr.mp3", middle),
                                 f"{row['key']} word {i} at {middle:.2f}s")

    def test_between_the_lines_nothing_is_lit(self):
        """The muezzin breathes. Lighting a word through the silence would be a lie about
        where he is."""
        w = self.window()
        import json
        lines = json.loads((ASSETS / "content" / "azaan" / "times.json")
                           .read_text(encoding="utf-8"))["azaan-fajr.mp3"]["lines"]
        for before, after in zip(lines, lines[1:]):
            middle = (before["end"] + after["start"]) / 2000.0
            self.assertIsNone(w.adhan.at("azaan-fajr.mp3", middle),
                              f"something is lit in the gap before {after['key']}")

    def test_both_recordings_are_measured_now(self):
        """The first ordinary recording would not come apart into its twelve lines and shipped
        without timings. The one that replaced it does, so the red follows the voice at all
        five prayers rather than only at Fajr."""
        w = self.window()
        for recording, lines in (("azaan.mp3", 12), ("azaan-fajr.mp3", 14)):
            self.assertTrue(w.adhan.measured(recording), recording)
            self.assertEqual(lines, len(w.adhan.times[recording]["lines"]), recording)

    def test_a_recording_with_no_measured_timings_lights_nothing(self):
        """Still the rule, and still worth holding: a recording nobody has measured shows its
        words with no red at all. Red in the wrong place is worse than none."""
        w = self.window()
        self.assertFalse(w.adhan.measured("somebody-elses-azaan.mp3"))
        for t in (0.0, 30.0, 90.0, 170.0):
            self.assertIsNone(w.adhan.at("somebody-elses-azaan.mp3", t))
        box = self.box(w, "dhuhr", "somebody-elses-azaan.mp3")
        self.assertFalse(box.follow.isActive(), "nothing to follow, so the clock stays off")
        self.assertTrue(box.boxes, "the words are still shown")

    # The box

    def test_the_box_shows_the_muezzin_the_words_and_the_meanings(self):
        w = self.window()
        box = self.box(w)
        self.assertTrue(box.drawing.there, "the drawing is missing")
        self.assertTrue(box.drawing.isVisible())
        self.assertEqual(7, len(box.boxes), "one for each distinct line of the Fajr call")
        said = [x.text() for x in box.findChildren(QtWidgets.QLabel)
                if x.objectName() == "callMeaning"]
        self.assertEqual(7, len(said), "a meaning under every line")
        self.assertIn("Come to prayer", said)
        self.assertIn("Prayer is better than sleep", said)

    def test_the_meaning_follows_the_language_setting(self):
        w = self.window(lang="ur")
        box = self.box(w)
        said = " ".join(x.text() for x in box.findChildren(QtWidgets.QLabel)
                        if x.objectName() == "callMeaning")
        self.assertIn("نماز", said, "the meanings should be in Urdu")
        self.assertNotIn("Come to prayer", said)

    def test_the_word_being_called_turns_red_and_only_that_one(self):
        w = self.window()
        box = self.box(w)
        box.boxes["salah"].set_highlight((0, 1))
        self.assertEqual((0, 1), box.boxes["salah"].highlight)
        box.clear()
        self.assertTrue(all(b.highlight is None for b in box.boxes.values()))

    def test_the_red_is_actually_painted_red(self):
        """Rendered, not read off the widget: the highlight is drawn by hand, and a box that
        holds the right number and paints the word white is no use to anybody."""
        w = self.window()
        box = self.box(w)
        # The driver is stopped first. It runs every 50ms and clears the red whenever nothing
        # is sounding, which in here is always -- so a highlight set by hand and then left to
        # settle is wiped before it can be looked at, and the test grades a blank line.
        box.follow.stop()
        line = box.boxes["shahada"]
        plain = line.grab().toImage()
        line.set_highlight((0, 2))
        settle()
        lit = line.grab().toImage()
        # Counted against the theme's own highlight colour rather than "looks reddish". White
        # letters on black carry orange fringes from the antialiasing -- (231, 158, 74) and the
        # like -- and a loose test counts those, so it reports red on a line with none.
        from salaah import theme
        want = QtGui.QColor(theme.palette().highlight)
        def lit_pixels(image):
            found = 0
            for y in range(image.height()):
                for x in range(image.width()):
                    c = QtGui.QColor(image.pixel(x, y))
                    if (abs(c.red() - want.red()) < 30 and abs(c.green() - want.green()) < 30
                            and abs(c.blue() - want.blue()) < 30):
                        found += 1
            return found
        self.assertEqual(0, lit_pixels(plain), "nothing is red before a word is lit")
        self.assertGreater(lit_pixels(lit), 20, "the lit word is not painted in the red")

    def test_the_drawing_is_painted_in_the_colour_it_is_given(self):
        """The picture is black lines on nothing, which is invisible on a black box. It is used
        as a stencil, so it has to come out whatever colour it is filled with."""
        from salaah.call import Drawing
        w = self.window()
        for colour, want in (("#FFFFFF", (255, 255, 255)), ("#A63D33", (166, 61, 51))):
            d = Drawing(w.adhan.picture(), colour)
            d.resize(300, 380)
            image = d.grab().toImage()
            hits = set()
            for y in range(0, image.height(), 3):
                for x in range(0, image.width(), 3):
                    c = QtGui.QColor(image.pixel(x, y))
                    if c.alpha() > 200:
                        hits.add((c.red(), c.green(), c.blue()))
            self.assertTrue(any(abs(r-want[0]) < 12 and abs(g-want[1]) < 12 and abs(b-want[2]) < 12
                                for r, g, b in hits),
                            f"nothing drawn in {colour}; got {sorted(hits)[:6]}")
            d.deleteLater()

    # How it is put up and taken down

    def test_the_call_puts_the_box_up_and_stopping_it_stops_the_sound(self):
        from salaah.call import CallBox
        w = self.window()
        w.call_to_prayer("fajr")
        settle()
        self.assertIsInstance(w.call_box, CallBox, "the plain notice should have been replaced")
        self.assertTrue(w.call_box.isVisible())
        w.call_box.accept()
        settle()
        self.assertIsNone(w.call_box, "the box should be let go of when it closes")
        self.assertFalse(w.call.playing)

    def test_it_has_no_border_or_rounded_corners_now_it_fills_the_screen(self):
        """This test used to say the opposite, and said it for a reason: the box was 88% of
        the screen, so the mosque showing round the edge was what made it read as a notice on
        top of the mat rather than a new screen.

        Harry has asked for the full screen, which settles it the other way -- and takes the
        border and the rounded corners with it. They were the edge of a box; on a screen that
        reaches the bezel there is no edge for them to sit on, and a white line down the side
        of a full screen is a white line.
        """
        w = self.window()
        box = self.box(w)
        style = box.styleSheet()
        self.assertNotIn("border-radius", style.split("QDialog#callBox QPushButton")[0],
                         "the box still has rounded corners")
        self.assertNotIn("solid #FFFFFF", style, "the box still has a white border round it")

    def test_the_words_are_marked_as_not_yet_read_over_by_a_reader_of_arabic(self):
        """Drafted, not checked. The flag is what says so; when Harry has read the lines on the
        mat he sets it true, and this test is what will notice if it was set without thought."""
        w = self.window()
        self.assertFalse(w.adhan.reviewed,
                         "if the words have now been checked, say so here as well")

    def test_the_red_goes_out_when_the_call_is_not_sounding(self):
        """Found by accident while writing the test above: the driver clears the red whenever
        the player has no position. That is right and worth holding onto -- when the call is
        stopped part way, the last word must not be left lit."""
        w = self.window()
        box = self.box(w)
        box.follow.stop()
        box.boxes["falah"].set_highlight((0, 1))
        self.assertIsNotNone(box.boxes["falah"].highlight)
        self.assertIsNone(w.call.position(), "nothing is playing in the test")
        box.tick()
        self.assertTrue(all(b.highlight is None for b in box.boxes.values()),
                        "the red stayed on after the voice stopped")


class SurahNumberTest(unittest.TestCase):
    """The number beside each surah: white in a thick white square, every one the same."""

    def window(self, theme="dark"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=theme, recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        w.open_corner_list()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def badges(self, w):
        return [x for x in w.surah_list.findChildren(QtWidgets.QLabel)
                if x.objectName() == "surahNumber"]

    def test_every_one_of_the_114_is_the_same_square(self):
        """It used to be a fixed width and whatever height the row came out at, so 1 and 114
        sat in boxes of different shapes."""
        w = self.window()
        sizes = {(x.width(), x.height()) for x in self.badges(w)}
        self.assertEqual(114, len(self.badges(w)))
        self.assertEqual(1, len(sizes), f"the squares come in {len(sizes)} sizes: {sizes}")
        wide, tall = sizes.pop()
        self.assertEqual(wide, tall, "a square, not a rectangle")

    def test_the_number_and_its_outline_are_drawn_in_the_ink_colour(self):
        """Rendered: white on the dark screen, which is what was asked for, and black on the
        light one, where white would be invisible. Read off the pixels, not off the stylesheet."""
        for mode, want in (("dark", 255), ("light", 0)):
            w = self.window(mode)
            badge = self.badges(w)[0]
            image = badge.grab().toImage()
            edge = [QtGui.QColor(image.pixel(x, 1)).red() for x in range(4, badge.width() - 4)]
            self.assertTrue(edge, mode)
            near = sum(1 for v in edge if abs(v - want) < 60)
            self.assertGreater(near / len(edge), 0.9,
                               f"{mode}: the top of the outline is not the ink colour")

    def test_the_outline_is_thick_enough_to_read_across_a_room(self):
        from salaah.reading import NUMBER_LINE
        self.assertGreaterEqual(NUMBER_LINE, 3, "a hairline box is not what was asked for")
        w = self.window()
        badge = self.badges(w)[0]
        image = badge.grab().toImage()
        middle = badge.width() // 2
        run = 0
        for y in range(badge.height() // 2):
            if QtGui.QColor(image.pixel(middle, y)).red() > 195:
                run += 1
            elif run:
                break
        self.assertGreaterEqual(run, 3, f"the drawn outline is only {run}px thick")

    def test_the_numbers_are_no_longer_blue(self):
        from salaah.ui import LAPIS
        w = self.window("light")
        badge = self.badges(w)[0]
        image = badge.grab().toImage()
        blue = QtGui.QColor(LAPIS)
        for y in range(image.height()):
            for x in range(image.width()):
                c = QtGui.QColor(image.pixel(x, y))
                self.assertFalse(abs(c.red() - blue.red()) < 20 and abs(c.green() - blue.green()) < 20
                                 and abs(c.blue() - blue.blue()) < 20,
                                 f"still painting in the old blue at {x},{y}")


class SoundSettingsTogetherTest(unittest.TestCase):
    """The two settings that decide whether the mat makes a sound, in one column."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="light", recitation=True, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        w.open_settings()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def head(self, w, key):
        wanted = w.t(key)
        found = [x for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                 if x.objectName() == "settingHead" and x.text() == wanted]
        self.assertEqual(1, len(found), f"{key} is not on the screen once")
        return found[0]

    def test_the_call_to_prayer_moved_to_the_right_hand_column(self):
        w = self.window()
        screen = w.settings_screen
        middle = screen.width() / 2
        call = self.head(w, "settings.azaan")
        self.assertGreater(call.mapTo(screen, call.rect().center()).x(), middle,
                           "the call to prayer is still on the left")

    def test_it_sits_directly_below_the_recitation(self):
        w = self.window()
        screen = w.settings_screen
        call = self.head(w, "settings.azaan")
        recitation = self.head(w, "settings.recitation")
        self.assertGreater(call.mapTo(screen, call.rect().topLeft()).y(),
                           recitation.mapTo(screen, recitation.rect().topLeft()).y(),
                           "the call should come after the recitation, not before it")
        # Only the right-hand column: the left one runs down the page alongside, and its
        # headings sit between these two in height without being between them on the screen.
        middle = screen.width() / 2
        between = [x for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                   if x.objectName() == "settingHead"
                   and x.mapTo(screen, x.rect().center()).x() > middle
                   and recitation.mapTo(screen, recitation.rect().center()).y()
                   < x.mapTo(screen, x.rect().center()).y()
                   < call.mapTo(screen, call.rect().center()).y()]
        self.assertEqual([], [x.text() for x in between],
                         "something got in between the two sound settings")

    def test_the_switch_still_works_where_it_now_lives(self):
        w = self.window()
        knob = next(b for b in w.settings_screen.findChildren(QtWidgets.QAbstractButton)
                    if b.objectName() == "azaanSwitch")
        was = w.settings.azaan
        knob.click()
        settle()
        self.assertNotEqual(was, w.settings.azaan, "moving it broke it")


class TouchableSliderTest(unittest.TestCase):
    """The slider down the side of the lists is slid with a finger, not pointed at with a mouse."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def surahs(self, w):
        w.open_corner_list()
        settle()
        return w.surah_list

    def duas(self, w):
        w.open_section("duas")
        settle()
        return w.section_lists["duas"]

    def test_every_slider_on_the_mat_is_the_touchable_one(self):
        """THIS REVERSES A DECISION, and the two tests it replaces are the record of it.

        Until 1.95 Settings deliberately kept a 14px slider. The reason written down was that
        "widening every slider in the app would have eaten the settings columns for a screen
        nobody scrolls with a finger", and at the time that was a fair call. Harry asked for
        the three to match, so the old reason was measured rather than argued with, and it does
        not survive the measurement: SETTINGS DRAWS NO SLIDER AT ALL ON THE MAT. At 1920x1200,
        which is the mat, and at 1920x1080 and 1280x800, its content fits and the bar is never
        shown. It appears first at 1024x600. So the width being protected was the width of
        something that is not on the screen, and the columns it was protecting were never at
        risk on the device this runs on.

        What WAS on the screen and wrong: the Sources page had no rule of its own at all, so Qt
        drew it whatever it draws for a mouse. That is the thin slider anybody actually saw.

        Measured against LIST_BAR rather than a number written in here. It was exactly three
        times the settings one until Harry used it and asked for more, at which point a test
        saying "three times" failed on a change that was the point of the exercise.
        """
        from salaah.reading import LIST_BAR
        w = self.window()
        w.open_settings()
        settle()
        want = w.px(LIST_BAR)
        self.assertEqual(want, w.settings_scroll.verticalScrollBar().width(),
                         "Settings is off the shared rule again")
        for name, listing in (("surahs", self.surahs(w)), ("du'as", self.duas(w))):
            wide = listing.scroll.verticalScrollBar().width()
            self.assertEqual(want, wide, f"the {name} slider is {wide}px, not {want}")

    def test_settings_does_not_draw_a_slider_at_the_sizes_the_mat_runs_at(self):
        """The measurement the reversal above rests on, kept so it cannot quietly stop being
        true. If a later change makes Settings scroll on the mat, the width it scrolls at
        becomes a real question again and this is the test that says so."""
        w = self.window()
        for height in (1200, 1080, 800):
            w.resize(1920, height)
            settle()
            w.open_settings()
            settle()
            bar = w.settings_scroll.verticalScrollBar()
            self.assertFalse(bar.isVisible() and bar.maximum() > 0,
                             f"Settings now scrolls at 1920x{height}, so the width of its "
                             f"slider matters again -- see the test above")

    def test_the_rows_gave_up_the_width_and_kept_their_height(self):
        """What was asked for: narrower rectangles, same height. The lists resize to whatever
        the slider leaves, so this is what should have happened by itself."""
        w = self.window()
        for listing in (self.surahs(w), self.duas(w)):
            rows = [b for b in listing.findChildren(QtWidgets.QPushButton)
                    if b.objectName() == "surahRow"]
            self.assertTrue(rows)
            self.assertEqual({w.px(96)}, {b.height() for b in rows}, "the height should not move")
            edge = max(b.mapTo(listing, b.rect().topRight()).x() for b in rows)
            bar = listing.scroll.verticalScrollBar()
            self.assertLessEqual(edge, bar.mapTo(listing, bar.rect().topLeft()).x(),
                                 "a row runs under the slider instead of stopping short of it")

    def test_the_handle_is_a_finger_sized_target_and_is_actually_drawn(self):
        """Rendered: a slider styled to a width it then paints nothing into is not a target.
        The surah list is 114 rows, so its handle is as small as the handle ever gets."""
        w = self.window()
        listing = self.surahs(w)
        bar = listing.scroll.verticalScrollBar()
        self.assertTrue(bar.isVisible(), "114 surahs should need scrolling")
        self.assertGreaterEqual(bar.height(), w.px(300))
        image = bar.grab().toImage()
        rows_painted = 0
        for y in range(image.height()):
            across = sum(1 for x in range(image.width())
                         if QtGui.QColor(image.pixel(x, y)).lightness() > 90)
            if across > image.width() * 0.6:
                rows_painted += 1
        self.assertGreaterEqual(rows_painted, w.px(100),
                                f"only {rows_painted}px of handle is painted; it is a groove, "
                                f"not a handle")

    def test_the_slider_actually_scrolls_the_list(self):
        w = self.window()
        listing = self.surahs(w)
        bar = listing.scroll.verticalScrollBar()
        self.assertEqual(0, bar.value())
        self.assertGreater(bar.maximum(), 0)
        bar.setValue(bar.maximum())
        settle()
        self.assertEqual(bar.maximum(), bar.value(), "the slider did not take")

    def test_the_kalima_list_behind_the_arches_got_it_too(self):
        """The kalima are chosen off the mosque, but the list is still there when the drawing
        is missing, and it is the same widget -- so it should not be the one left behind."""
        w = self.window()
        # Shown directly: open_section puts the arches up instead, so going that way leaves the
        # list never laid out and its slider at an unrealised default width.
        listing = w.section_lists["kalima"]
        w.stack.setCurrentWidget(w.corner_page)
        w.corner_screen.setCurrentWidget(listing)
        settle()
        self.assertTrue(listing.isVisible(), "the list was never actually shown")
        self.assertEqual("listScroll", listing.scroll.objectName(), "the rule would not reach it")
        # Six kalima fit without scrolling, so the slider is hidden and its width means nothing
        # until it is asked for. Turned on, it should be the same wide one as the others.
        listing.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOn)
        settle()
        from salaah.reading import LIST_BAR
        bar = listing.scroll.verticalScrollBar()
        self.assertTrue(bar.isVisible())
        self.assertEqual(w.px(LIST_BAR), bar.width())


class MuezzinPictureTest(unittest.TestCase):
    """The drawing is used as a stencil, so what matters is its shape and that it can be
    filled. A picture saved the ordinary way -- black lines on white -- would be a black
    rectangle on a black box, which the eye would notice and no other test would."""

    def test_the_picture_is_a_stencil_and_not_a_flat_drawing(self):
        picture = ASSETS / "azaan" / "muezzin.png"
        self.assertTrue(picture.is_file())
        image = QtGui.QImage(str(picture))
        self.assertFalse(image.isNull())
        self.assertTrue(image.hasAlphaChannel(), "no alpha: there is no shape to fill")
        clear = ink = 0
        colours = set()
        for y in range(0, image.height(), 5):
            for x in range(0, image.width(), 5):
                c = QtGui.QColor(image.pixelColor(x, y))
                if c.alpha() < 20:
                    clear += 1
                elif c.alpha() > 230:
                    ink += 1
                    colours.add((c.red(), c.green(), c.blue()))
        self.assertGreater(clear, ink, "most of the picture should be see-through")
        self.assertGreater(ink, 0, "nothing is drawn")
        self.assertEqual({(255, 255, 255)}, colours,
                         "the ink must be white so the screen can tint it to any colour")

    def test_it_is_the_tall_shape_the_box_gives_it(self):
        """Tall, and big enough for the largest the box ever draws it -- which is about four
        hundred pixels across on a 1920 monitor, so this has headroom. It used to ask for eight
        hundred pixels of height, back when the drawing shipped at whatever size it arrived in;
        the one it wants now is cut down on purpose, because seven megabytes of muezzin is a
        download every mat pays for and nobody can see."""
        image = QtGui.QImage(str(ASSETS / "azaan" / "muezzin.png"))
        self.assertGreater(image.height(), image.width(), "an upright arch, not a wide one")
        self.assertGreaterEqual(image.width(), 430, "too small to draw at the size of the box")


class DrawnForTheDarkTest(unittest.TestCase):
    """The artwork says which screen it was drawn for, and the screen does the rest.

    The first mosque was dark ink on a light ground and is turned inside out after dark. The
    ones drawn since are white lines on black. Without the drawing saying so, the night screen
    turned the new artwork inside out and showed the negative of what was drawn."""

    def window(self, mode="dark"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=mode, recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        w.leave_welcome()      # past the front door: these look at the mosque behind it
        w.veil.stop()          # and at the screen, not at the walk laid over it
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_both_drawings_say_they_were_made_for_the_dark_screen(self):
        import json
        for folder in ("mosque", "kalima"):
            described = json.loads((ASSETS / folder / "mosque.json").read_text(encoding="utf-8"))
            self.assertEqual("dark", described.get("drawn"), folder)

    def test_it_is_shown_as_drawn_after_dark_and_turned_over_by_day(self):
        self.assertFalse(self.window("dark").mosque.flipped, "the night screen is the one it suits")
        self.assertTrue(self.window("light").mosque.flipped, "and the white one is not")

    def test_the_clock_reads_against_whatever_the_dome_is(self):
        """CHANGED IN 1.63, because the dome changed under it.

        The old main page drew its dome as an OUTLINE -- a hole in the picture -- so after
        dark the dome was dark and the time had to be white on it. Harry's new one draws the
        dome SOLID, so after dark it is white and the same white numerals would vanish. Both
        are right about their own drawing, and neither is the thing worth pinning.

        What is worth pinning is that you can read the time: whichever way round the drawing
        is, and whichever screen it is on, the numerals stand clear of the dome behind them.
        Measured by turning the time on and off and comparing, because counting bright pixels
        in the box reported plenty of light from the dome's own edge even with the numerals
        painted invisible -- which is how the first version of this test fooled itself.
        """
        for mode in ("dark", "light"):
            with self.subTest(mode):
                w = self.window(mode)
                m = w.mosque
                m.sky.birds = []
                m.sky.stars = []
                _, origin, scale = m.placement()
                box = m.clock_box
                m.set_time("")
                settle()
                bare = w.grab().toImage()
                m.set_time("14:28")
                settle()
                shown = w.grab().toImage()

                dome = QtGui.QColor(bare.pixel(
                    origin.x() + int((box.x() + box.width() * 0.05) * scale),
                    origin.y() + int((box.y() + box.height() * 0.5) * scale))).lightness()
                changed, wrong_way = 0, 0
                for y in range(origin.y() + int(box.y() * scale),
                               origin.y() + int((box.y() + box.height()) * scale), 2):
                    for x in range(origin.x() + int(box.x() * scale),
                                   origin.x() + int((box.x() + box.width()) * scale), 2):
                        was = QtGui.QColor(bare.pixel(x, y)).lightness()
                        now = QtGui.QColor(shown.pixel(x, y)).lightness()
                        if abs(now - was) <= 60:
                            continue
                        # Away from the dome is the right way: dark ink on a light dome,
                        # light ink on a dark one.
                        if (now < was) == (dome > 128):
                            changed += 1
                        else:
                            wrong_way += 1
                self.assertGreater(changed, 200,
                                   f"{mode}: the time does not stand out from the dome")
                self.assertGreater(changed, wrong_way * 4,
                                   f"{mode}: the time is painted into the dome, not on it")

    def test_an_old_style_drawing_would_still_be_turned_over_after_dark(self):
        """The flag defaults to the way the first mosque was made, so artwork without it keeps
        the behaviour it has always had."""
        from salaah.mosque import MosqueScreen
        screen = MosqueScreen(ASSETS)
        self.assertTrue(screen.drawn_dark, "this one is dark-drawn")
        screen.drawn_dark = False                     # as an old drawing would load
        from salaah import theme
        self.assertEqual(theme.palette().dark, screen.flipped,
                         "without the flag, dark mode is what turns it over")
        screen.deleteLater()


class NewMosqueArtTest(unittest.TestCase):
    """The two new drawings: five named arches and six numbered ones, with the sky knocked out."""

    def window(self, mode="dark"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=mode, recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        w.leave_welcome()      # past the front door: these look at the mosque behind it
        w.veil.stop()          # and at the screen, not at the walk laid over it
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_the_front_door_still_has_its_five_prayers_in_order(self):
        w = self.window()
        self.assertEqual(["fajr", "dhuhr", "asr", "maghrib", "isha"],
                         [a.prayer for a in w.mosque.arches])
        lefts = [a.box.x() for a in w.mosque.arches]
        self.assertEqual(lefts, sorted(lefts), "the arches are not left to right")

    def test_the_kalima_menu_has_its_six(self):
        w = self.window()
        w.open_section("kalima")
        settle()
        self.assertEqual(["1", "2", "3", "4", "5", "6"],
                         [a.prayer for a in w.arch_menus["kalima"].mosque.arches])

    def test_the_sky_is_see_through_so_what_is_behind_it_shows(self):
        """What Harry asked about: the sun, moon, stars and birds are drawn behind the mosque,
        so an opaque drawing hides them. Checked by painting the sky full of stars and counting
        how many survive."""
        w = self.window()
        m = w.mosque
        m.sky.birds = []
        m.set_sky(False, 0.5)
        self.assertGreater(len(m.sky.stars), 20, "there should be stars to see")

        # Counted by taking the stars away, not by counting bright pixels: the building's own
        # white outlines run through the same rows, and with the sky painted solid they alone
        # were enough to pass. What matters is whether anything BEHIND the drawing gets through.
        stars = list(m.sky.stars)
        m.sky.stars = []
        m.update()
        settle()
        bare = w.grab().toImage()
        m.sky.stars = stars
        m.update()
        settle()
        starry = w.grab().toImage()
        showing = 0
        for y in range(120, m.height()):
            for x in range(0, w.width()):
                if (QtGui.QColor(starry.pixel(x, y)).lightness()
                        - QtGui.QColor(bare.pixel(x, y)).lightness()) > 30:
                    showing += 1
        self.assertGreater(showing, 150,
                           f"only {showing} pixels of sky get through; the drawing covers it")

    def test_the_minaret_boxes_were_written_and_land_on_the_minarets(self):
        """They used to be left empty by the builder, which is not an error anywhere -- the
        glow would simply never appear and nothing would say why."""
        w = self.window()
        m = w.mosque
        self.assertEqual({"left", "right"}, set(m.minarets))
        for side, box in m.minarets.items():
            self.assertGreater(box.width(), 0, side)
            self.assertGreater(box.height(), 0, side)
            self.assertLess(box.y(), m.picture.height() * 0.45, f"{side} is not near the top")
        left, right = m.minarets["left"], m.minarets["right"]
        self.assertLess(left.center().x(), m.picture.width() * 0.3)
        self.assertGreater(right.center().x(), m.picture.width() * 0.7)

    def test_the_prayer_whose_time_it_is_is_picked_out_in_green(self):
        """CHANGED IN 1.63. The names used to be part of the drawing and were lifted off it
        with the arch's mask; they come from the pack now and are painted on. The claim is
        unchanged and is checked here the same way it always should have been -- by looking at
        the arch on the screen -- with the detail of HOW in MainScreenMarkTest.
        """
        w = self.window()
        m = w.mosque
        held = m.sky.now()
        frozen = mock.patch.object(type(m.sky), "now", staticmethod(lambda: held))
        frozen.start()
        self.addCleanup(frozen.stop)
        m.flutter.stop()
        from salaah.mosque import GREEN, GREEN_DARK
        want = GREEN_DARK if m.flipped else GREEN

        def green_in(prayer):
            shot = m.grab().toImage()
            _, origin, scale = m.placement()
            arch = next(a for a in m.arches if a.prayer == prayer)
            box = QtCore.QRect(origin.x() + int(arch.box.x() * scale),
                               origin.y() + int(arch.box.y() * scale),
                               int(arch.box.width() * scale), int(arch.box.height() * scale))
            found = 0
            for y in range(box.top(), box.bottom(), 2):
                for x in range(box.left(), box.right(), 2):
                    c = QtGui.QColor(shot.pixel(x, y))
                    if (abs(c.red() - want.red()) <= 40
                            and abs(c.green() - want.green()) <= 40
                            and abs(c.blue() - want.blue()) <= 40):
                        found += 1
            return found

        m.set_lit("dhuhr")
        settle()
        self.assertGreater(green_in("dhuhr"), 30, "Dhuhr is not picked out when it is its time")
        self.assertLess(green_in("fajr"), 5, "Fajr is green and it is not its time")
        m.set_lit("fajr")
        settle()
        self.assertGreater(green_in("fajr"), 30, "the green did not move with the hour")
        self.assertLess(green_in("dhuhr"), 5, "Dhuhr stayed green after its time passed")


class MovingMuezzinTest(unittest.TestCase):
    """The call screen plays a little film of the muezzin instead of a still."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=False, place="Bury", azaan=True),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def box(self, w):
        from salaah.call import CallBox
        b = CallBox(w, "fajr", "azaan-fajr.mp3", w.adhan)
        b.show()
        settle()
        self.addCleanup(lambda: (b.close(), b.deleteLater(), settle()))
        return b

    def test_there_is_a_film_and_it_is_running_while_the_call_is_up(self):
        w = self.window()
        self.assertTrue(w.adhan.film().is_file())
        box = self.box(w)
        self.assertIsNotNone(box.drawing.film, "the still is being shown instead of the film")
        self.assertGreater(box.drawing.film.frameCount(), 1)
        self.assertTrue(box.drawing.moving, "the film is loaded but not playing")

    def test_the_frames_are_different_pictures_and_each_one_gets_painted(self):
        """A film that loads, reports six frames and paints the same one six times is a still
        with extra steps. Compared over the whole widget: the frames sit in the middle of a
        tall box, so the first few thousand bytes are the black margin above them and match
        whatever is playing."""
        w = self.window()
        box = self.box(w)
        # Stopped before it is stepped. The film is playing -- the test above insists on it --
        # and settle() gives its own timer a chance to run, so a frame asked for by number can
        # have moved on by the time the grab happens. Two grabs then land on one frame and the
        # count of different pictures comes up short. It failed that way once in a full suite
        # and passed three times out of three on its own, which is what a race looks like.
        box.drawing.film.stop()
        drawn = []
        for i in range(box.drawing.film.frameCount()):
            box.drawing.film.jumpToFrame(i)
            settle()
            image = box.drawing.grab().toImage()
            # Sampled pixel by pixel rather than hashing the raw buffer: the two Qt kits hand
            # back different things from bits(), and PyQt6's has no tobytes().
            drawn.append(tuple(image.pixel(x, y)
                               for y in range(0, image.height(), 7)
                               for x in range(0, image.width(), 7)))
        self.assertEqual(len(drawn), len(set(drawn)),
                         f"only {len(set(drawn))} of {len(drawn)} frames are different pictures")

    def test_it_stops_when_the_call_is_over(self):
        """Nothing is on screen to repaint, and a film left running on a Pi is a timer waking
        the processor five times a second for nobody."""
        w = self.window()
        box = self.box(w)
        self.assertTrue(box.drawing.moving)
        box.accept()
        settle()
        self.assertFalse(box.drawing.moving, "the film is still running with the box closed")

    def test_with_no_film_it_falls_back_to_the_still_and_tints_it(self):
        from salaah.call import Drawing
        w = self.window()
        plain = Drawing(w.adhan.picture(), "#FFFFFF", film=ASSETS / "azaan" / "no-such-film.gif")
        self.assertIsNone(plain.film)
        self.assertTrue(plain.there, "with no film it should still show the still")
        plain.resize(300, 380)
        image = plain.grab().toImage()
        white = sum(1 for y in range(0, image.height(), 3) for x in range(0, image.width(), 3)
                    if QtGui.QColor(image.pixel(x, y)).lightness() > 230)
        self.assertGreater(white, 50, "the still was not drawn")
        plain.deleteLater()

    def test_the_film_is_not_flattened_by_the_tinting_the_still_needs(self):
        """The still is a stencil filled with one colour. Doing that to a film would make every
        frame the same silhouette, which is the opposite of the point."""
        w = self.window()
        box = self.box(w)
        image = box.drawing.grab().toImage()
        shades = set()
        for y in range(0, image.height(), 4):
            for x in range(0, image.width(), 4):
                c = QtGui.QColor(image.pixel(x, y))
                if c.lightness() > 40:
                    shades.add(c.lightness() // 32)
        self.assertGreater(len(shades), 2,
                           "the film came out in one flat shade; it is being used as a stencil")

    def test_hiding_it_any_other_way_also_stops_the_film(self):
        """Pressing Stop is not the only way the box leaves the screen -- the window can go, or
        another screen can come up over it. The film has to notice all of them, which is why it
        stops on being hidden rather than only on the box being dismissed."""
        w = self.window()
        box = self.box(w)
        self.assertTrue(box.drawing.moving)
        box.hide()                       # not accept(): no dismissing, just off the screen
        settle()
        self.assertFalse(box.drawing.moving, "the film ran on with nothing to paint on")

    def test_a_second_call_lets_go_of_the_first_box(self):
        """Five calls a day for months. The boxes used to be forgotten rather than dropped,
        which was harmless when a box was a few labels and is not now one carries a film."""
        from salaah.call import CallBox
        w = self.window()
        for prayer in ("dhuhr", "asr", "maghrib"):
            w.call_to_prayer(prayer)
            settle()
            w.end_the_call()
            settle()
        alive = [b for b in w.findChildren(CallBox)]
        self.assertEqual([], alive, f"{len(alive)} call boxes are still about")
        self.assertIsNone(w.call_box)

    def test_the_box_up_now_is_the_only_one(self):
        from salaah.call import CallBox
        w = self.window()
        w.call_to_prayer("dhuhr")
        settle()
        w.call_to_prayer("asr")          # a second call while the first box is still up
        settle()
        self.assertEqual(1, len(w.findChildren(CallBox)), "the first box was left behind")


class CleanArtworkTest(unittest.TestCase):
    """The drawings are two-tone. The first pair had a glow painted round every line, and where
    the sky was knocked out from under it a grey fringe was left standing on the black."""

    def solid_shades(self, folder):
        image = QtGui.QImage(str(ASSETS / folder / "mosque.png"))
        self.assertFalse(image.isNull(), folder)
        mid = solid = 0
        for y in range(0, image.height(), 3):
            for x in range(0, image.width(), 3):
                c = QtGui.QColor(image.pixelColor(x, y))
                if c.alpha() < 200:
                    continue
                solid += 1
                if 40 < c.lightness() < 215:
                    mid += 1
        return mid, solid

    def test_the_drawings_are_black_and_white_and_not_much_in_between(self):
        for folder in ("mosque", "kalima"):
            mid, solid = self.solid_shades(folder)
            self.assertGreater(solid, 1000, folder)
            share = mid / solid
            self.assertLess(share, 0.12,
                            f"{folder}: {share*100:.1f}% of what is drawn is a half shade -- "
                            f"that is the glow that made the first pair look muddy")

    def test_the_drawings_that_are_compared_share_a_canvas(self):
        """The mosques that read as the same building seen twice are lined up against each
        other, so they must be the same size.

        The kalima menu rejoined them in 1.64; it was the last of the old artwork, and for one
        version it was left out of this with a note saying why.
        """
        # The front door was one of these until 1.76, when it stopped being a mosque.
        folders = ["mosque", "kalima"] + [f"prayers/{p}" for p in PRAYERS]
        sizes = {QtGui.QImage(str(ASSETS / f / "mosque.png")).size() for f in folders}
        self.assertEqual(1, len(sizes), f"the mosques are drawn at different sizes: {sizes}")
        shape = next(iter(sizes))
        self.assertGreater(shape.width() / shape.height(), 1.85,
                           "they should be cut to the shape of the screen")


class ArchFinderTest(unittest.TestCase):
    """Two rules the builder needed for the new drawings, tested on shapes made here rather
    than on the artwork, so what is being checked is the rule and not one picture."""

    @staticmethod
    def grey(shapes, size=(400, 300)):
        """A black field with white rectangles punched in it, as an image the finder can read.

        A shape given as (x0, y0, x1, y1, "ring") is drawn as an outline with a gap inside it,
        which is how a double-outlined panel actually looks. Filling one rectangle inside
        another just makes one bigger white blob -- which is what the first version of this
        did, so the nesting rule it was meant to test was never exercised.
        """
        from PIL import Image, ImageDraw
        image = Image.new("L", size, 0)
        draw = ImageDraw.Draw(image)
        for shape in shapes:
            x0, y0, x1, y1 = shape[:4]
            if len(shape) > 4 and shape[4] == "ring":
                draw.rectangle([x0, y0, x1 - 1, y1 - 1], outline=255, width=6)
            else:
                draw.rectangle([x0, y0, x1 - 1, y1 - 1], fill=255)
        return image

    def finder(self):
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "arch_menu", Path(__file__).resolve().parent.parent / "tools" / "build_arch_menu.py")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    def test_a_wide_panel_is_found_only_when_the_rule_is_relaxed(self):
        """The default throws away anything wider than it is tall -- the slots in a minaret,
        the line under the plinth. The welcome screen's opening is exactly that shape."""
        tools = self.finder()
        panel = self.grey([(40, 180, 360, 260)])         # 320 wide, 80 tall
        self.assertEqual([], tools.arches_in(panel, tools.SMALLEST),
                         "a flat panel should not pass for an arch by default")
        self.assertEqual(1, len(tools.arches_in(panel, tools.SMALLEST, 0.2)),
                         "and should be found once the rule is relaxed")

    def test_a_shape_inside_another_is_one_opening_not_two(self):
        """A panel drawn with a double outline appears twice: the border and the fill within
        it. The welcome drawing has one, and the builder refused it as two openings."""
        tools = self.finder()
        # An outline with a filled panel inside it and a black gap between: two separate white
        # shapes, one wholly within the other.
        nested = self.grey([(40, 100, 360, 260, "ring"), (60, 120, 340, 240)])
        found = tools.arches_in(nested, tools.SMALLEST, 0.2)
        self.assertEqual(1, len(found), f"got {found}")
        self.assertEqual((40, 100, 360, 260), found[0], "the outer shape is the opening")

    def test_arches_standing_side_by_side_are_left_alone(self):
        """The rule above must not swallow a row of arches, which is what the other two
        drawings are."""
        tools = self.finder()
        row = self.grey([(30 + i * 90, 80, 100 + i * 90, 260) for i in range(4)])
        found = tools.arches_in(row, tools.SMALLEST)
        self.assertEqual(4, len(found), f"got {found}")
        self.assertEqual([b[0] for b in found], sorted(b[0] for b in found), "left to right")



class ArtworkCacheTest(unittest.TestCase):
    """The drawings are read once and shared. Three mosques, rebuilt on every settings change,
    were re-reading about twenty megabytes of picture each time."""

    def test_the_same_drawing_is_not_read_twice(self):
        """The two screens should be handed the very same object. Comparing the pictures'
        contents, or their cacheKey, proves nothing: Qt keeps a cache of its own for images
        read from a file, so two pixmaps loaded separately can come back identical anyway.
        Identity is the thing that can only be true if this cache handed out what it had."""
        from salaah import mosque
        a = mosque.MosqueScreen(ASSETS)
        b = mosque.MosqueScreen(ASSETS)
        self.addCleanup(lambda: (a.deleteLater(), b.deleteLater(), APP.processEvents()))
        self.assertTrue(a.ready and b.ready)
        self.assertIs(a.picture, b.picture, "the drawing was read again for the second screen")
        # The masks each arch used to carry were checked here too. Nothing reads one since
        # 1.63 -- the lettering they existed for is not in the drawing any more -- so they are
        # not opened at all, which is the same saving by a shorter road.
        for one, two in zip(a.arches, b.arches):
            self.assertFalse(hasattr(one, "mask"), f"{one.prayer} is loading a mask again")

    def test_rebuilding_the_artwork_is_picked_up_and_not_served_stale(self):
        """Harry rebuilds these drawings often. A cache keyed on the file name alone would go
        on handing out the old picture until the app was restarted."""
        import shutil, tempfile
        from salaah import mosque
        spare = Path(tempfile.mkdtemp())
        self.addCleanup(lambda: shutil.rmtree(spare, ignore_errors=True))
        shutil.copytree(ASSETS / "mosque", spare / "mosque")
        first = mosque.MosqueScreen(spare)
        self.addCleanup(lambda: (first.deleteLater(), APP.processEvents()))
        self.assertTrue(first.ready)
        was = first.picture.size()

        # A different drawing on the same canvas, made rather than borrowed. It used to borrow
        # the kalima one, which worked while the two were the same size and stopped when
        # Harry's new main page came in at 1396x733 against the kalima's 1624x853 -- the test
        # then failed for a reason that had nothing to do with the cache it was watching.
        from salaah.qt import QtGui
        turned = QtGui.QImage(str(spare / "mosque" / "mosque.png")).mirrored(True, False)
        self.assertTrue(turned.save(str(spare / "mosque" / "mosque.png")))
        import os, time
        later = time.time() + 5
        os.utime(spare / "mosque" / "mosque.png", (later, later))
        again = mosque.MosqueScreen(spare)
        self.addCleanup(lambda: (again.deleteLater(), APP.processEvents()))
        self.assertNotEqual(first.picture.cacheKey(), again.picture.cacheKey(),
                            "the old picture was handed out again after the file changed")
        self.assertEqual(was, again.picture.size(), "same canvas, different drawing")


class BannerLeadsWithThePinTest(unittest.TestCase):
    """What the black strip across the top says, and in what order: a pin, the place in blue,
    then the five prayer times.

    Measured on the FRONT DOOR until 1.76, which is where the strip was first put and the
    first place anybody saw it. The front door is one picture now and carries no strip at all,
    so the mosque behind it is where these are read -- the same strip, built by the same
    make_banner, and the one every other screen gets a copy of.
    """

    def window(self, **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(**{"theme": "dark", "recitation": False, "place": "Bury",
                                   **settings}),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(1920, 1080)
        w.show()
        w.leave_welcome()          # the strip lives on the mosque, not on the front door
        w.veil.stop()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def strip(self, w, page):
        strips = [x for x in page.findChildren(QtWidgets.QWidget)
                  if x.objectName() == "banner"]
        self.assertEqual(1, len(strips), "one strip, no more and no fewer")
        return strips[0]

    def test_the_strip_names_the_place_and_all_five_prayers(self):
        w = self.window()
        front = self.strip(w, w.home)
        said = [x for x in front.findChildren(QtWidgets.QLabel)
                if x.objectName() == "bannerText"]
        self.assertEqual(1, len(said))
        self.assertIn("Bury", said[0].text())
        for prayer in ("fajr", "dhuhr", "asr", "maghrib", "isha"):
            self.assertIn(w.t(f"prayer.{prayer}"), said[0].text(), prayer)
        self.assertEqual(1, len(front.findChildren(QtWidgets.QSlider)), "and how loud it is")
        self.assertEqual(0, front.mapTo(w.home, QtCore.QPoint(0, 0)).y(),
                         "the strip is the top of the screen")

    def test_the_pin_comes_before_the_place(self):
        w = self.window()
        front = self.strip(w, w.home)
        pins = [x for x in front.findChildren(QtWidgets.QLabel) if x.objectName() == "bannerPin"]
        self.assertEqual(1, len(pins), "no pin on the strip")
        pin, words = pins[0], next(x for x in front.findChildren(QtWidgets.QLabel)
                                   if x.objectName() == "bannerText")
        self.assertFalse(pin.pixmap().isNull(), "the pin is empty")
        self.assertLess(pin.mapTo(front, pin.rect().center()).x(),
                        words.mapTo(front, QtCore.QPoint(0, 0)).x(),
                        "the pin should come before the words, not after them")

    def test_every_strip_has_one(self):
        w = self.window()
        pins = [x for x in w.findChildren(QtWidgets.QLabel) if x.objectName() == "bannerPin"]
        self.assertEqual(len(w.banner_labels), len(pins),
                         "a strip somewhere is missing its pin")

    def test_the_place_is_written_in_red_and_the_times_are_not(self):
        """RED SINCE 2.23, AND IT USED TO BE BLUE, which is worth saying because the blue was
        not an accident either.

        2.07 moved this off a hardcoded constant and onto the strip's own lapis, so that the
        place followed the palette into either theme. That was the right fix for the problem
        it had. What it never settled was why the place was a colour of its OWN: lapis is
        used for nothing a hand goes to, so the one thing on the strip you can press -- the
        place, which opens the location screen -- was the one colour that said nothing about
        being pressable.

        Harry, 12 November 2026: "change font colour of location and the icon to the same red
        of main screen button". So the pin and the name are now BRICK, the colour of Menu,
        Main screen, the leave buttons and the cog, and the times keep the strip's own ink.
        """
        from salaah.ui import BRICK
        w = self.window()
        said = next(x for x in w.home.findChildren(QtWidgets.QLabel)
                    if x.objectName() == "bannerText").text()
        self.assertIn(f'color:{BRICK}">Bury</td>', said)
        self.assertEqual(1, said.upper().count(BRICK.upper()),
                         "the prayer times went red as well")

    def test_the_red_reads_on_the_strip_in_either_theme(self):
        """The place name lost a guard when it stopped being lapis, so here it is again.

        BRICK is a constant rather than a palette entry, so it does NOT follow the strip from
        black to white -- the same red sits on both. That is the thing worth checking: a
        colour that cannot move has to work in both places or it is only working in one.
        """
        from salaah import theme
        from salaah.ui import BRICK
        red = QtGui.QColor(BRICK)
        self.assertGreater(red.red(), red.green() + 60, "that is not a red")
        self.assertGreater(red.red(), red.blue() + 60, "that is not a red")
        for dark in (True, False):
            theme.set_dark(dark)
            with self.subTest("dark mat" if dark else "light mat"):
                paper = QtGui.QColor(theme.palette().paper)
                self.assertGreater(abs(red.lightness() - paper.lightness()), 60,
                                   "the red does not read against the strip behind it")

    def test_the_blue_is_a_blue_and_reads_on_the_strip_behind_it(self):
        """Lapis is no longer the place name's colour -- it is the slider's fill and the dots
        on the globe -- but it is still a palette colour that has to read on the strip.

        It compares against the palette, so it follows wherever the palette goes: set the
        strip's lapis to off-white and only the floors below catch it.

        THE DIRECTION IS CHECKED PER THEME, not once at the end. It used to finish with a flat
        "lightness > 110", which was true of both values while the strip was the other theme
        and is false of the light theme's #274B8F now the strip is the mat's own. A floor that
        only holds for one of the two colours it is applied to is not a rule; what is actually
        wanted is that each lapis goes the opposite way from the paper it sits on.
        """
        from salaah import theme
        for dark in (True, False):
            theme.set_dark(dark)
            with self.subTest("dark mat" if dark else "light mat"):
                strip = theme.palette()
                blue, paper = QtGui.QColor(strip.lapis), QtGui.QColor(strip.paper)
                self.assertGreater(blue.blue(), blue.red() + 60, "that is not a blue")
                self.assertGreater(blue.blue(), blue.green() + 40, "that is not a blue")
                self.assertGreater(abs(blue.lightness() - paper.lightness()), 60,
                                   "the blue does not read against the strip behind it")
                if dark:
                    self.assertGreater(blue.lightness(), 110,
                                       "too dark to read on a black strip")
                else:
                    self.assertLess(blue.lightness(), 145,
                                    "too pale to read on a white strip")

    def test_the_place_is_painted_red_on_the_screen(self):
        """Rendered: rich text that names a colour and then does not use it is a real enough
        mistake, and only the pixels say. Red since 2.23 -- see the test above for why the
        blue it replaced was not an accident either."""
        from salaah.ui import BRICK
        w = self.window()
        front = self.strip(w, w.home)
        words = next(x for x in front.findChildren(QtWidgets.QLabel)
                     if x.objectName() == "bannerText")
        image = words.grab().toImage()
        want = QtGui.QColor(BRICK)
        # Near enough the exact colour, not merely reddish. White lettering carries coloured
        # fringes from the antialiasing, and a loose test counted those and passed on a strip
        # with none of the colour on it at all.
        red = sum(1 for y in range(image.height()) for x in range(image.width())
                  if (abs(QtGui.QColor(image.pixel(x, y)).red() - want.red()) < 10
                      and abs(QtGui.QColor(image.pixel(x, y)).green() - want.green()) < 10
                      and abs(QtGui.QColor(image.pixel(x, y)).blue() - want.blue()) < 10))
        self.assertGreater(red, 150, "nothing on the strip is painted in the red")


class MapPinTest(unittest.TestCase):
    """The pin is drawn in code. The picture that was sent over is a stock-library preview with
    a watermark down its left edge, which has no business on a mat somebody owns."""

    def test_it_is_a_round_head_with_a_hole_and_a_point(self):
        from salaah.ui import map_pin
        image = map_pin(240, "#8FB1F0").toImage()
        self.assertEqual(0, QtGui.QColor(image.pixelColor(120, 90)).alpha(),
                         "the middle of the head should be a hole")
        self.assertEqual(255, QtGui.QColor(image.pixelColor(120, 30)).alpha(), "the head")
        self.assertEqual(255, QtGui.QColor(image.pixelColor(120, 225)).alpha(), "the point")
        self.assertEqual(0, QtGui.QColor(image.pixelColor(12, 225)).alpha(),
                         "it should taper: the bottom corners are empty")

    def test_it_takes_the_colour_it_is_given(self):
        from salaah.ui import map_pin
        for colour in ("#8FB1F0", "#B4443A"):
            image = map_pin(120, colour).toImage()
            got = QtGui.QColor(image.pixelColor(60, 15))
            self.assertEqual(QtGui.QColor(colour).name(), got.name(), colour)

    def test_it_is_drawn_rather_than_carried_as_a_picture(self):
        self.assertFalse((ASSETS / "pin.png").exists())
        self.assertFalse(list(ASSETS.glob("**/*pin*")), "a pin picture crept into the assets")

    # Harry's shape, since 1.64. The outline is a table of numbers traced off the drawing he
    # sent, so what these watch for is a table that has been mangled -- a row out of order, a
    # column swapped, a stray value -- rather than the drawing itself, which is not in the
    # repository and should not be.

    @staticmethod
    def silhouette(size=240):
        from salaah.ui import map_pin
        image = map_pin(size, "#8FB1F0").toImage()
        rows = []
        for y in range(size):
            on = [x for x in range(size) if QtGui.QColor(image.pixelColor(x, y)).alpha() > 128]
            rows.append((on[0], on[-1]) if on else None)
        return rows

    def test_it_is_the_same_on_both_sides(self):
        """Only half the outline is written down, so a bug in the mirroring would show here
        and nowhere else."""
        size = 240
        for y, span in enumerate(self.silhouette(size)):
            if span is None:
                continue
            left, right = span
            middle = (left + right) / 2
            self.assertLess(abs(middle - (size - 1) / 2), 1.5,
                            f"row {y} is off centre: {left}-{right}")

    def test_it_is_widest_about_a_third_of_the_way_down(self):
        """A teardrop, not a circle and not a triangle: the head is in the upper part and the
        taper is the long way. Table rows out of order would move the waist."""
        rows = [(y, s) for y, s in enumerate(self.silhouette()) if s is not None]
        widest = max(rows, key=lambda r: r[1][1] - r[1][0])[0]
        self.assertTrue(0.28 < widest / 240 < 0.45,
                        f"the widest part is {widest / 240:.2f} of the way down")

    def test_below_the_waist_it_only_narrows(self):
        """All the way to a point, on each side separately.

        Each side, not the overall width: a bulge down one edge leaves the width shrinking all
        the way, because the other edge is still coming in faster than the bulge goes out. The
        first version of this measured the width and a deliberate bulge walked straight past it.
        """
        size = 240
        rows = [(y, s) for y, s in enumerate(self.silhouette(size)) if s is not None]
        widest = max(rows, key=lambda r: r[1][1] - r[1][0])[0]
        below = [(y, s) for y, s in rows if y > widest + 4]
        middle = (size - 1) / 2
        # Against the narrowest it has been, not against the row above. Row by row, a bulge
        # that comes on gradually never widens by more than a pixel at a time and walks
        # straight through: a deliberate one nine pixels deep did exactly that, because it
        # arrived over five rows. Once an edge has come in to X it may not go back out past X.
        tightest = {"left": size, "right": size}
        for y, (left, right) in below:
            for side, out in (("left", middle - left), ("right", right - middle)):
                self.assertLessEqual(out, tightest[side] + 2,
                                     f"the {side} edge is back out to {out:.0f} at row {y} "
                                     f"after coming in to {tightest[side]:.0f}")
                tightest[side] = min(tightest[side], out)
        self.assertLess(below[-1][1][1] - below[-1][1][0], 24,
                        "it should come to a point, not a stump")

    def test_the_hole_sits_inside_the_head(self):
        rows = self.silhouette()
        from salaah.ui import map_pin
        image = map_pin(240, "#8FB1F0").toImage()
        clear = [(x, y) for y in range(240) for x in range(240)
                 if rows[y] is not None and rows[y][0] < x < rows[y][1]
                 and QtGui.QColor(image.pixelColor(x, y)).alpha() < 128]
        self.assertTrue(clear, "there is no hole in the head")
        down = sum(y for _, y in clear) / len(clear) / 240
        self.assertTrue(0.25 < down < 0.45, f"the hole is {down:.2f} of the way down")


class BannerStripTest(unittest.TestCase):
    """The black strip across the top, which every screen shares and which therefore has to
    look the same on every screen."""

    def window(self, lang="en", wide=1920, side=False):
        # side=False by default, which is the TIGHTER strip: with the 7" screen attached the
        # cog lives over there, and the sixty pixels that frees were enough to hide the
        # clipping this class exists to catch.
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", lang=lang, recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=side)
        w.resize(wide, 1080)
        w.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    @staticmethod
    def strip(page):
        return next((c for c in page.findChildren(QtWidgets.QWidget)
                     if c.objectName() == "banner"), None)

    def every_screen(self, w):
        """The strip on each of the screens that carries one, by name."""
        out = {}
        w.stack.setCurrentWidget(w.welcome)
        settle()
        out["the front door"] = self.strip(w.welcome)
        w.stack.setCurrentWidget(w.home)
        settle()
        out["the mosque"] = self.strip(w.home)
        w.open_prayer("isha")
        settle()
        out["a prayer's units"] = self.strip(w.pick)
        w.open_corner("quran")
        settle()
        out["the Qur'an"] = self.strip(w.stack.currentWidget())
        w.open_corner("kalima")
        settle()
        out["the kalima menu"] = self.strip(w.stack.currentWidget())
        return {name: bar for name, bar in out.items() if bar is not None}

    def test_the_strip_is_the_same_height_everywhere(self):
        """Harry: the one over the prayer menu is "slightly narrower than the others". It was
        the other way round -- the screens carrying a Main screen button came out five pixels
        TALLER, because the button is taller than the volume slider and the row grew to hold
        it. Either way the strip changed height as you moved about, which is the thing."""
        w = self.window()
        found = self.every_screen(w)
        self.assertGreaterEqual(len(found), 4, "not enough screens were looked at")
        heights = {name: bar.height() for name, bar in found.items()}
        self.assertEqual(1, len(set(heights.values())),
                         f"the strip is not one height: {heights}")

    def test_the_strip_runs_the_whole_way_across(self):
        w = self.window()
        for name, bar in self.every_screen(w).items():
            with self.subTest(name):
                self.assertEqual(w.width(), bar.width(), f"{name}: the strip stops short")
                self.assertEqual(0, bar.mapTo(w, QtCore.QPoint(0, 0)).x())

    def test_the_times_fit_on_the_strip_in_every_language(self):
        """French and Spanish ran off the end of it on any screen carrying a Main screen
        button -- 1167 pixels of words in 1133 of room, so Isha lost its last digit. A rich
        text label does not elide, it simply stops, and a prayer time with a character missing
        is worse than a tighter row."""
        for lang in WRITTEN_IN + (ARABIC_ONLY,):
          for side in (False, True):
            with self.subTest(f"{lang}{' with the 7 inch' if side else ''}"):
                w = self.window(lang, side=side)
                w.open_corner("kalima")      # the widest furniture: slider, button and cog
                settle()
                w.tick()
                settle()
                labels = [c for c in w.stack.currentWidget().findChildren(QtWidgets.QLabel)
                          if c.objectName() == "bannerText"]
                self.assertTrue(labels, f"{lang}: no times on the strip")
                said = labels[0]
                self.assertLessEqual(said.sizeHint().width(), said.width(),
                                     f"{lang}: the times are cut off ("
                                     f"{said.sizeHint().width()} in {said.width()})")
                self.assertIn(":", said.text(), f"{lang}: the strip has no times on it")

    def test_the_pin_is_on_every_strip(self):
        w = self.window()
        for name, bar in self.every_screen(w).items():
            with self.subTest(name):
                pins = [c for c in bar.findChildren(QtWidgets.QLabel)
                        if c.objectName() == "bannerPin"]
                self.assertTrue(pins, f"{name}: no pin")
                self.assertFalse(pins[0].pixmap().isNull(), f"{name}: the pin is empty")

    def test_the_pin_sits_on_the_strip_and_not_in_a_box_of_its_own(self):
        """Harry: "the geo icon has a black background ... it should be the same as banner".

        The pin is drawn with its background left see-through, which is not enough on its
        own: the blanket QWidget rule at the top of the stylesheet paints every widget in the
        paper colour, and a QLabel is a widget. So the pin came in a black square by night
        and a white one by day, on a strip that is neither.

        Measured at the corners of the pin's own label, which is where the square showed and
        where the pin itself never reaches.
        """
        for mode in ("dark", "light"):
            w = self.window(side=True)
            w.settings.theme = mode
            w.apply_theme(chosen=True)
            settle()
            for name, bar in self.every_screen(w).items():
                pin = next(c for c in bar.findChildren(QtWidgets.QLabel)
                           if c.objectName() == "bannerPin")
                shot = bar.grab().toImage()
                at = pin.mapTo(bar, pin.rect().topLeft())
                strip = QtGui.QColor(shot.pixel(max(0, at.x() - 6), at.y() + 2))
                for x, y in ((0, 0), (pin.width() - 1, 0), (0, pin.height() - 1)):
                    with self.subTest(f"{mode}, {name}, corner {x},{y}"):
                        corner = QtGui.QColor(shot.pixel(at.x() + x, at.y() + y))
                        self.assertEqual(
                            strip.name(), corner.name(),
                            f"{mode}, {name}: the pin's corner is {corner.name()} on a strip "
                            f"of {strip.name()} -- it is sitting in a box of its own")

    def test_the_times_are_spaced_out_rather_than_run_together(self):
        """Harry: "the text all looks joined up, there is no adequate spacing and distance
        between the prayers, looks like one long sentence".

        What had happened: the strip narrows its gaps when the words will not fit, and it was
        asking every banner the window owns whether they fit -- including the ones on pages
        that have never been shown, which report a width Qt gave them before it ever laid
        them out (640 against a real 1021). Those hidden pages voted the gap down to a single
        space on the screen you were actually looking at.

        Measured in pixels off the strip rather than counted in the markup, because the markup
        is what the code wrote and the gap is what a person sees: the strip is rendered as it
        stands, then again with every gap taken out, and the difference is the spacing, which
        has to come to at least three spaces for each of the five gaps on the row.
        """
        w = self.window()
        for name, bar in self.every_screen(w).items():
            with self.subTest(name):
                said = next(c for c in bar.findChildren(QtWidgets.QLabel)
                            if c.objectName() == "bannerText")
                # THE GAP IS PADDING INSIDE THE CELLS NOW, not cellspacing and not a run of
                # &nbsp;. 2.06 made the row a one-cell-per-prayer table so the prayer of the
                # hour could carry a border -- Qt will not draw one on an inline span, which
                # was measured rather than assumed -- and spaced them with cellspacing.
                #
                # 2.23 had to take cellspacing away: it pads the OUTSIDE of a table as well
                # as the gaps between its cells, so it was also putting a full gap to the
                # left of the place name, where Harry wanted the pin to sit close. The air
                # between the times is now padding on the cells, which is the same air in a
                # different place. Counting cellspacing here would be counting something the
                # code stopped writing, exactly as counting &nbsp; would have been.
                #
                # Checked on every screen because that is what this test is for: the fault it
                # was written for was hidden pages voting the gap down on the page you were
                # looking at. How WIDE the gaps really are is measured off the rendered strip
                # in test_the_gaps_are_really_there, which can only be done where there are
                # pixels to read.
                spacing = re.search(r'padding-left:(\d+)px', said.text())
                self.assertIsNotNone(spacing, f"{name}: the row is not a spaced table")
                thin = QtGui.QFontMetrics(said.font()).horizontalAdvance(" ")
                self.assertGreaterEqual(
                    int(spacing.group(1)), thin * 3,
                    f"{name}: {spacing.group(1)}px between the prayers -- under three spaces, "
                    f"which is the row reading as one long sentence")
                self.assertLessEqual(said.sizeHint().width(), said.width(),
                                     f"{name}: spaced out, but now it does not fit")

    def test_the_gaps_are_really_there(self):
        """The one that reads pixels, on the strip a person is actually looking at.

        THE WHOLE WINDOW IS RENDERED AND THE STRIP CROPPED OUT OF IT. Rendering the label on
        its own does not paint its stylesheet background -- the 1.97 trap, where a contrast
        test passed with every fault restored because it compared a transparent fill against a
        stray antialiased pixel. Resizing a banner by hand is no better: it sits in a layout
        that puts it straight back, which is how a first attempt at this came to measure a
        640px strip with the times crushed into 191.
        """
        w = self.window()
        w.leave_welcome()
        settle()
        said = next(x for x in w.banner_labels if x.isVisible() and x.width() > 400)
        shot = QtGui.QImage(w.size(), QtGui.QImage.Format.Format_RGB32)
        shot.fill(0xFFFF00FF)                 # magenta: anything unpainted is obvious
        w.render(shot)
        box = QtCore.QRect(said.mapTo(w, QtCore.QPoint(0, 0)),
                           said.size()).intersected(shot.rect())
        crop = shot.copy(box)
        counts: dict = {}
        for y in range(crop.height()):
            for x in range(crop.width()):
                rgb = QtGui.QColor(crop.pixel(x, y)).rgb()
                counts[rgb] = counts.get(rgb, 0) + 1
        paper = max(counts, key=counts.get)
        self.assertNotEqual(0xFFFF00FF, paper,
                            "the strip painted nothing, so this measures nothing")
        runs, n = [], 0
        for x in range(crop.width()):
            if all(QtGui.QColor(crop.pixel(x, y)).rgb() == paper for y in range(crop.height())):
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)
        wide = sorted((r for r in runs if r >= 6), reverse=True)
        self.assertGreaterEqual(len(wide), 5,
                                f"only {len(wide)} gaps across the row: {wide}")
        thin = QtGui.QFontMetrics(said.font()).horizontalAdvance(" ")
        self.assertGreaterEqual(wide[4], thin * 2,
                                f"the five widest gaps are {wide[:5]}px, which is the row "
                                f"running together")

    @staticmethod
    def gap(label) -> int:
        """How far apart the prayers are set on the strip, in the units write_the_times uses.

        It used to count a run of &nbsp;. The row is a table now -- one cell per prayer, so the
        prayer of the hour can carry a border Qt will not draw on a span -- and the gap is the
        padding. Same number on the same scale: write_the_times still works in fours down
        to ones and multiplies by eight, so four spaces and a 32px padding are the same
        setting said two ways.
        """
        found = re.search(r'padding-left:(\d+)px', label.text())
        return int(found.group(1)) // 8 if found else 0

    def test_opening_one_prayer_after_another_does_not_take_the_app_down(self):
        """A strip that has been thrown away is not written to again.

        A prayer's units are built fresh every time an arch is touched and the old page is
        deleted -- but the window went on holding a handle to the strip that was on it, and
        writing the time to a widget that is no longer there raises, in both bindings, out of
        the ten-second timer. Two prayers and a tick was all it took; what Harry would have
        seen is the mat dropping to the desktop, or now restarting itself.
        """
        w = self.window()
        for prayer in ("fajr", "dhuhr", "isha", "asr"):
            w.open_prayer(prayer)
            settle()
            w.tick()
            settle()
        said = next(c for c in self.strip(w.pick).findChildren(QtWidgets.QLabel)
                    if c.objectName() == "bannerText")
        self.assertIn(":", said.text(), "the strip on the page you are looking at is blank")
        self.assertLessEqual(len(w.banner_labels), 8,
                             f"{len(w.banner_labels)} strips are being kept for "
                             f"{len(w.stack.children())} pages; the dead ones pile up")

    def test_the_spacing_comes_back_when_there_is_room_again(self):
        """The other half of the same fault, and the half that made it stick.

        How much room the times have was asked of the label -- and a label's width is last
        layout's answer, so once the row had been squeezed onto a narrow window the measure
        of the room was the squeezed width, and the four spaces never fitted again however
        wide the window went afterwards. Measured: 1920 gives four spaces, 900 gives two,
        and back at 1920 the old way gives one, for good.

        The room is worked out from the strip instead -- its width less the pin, the slider
        and the buttons, all of which are fixed -- so it is right the moment it is asked.
        """
        w = self.window()
        w.stack.setCurrentWidget(w.home)
        settle()
        said = next(c for c in self.strip(w.home).findChildren(QtWidgets.QLabel)
                    if c.objectName() == "bannerText")
        self.assertGreaterEqual(self.gap(said), 4, "it did not start out spaced")
        for wide in (900, 1920):
            w.resize(wide, 1080)
            settle()
            w.tick()
            settle()
        self.assertGreaterEqual(self.gap(said), 4,
                                "the strip was squeezed onto a narrow window and stayed "
                                "squeezed when the room came back")


class SixTileMenuTest(unittest.TestCase):
    """The 7in menu: six tiles, two across and three down, filling the screen with no heading."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_the_tiles_sit_two_across_and_five_down(self):
        """Three down, then four, now five: Harry has redrawn this sheet four times.

        This test has been wrong since 1.88 and nobody noticed, because it was wrong in a crowd
        of other failures. It still expected a "wudu" tile that became "children" at 1.88, and
        eight tiles where 1.89 draws ten. Both are written out again here from the sheet that
        actually ships -- Qur'an/Salaah, Hadith/Du'as, Children/Learn, Knowledge/World,
        Settings/Radio -- and note that this is NOT the old order with two appended: Radio,
        Settings and World all moved.
        """
        w = self.window()
        tiles = w.side.corner.tiles
        self.assertEqual(10, len(tiles))
        columns = sorted({t.x() for t in tiles})
        rows = sorted({t.y() for t in tiles})
        self.assertEqual(2, len(columns), f"expected two columns, got {columns}")
        self.assertEqual(5, len(rows), f"expected five rows, got {rows}")
        # reading order: across, then down
        order = sorted(tiles, key=lambda t: (t.y(), t.x()))
        self.assertEqual(["quran", "salaah", "hadith", "duas", "children",
                          "learn", "knowledge", "world", "settings", "radio"],
                         [t.name for t in order])

    def test_the_heading_is_gone_and_the_tiles_take_the_height(self):
        """The words are drawn into the tiles, so a title above them said a third thing on a
        screen with room for two -- and took the height the tiles wanted."""
        w = self.window()
        corner = w.side.corner
        said = [x.text() for x in corner.findChildren(QtWidgets.QLabel) if x.text()]
        self.assertEqual([], said, f"there is still lettering above the tiles: {said}")
        self.assertNotIn("Knowledge", " ".join(
            x.text() for x in w.side.findChildren(QtWidgets.QLabel)))
        top = min(t.y() for t in corner.tiles)
        bottom = max(t.y() + t.height() for t in corner.tiles)
        self.assertLess(top, w.side.height() * 0.05, "space wasted above the tiles")
        self.assertGreater(bottom, w.side.height() * 0.95, "space wasted below them")

    def test_every_tile_has_its_own_picture_and_they_are_all_different(self):
        """The picture each tile is actually pointed at, not the files on disk. Eight correct
        files prove nothing if every tile is wired to the same one -- which is exactly what
        the first version of this missed."""
        w = self.window()
        pointed = {t.name: t.path for t in w.side.corner.tiles}
        self.assertEqual(10, len(set(pointed.values())), f"tiles share pictures: {pointed}")
        seen = {}
        for name, path in pointed.items():
            self.assertEqual(f"{name}.png", path.name, f"{name} is pointed at {path.name}")
            self.assertTrue(path.is_file(), name)
            image = QtGui.QImage(str(path))  # noqa: the path the tile itself carries
            self.assertFalse(image.isNull(), name)
            self.assertGreater(image.width(), 200, name)
            # THE SHAPE OF ITS OWN BOX, not "roughly square". These stills are cut out of the
            # film, so each one should be the shape of the box it was cut from -- and that is
            # the thing worth checking, because a still of the wrong shape is a still from an
            # older sheet. "Roughly square" was true of the eight-tile sheet and stopped being
            # true at 1.89, when five rows made every tile 272x184; the old wording would have
            # had the drawing changed to suit the test.
            import json
            boxes = json.loads((ASSETS / "knowledge" / "menu.json")
                               .read_text(encoding="utf-8"))["tiles"]
            x0, y0, x1, y1 = boxes[name]
            want = (x1 - x0) / (y1 - y0)
            got = image.width() / image.height()
            self.assertAlmostEqual(
                got, want, delta=0.05,
                msg=f"{name}.png is {image.width()}x{image.height()} ({got:.2f}) and its box "
                    f"on the sheet is {x1 - x0}x{y1 - y0} ({want:.2f}) -- a still from an "
                    f"older cut of the menu")
            ink = tuple(image.pixel(x, y) for y in range(0, image.height(), 9)
                        for x in range(0, image.width(), 9))
            self.assertNotIn(ink, seen, f"{name} is the same picture as {seen.get(ink)}")
            seen[ink] = name

    def test_the_four_that_are_filled_in_still_open_what_they_did(self):
        w = self.window()
        by_name = {t.name: t for t in w.side.corner.tiles}
        by_name["quran"].click()
        settle()
        self.assertIs(w.surah_list, w.corner_screen.currentWidget())
        w.go_home()
        by_name["duas"].click()
        settle()
        self.assertIs(w.dua_menu, w.corner_screen.currentWidget(),
                      "the Du'as tile should open the kinds")
        w.go_home()
        by_name["hadith"].click()
        settle()
        self.assertIs(w.hadith_menu, w.corner_screen.currentWidget(),
                      "the Hadith tile should open the twelve headings")
        w.go_home()
        # The fifth used to be the kalima. They are behind the du'a menu now, and this square
        # is Salaah: straight to the five prayers rather than into the Knowledge Corner.
        by_name["salaah"].click()
        settle()
        self.assertIs(w.home, w.stack.currentWidget())

    def test_a_tile_whose_section_is_missing_lands_on_a_named_empty_screen(self):
        """Every one of the six leads somewhere now -- hadith was the last that did not, and it
        has its twelve headings since. What is left to check is the fallback: a mat whose assets
        were half copied still lands on a screen that SAYS which section is missing, rather than
        on an empty menu or a blank page."""
        w = self.window()
        by_name = {t.name: t for t in w.side.corner.tiles}
        for name, heading in (("hadith", "Hadith"),):
            w.go_home()
            settle()
            w.section_lists[name].passages._items = []
            by_name[name].click()
            settle()
            self.assertIs(w.corner_soon, w.corner_screen.currentWidget(), name)
            self.assertIs(w.corner_page, w.stack.currentWidget(), name)
            self.assertEqual(heading, w.soon_title.text(), name)
            said = [x.text() for x in w.corner_soon.findChildren(QtWidgets.QLabel)]
            self.assertIn(w.t("corner.not_yet"), said, name)

    def test_the_empty_screen_carries_the_strip_like_every_other(self):
        w = self.window()
        w.section_lists["hadith"].passages._items = []
        {t.name: t for t in w.side.corner.tiles}["hadith"].click()
        settle()
        strips = [x for x in w.corner_page.findChildren(QtWidgets.QWidget)
                  if x.objectName() == "banner"]
        self.assertEqual(1, len(strips))
        said = next(x for x in strips[0].findChildren(QtWidgets.QLabel)
                    if x.objectName() == "bannerText")
        self.assertIn("Bury", said.text())
        for prayer in ("fajr", "dhuhr", "asr", "maghrib", "isha"):
            self.assertIn(w.t(f"prayer.{prayer}"), said.text(), prayer)

    def test_every_reading_tile_is_named_in_every_language(self):
        """Every tile that lands on a Knowledge screen needs a name for its heading. Settings
        is not one of those -- it goes to the Settings screen, which has its own title."""
        import json
        from salaah.knowledge import TILES
        readings = [n for n in TILES if n != "settings"]
        self.assertEqual(9, len(readings))
        for lang in sorted(full_packs(available_packs(ASSETS))):
            ui = json.loads((ASSETS / "content" / "packs" / lang / "pack.json")
                            .read_text(encoding="utf-8"))["ui"]
            for name in readings:
                self.assertTrue(ui.get(f"corner.{name}", "").strip(),
                                f"{lang} has no name for {name}")

    def test_a_tile_is_a_big_enough_target_for_a_finger(self):
        """IN MILLIMETRES, not pixels.

        This asked for 200 px each way, which was fine for eight tiles in four rows and fails
        for ten in five: the sheet is 600x1024 whatever is drawn on it, so a fifth row makes
        every tile 184 px tall instead of 255. Raising the number to 180 to suit would be
        fitting the test to the drawing, and it would say nothing about a finger.

        The panel is 7 inches on the diagonal at 600x1024, which is about 6.7 pixels to the
        millimetre, so the 1.89 tiles are roughly 41mm by 28mm. The guidelines that exist put
        a comfortable touch target at 9-10mm -- Microsoft says 9mm, ISO 9241-9 about a finger
        width -- so ten tiles are still three times over on the short side. Checked against
        12mm here, which leaves room for a sixth row before anybody has to think again.
        """
        PX_PER_MM = (600 ** 2 + 1024 ** 2) ** 0.5 / (7 * 25.4)
        least = 12 * PX_PER_MM
        w = self.window()
        for tile in w.side.corner.tiles:
            for side, how in ((tile.width(), "across"), (tile.height(), "down")):
                self.assertGreater(
                    side, least,
                    f"{tile.name} is {side / PX_PER_MM:.0f}mm {how}, under the 12mm a finger "
                    f"wants ({side} px against {least:.0f})")


class SettingsFromTheTileTest(unittest.TestCase):
    """Settings is reached from the 7in tile, so the red cog has left the strip."""

    def window(self, side=True):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=side)
        w.resize(1920, 1080)
        w.show()
        if side:
            w.side.resize(600, 1024)
            w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_the_settings_tile_opens_settings(self):
        w = self.window()
        {t.name: t for t in w.side.corner.tiles}["settings"].click()
        settle()
        self.assertIs(w.settings_screen, w.stack.currentWidget())

    def test_it_does_not_land_on_the_not_filled_in_screen(self):
        """Settings is not a reading. Sent through the same door as the others it would have
        come out on the screen that says there is nothing here yet."""
        w = self.window()
        {t.name: t for t in w.side.corner.tiles}["settings"].click()
        settle()
        self.assertIsNot(w.corner_soon, w.corner_screen.currentWidget())
        self.assertIsNot(w.corner_page, w.stack.currentWidget())

    def test_no_cog_on_any_strip_when_the_small_screen_is_there(self):
        from salaah.mosque import GearButton
        w = self.window()
        # The front door is not in this list: it has carried no strip since 1.76, so there
        # is nothing on it for a cog to be on.
        for page in (w.home, w.corner_page):
            strips = [x for x in page.findChildren(QtWidgets.QWidget)
                      if x.objectName() == "banner"]
            for strip in strips:
                self.assertEqual([], strip.findChildren(GearButton),
                                 "a cog is still on a strip")

    def test_the_cog_stays_when_there_is_no_small_screen_to_replace_it(self):
        """Without the 7in there is no Settings tile, and taking the cog away as well would
        wall Settings off with no way in at all."""
        from salaah.mosque import GearButton
        w = self.window(side=False)
        self.assertTrue(w.needs_a_gear)
        cogs = [x for x in w.home.findChildren(GearButton)]
        self.assertTrue(cogs, "no way into Settings on a mat with one screen")
        cogs[0].pressed_signal.emit()
        settle()
        self.assertIs(w.settings_screen, w.stack.currentWidget())

    def test_the_settings_tile_is_not_shown_as_a_reading(self):
        w = self.window()
        w.chose_on_the_small_screen("settings")
        settle()
        self.assertIs(w.settings_screen, w.stack.currentWidget())
        w.go_home()
        settle()
        w.chose_on_the_small_screen("hadith")
        settle()
        self.assertIs(w.hadith_menu, w.corner_screen.currentWidget(),
                      "the readings should still go the way they did")


class VolumeSliderLookTest(unittest.TestCase):
    """The slider on the strip: bigger, and with no figure printed beside it."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=True, place="Bury", volume=60),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def showing(self, w):
        # Past the front door: it is one picture since 1.76, with no strip and so no slider.
        w.leave_welcome()
        w.veil.stop()
        settle()
        bars = [b for b, _ in w.volume_bars if b.isVisible()]
        self.assertTrue(bars, "no slider is on screen")
        return bars[0]

    def test_no_percentage_is_printed_beside_it(self):
        w = self.window()
        for bar, read in w.volume_bars:
            self.assertFalse(read.isVisible(), "the figure is still on the strip")
        # Anything else on the strip that prints one -- a hidden label still answers text(),
        # so only what is actually on screen counts.
        w.leave_welcome()
        w.veil.stop()
        settle()
        said = " ".join(x.text() for x in w.home.findChildren(QtWidgets.QLabel)
                        if x.text() and x.isVisible())
        self.assertNotIn("%", said, "a percentage is still printed on the strip")

    def test_it_is_bigger_than_it_was(self):
        """Wide enough for a thumb, which is why it was made bigger in the first place.

        It asked for 300 until the strip ran out of room in Spanish and the spacing between
        the prayer times was what gave way -- "looks like one long sentence". The slider gave
        up those 80 pixels instead: it is a control, and still an easy one to hit at 240,
        where the times are the thing people read.
        """
        w = self.window()
        bar = self.showing(w)
        self.assertGreaterEqual(bar.width(), w.px(240), "no wider than before")
        self.assertGreaterEqual(bar.height(), w.px(50), "no taller than before")

    def test_it_still_fits_inside_the_strip(self):
        w = self.window()
        bar = self.showing(w)
        strip = next(x for x in w.home.findChildren(QtWidgets.QWidget)
                     if x.objectName() == "banner")
        self.assertLessEqual(bar.height(), strip.height(),
                             "the slider is taller than the strip it sits in")

    def test_it_still_sets_the_volume(self):
        w = self.window()
        self.showing(w).setValue(25)
        settle()
        self.assertEqual(25, w.settings.volume)
        for bar, _ in w.volume_bars:
            self.assertEqual(25, bar.value(), "the sliders came out of step")


class DuaMenuTest(unittest.TestCase):
    """Touching Du'as lands on the eighteen kinds, and a kind shows only its own."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_the_duas_tile_opens_the_kinds_and_not_the_long_list(self):
        w = self.window()
        w.chose_on_the_small_screen("duas")
        settle()
        self.assertIsNotNone(w.dua_menu, "the menu was not built")
        self.assertIs(w.dua_menu, w.corner_screen.currentWidget())

    def test_every_kind_is_touchable_and_carries_its_own_picture(self):
        from salaah.duamenu import CATEGORIES, NOT_A_KIND
        w = self.window()
        tiles = {t.name: t for t in w.dua_menu.tiles}
        self.assertEqual(set(CATEGORIES), set(tiles))
        for name, tile in tiles.items():
            self.assertEqual(f"{name}.png", tile.path.name,
                             f"the {name} tile is drawn from {tile.path.name}")
            self.assertTrue(tile.path.is_file())
            self.assertTrue(tile.isEnabled())

    def test_a_kind_shows_only_the_duas_filed_under_it(self):
        w = self.window()
        w.open_dua_category("worry")
        settle()
        board = w.dua_board
        self.assertIs(board, w.corner_screen.currentWidget())
        shown = [item for _, item in board.showing]
        self.assertTrue(shown, "nothing came up under worry")
        for item in shown:
            self.assertIn("worry", item.cats, "a du'a of another kind is on screen")
        # by key: a Passage carries a dict of meanings, so it cannot go in a set
        self.assertTrue({d.key for d in shown}
                        <= {d.key for d in board.passages.items if "worry" in d.cats})

    def test_the_rows_on_screen_are_the_ones_the_filter_kept(self):
        """wanted() saying the right thing is not the same as the screen showing it."""
        w = self.window()
        w.open_dua_category("forgiveness")
        settle()
        board = w.dua_board
        titles = {item.title for _, item in board.showing}
        on_screen = {x.text() for x in board.findChildren(QtWidgets.QLabel)
                     if x.text() and x.isVisible()}
        self.assertTrue(titles <= on_screen, f"{titles - on_screen} was picked but not drawn")
        others = {d.title for d in board.passages.items
                  if "forgiveness" not in d.cats}
        self.assertEqual(set(), others & on_screen, "a du'a from another kind is on screen")

    def test_changing_kind_replaces_the_rows_rather_than_adding_to_them(self):
        w = self.window()
        board = w.dua_board
        w.open_dua_category("worry")
        settle()
        first = len(board.cards)
        self.assertGreater(first, 0, "nothing was shown to begin with")
        w.open_dua_category("mosque")
        settle()
        self.assertEqual(len(board.showing), len(board.cards),
                         f"{len(board.cards)} cards for {len(board.showing)} picked -- "
                         f"the cards from the kind before are still standing")
        for card in board.cards:
            self.assertIn("mosque", card.item.cats, "a card from the kind before survived")

    def test_opening_one_from_a_narrowed_list_opens_that_very_dua(self):
        """The row keeps its place in the whole section. Number the rows 0,1,2 inside the
        filter instead and the third du'a under a kind opens the third du'a overall."""
        w = self.window()
        w.open_dua_category("worry")
        settle()
        listing = w.section_lists["duas"]
        board = w.dua_board
        card = board.cards[-1]
        index, wanted = card.index, card.item
        # Press the card itself. Emitting chose(index) here instead would prove nothing: the
        # test would be supplying the very number the card is supposed to carry.
        card.opened.emit(card.index)
        settle()
        reader = w.section_readers["duas"]
        self.assertIs(reader, w.corner_screen.currentWidget())
        self.assertEqual(index, reader.at, "a different du'a opened")
        opened = reader.passages.items[reader.at]
        self.assertEqual(wanted.title, opened.title)
        self.assertIn("worry", opened.cats)

    def test_a_kind_with_nothing_in_it_says_which_kind_it_is(self):
        """Every kind has du'as now, so this empties one to get at the behaviour -- which is
        what a mat with a half-copied content folder would see."""
        w = self.window()
        listing = w.section_lists["duas"]
        kept = list(listing.passages.items)     # reading it is what loads the file
        listing.passages._items = [d for d in kept if "travel" not in d.cats]
        self.addCleanup(lambda: setattr(listing.passages, "_items", kept))
        w.open_dua_category("travel")
        settle()
        self.assertIs(w.corner_soon, w.corner_screen.currentWidget())
        self.assertEqual(w.t("dua.travel"), w.soon_title.text())
        self.assertNotEqual("", w.soon_title.text().strip())

    def test_the_whole_list_comes_back_when_it_is_asked_for(self):
        w = self.window()
        board = w.dua_board
        w.open_dua_category("worry")
        settle()
        narrowed = len(board.wanted())
        board.show_only(None)
        settle()
        self.assertEqual(len(board.passages.items), len(board.wanted()))
        self.assertLess(narrowed, len(board.wanted()))

    def test_the_kinds_are_left_alone_while_a_prayer_is_going_on(self):
        w = self.window()
        w.open_dua_category("worry")
        settle()
        board = w.dua_board
        # Both kinds land on the same widget, so what is SHOWN is what has to be looked at.
        was = [i for i, _ in board.wanted()]
        with mock.patch.object(type(w), "playing", property(lambda _self: True)):
            w.open_dua_category("forgiveness")
            settle()
            self.assertEqual(was, [i for i, _ in board.wanted()],
                             "a stray knee changed the screen mid-prayer")
        w.open_dua_category("forgiveness")
        settle()
        self.assertNotEqual(was, [i for i, _ in board.wanted()],
                            "and it still works once the prayer is over")


class DuaBoardTest(unittest.TestCase):
    """Two columns with a rule between them, a play mark on every du'a, and the meaning under
    the Arabic -- all of it measured off what is drawn, not off the layout's opinion."""

    def window(self, theme="dark"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=theme, recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def board(self, w, cat="travel"):
        w.open_corner("duas")
        settle()
        w.open_dua_category(cat)
        settle()
        self.assertIs(w.dua_board, w.corner_screen.currentWidget())
        return w.dua_board

    def test_two_duas_are_shown_one_each_side(self):
        """Two, no more: the whole point of the size they are drawn at."""
        from salaah.duamenu import CATEGORIES, NOT_A_KIND
        w = self.window()
        for cat in (c for c in CATEGORIES if c not in NOT_A_KIND):
            board = self.board(w, cat)
            left = [board.left.itemAt(i).widget() for i in range(board.left.count())]
            right = [board.right.itemAt(i).widget() for i in range(board.right.count())]
            left = [x for x in left if x is not None]
            right = [x for x in right if x is not None]
            self.assertEqual(1, len(left), f"{cat} has {len(left)} on the left")
            self.assertEqual(1, len(right), f"{cat} has {len(right)} on the right")
            self.assertEqual(2, len(board.cards), f"{cat} drew {len(board.cards)} cards")

    def test_the_two_columns_really_are_side_by_side_on_screen(self):
        """Counting widgets in two boxes says nothing about where they were drawn."""
        w = self.window()
        board = self.board(w, "worry")
        left = [c for c in board.cards if board.left.indexOf(c) >= 0]
        right = [c for c in board.cards if board.right.indexOf(c) >= 0]
        edge = max(c.mapTo(board, c.rect().topRight()).x() for c in left)
        start = min(c.mapTo(board, c.rect().topLeft()).x() for c in right)
        self.assertLess(edge, start, "the columns overlap instead of sitting side by side")

    def test_a_thick_rule_is_drawn_between_them(self):
        w = self.window()
        board = self.board(w, "travel")
        self.assertIsNotNone(board.rule, "no rule between the columns")
        self.assertGreaterEqual(board.rule.width(), w.px(5), "the rule is a hairline")
        # Drawn, not merely sized: a widget styled to a width it paints nothing into is not a
        # line. Its own pixels are what settle it.
        image = board.rule.grab().toImage()
        self.assertGreater(image.width(), 0)
        middle = image.pixelColor(image.width() // 2, image.height() // 2)
        page = w.palette().color(w.backgroundRole())
        self.assertNotEqual((page.red(), page.green(), page.blue()),
                            (middle.red(), middle.green(), middle.blue()),
                            "the rule is the same colour as the page behind it")

    def test_the_rule_sits_between_the_columns_and_not_beside_them(self):
        w = self.window()
        board = self.board(w, "worry")
        rule = board.rule.mapTo(board, board.rule.rect().center()).x()
        left = [c for c in board.cards if board.left.indexOf(c) >= 0]
        right = [c for c in board.cards if board.right.indexOf(c) >= 0]
        self.assertLess(max(c.mapTo(board, c.rect().topRight()).x() for c in left), rule)
        self.assertGreater(min(c.mapTo(board, c.rect().topLeft()).x() for c in right), rule)

    def test_every_dua_carries_a_play_mark_that_is_actually_drawn(self):
        w = self.window()
        board = self.board(w, "worry")
        for card in board.cards:
            self.assertFalse(card.button.icon().isNull(), f"{card.item.key} has no play mark")
            shot = card.button.grab().toImage()
            page = w.palette().color(w.backgroundRole())
            ink = sum(1 for y in range(0, shot.height(), 2) for x in range(0, shot.width(), 2)
                      if abs(shot.pixelColor(x, y).red() - page.red()) > 40)
            self.assertGreater(ink, 20, f"{card.item.key}'s mark is a blank square")

    def test_the_arabic_and_the_meaning_are_both_on_the_card(self):
        w = self.window()
        board = self.board(w, "travel")
        for card in board.cards:
            self.assertEqual([card.item.arabic], list(card.arabic.lines))
            self.assertTrue(card.meaning.text().strip(), f"{card.item.key} has no meaning")
            self.assertTrue(card.meaning.isVisible())
            self.assertNotEqual(card.item.arabic, card.meaning.text())

    def test_a_dua_with_no_transliteration_shows_no_empty_line_for_it(self):
        """The ones from hadith have no transliteration yet. An empty italic line would read
        as a missing word rather than as nothing to say.

        Which is now moot: there is no transliteration line on a card at all. It appeared on ten
        du'as and not on the other thirty-eight, and Harry had it taken out once every du'a could
        be heard read aloud. So what this asks is the stronger version of what it used to ask --
        not that the line is hidden when empty, but that it is not there to be empty."""
        w = self.window()
        board = self.board(w, "travel")
        for card in board.cards:
            self.assertFalse(hasattr(card, "said"),
                             f"{card.item.key} still carries a transliteration line")

    def test_pressing_a_card_opens_that_very_dua(self):
        w = self.window()
        board = self.board(w, "worry")
        # Taken before pressing anything: reopening the kind reshuffles, so a card held across
        # the loop would be a card that is no longer on screen.
        want = [(c.index, c.item.title) for c in board.cards]
        for index, title in want:
            card = next(c for c in board.cards if c.index == index)
            card.opened.emit(card.index)
            settle()
            reader = w.section_readers["duas"]
            self.assertIs(reader, w.corner_screen.currentWidget())
            self.assertEqual(index, reader.at)
            self.assertEqual(title, reader.passages.items[reader.at].title)
            w.corner_screen.setCurrentWidget(board)      # back without reshuffling
            settle()

    def test_the_play_mark_reads_the_dua_its_card_stands_for(self):
        """It used to open that du'a's own page. It reads it here now, and the card it reads is
        the card that was pressed -- which is the same claim, about the right du'a, made against
        what actually happens."""
        w = self.window()
        board = self.board(w, "health")
        card = board.cards[-1]
        card.button.click()
        settle()
        self.assertIs(board, w.corner_screen.currentWidget(), "it left the board")
        self.assertIs(card, board.said_by, "the wrong card is being read")
        board.stop_saying()
        settle()

    def test_there_is_no_button_strip_along_the_bottom(self):
        """It was taken away to give the Arabic the height. Checked by looking for any button
        on the board rather than for the one that used to be there, so a different one put
        back in the same place is caught too."""
        w = self.window()
        board = self.board(w, "travel")
        self.assertFalse(hasattr(board, "back_button"))
        buttons = [b for b in board.findChildren(QtWidgets.QAbstractButton) if b.isVisible()]
        for b in buttons:
            # The play marks sit on the cards; the two chevrons sit in the strip at the top,
            # beside the heading. Anything else, anywhere, is the strip creeping back.
            self.assertIn(b.objectName(), ("duaPlay", "turnBoard"),
                          f"{b.objectName() or b.text()!r} is on the board")
            if b.objectName() == "turnBoard":
                self.assertLess(b.mapTo(board, QtCore.QPoint(0, 0)).y(), board.height() * 0.2,
                                "an arrow has wandered down the screen")
        floor = max(c.mapTo(board, c.rect().bottomLeft()).y() for c in board.cards)
        self.assertGreater(floor, board.height() * 0.93,
                           "the cards stop short of the bottom -- something is taking that strip")

    def test_no_kind_scrolls_at_all(self):
        """Now that the Arabic sizes itself to its box, nothing should ever need scrolling."""
        from salaah.duamenu import CATEGORIES, NOT_A_KIND
        w = self.window()
        scrolls = []
        for cat in (c for c in CATEGORIES if c not in NOT_A_KIND):
            board = self.board(w, cat)
            if board.scroll.verticalScrollBar().maximum() > 0:
                scrolls.append(cat)
        self.assertEqual([], scrolls, f"these kinds do not fit: {scrolls}")

    def test_the_two_longest_duas_together_still_fit(self):
        """The worst pair the shuffle can deal, forced rather than waited for."""
        w = self.window()
        board = self.board(w, "forgiveness")
        board.showing = sorted(board.wanted(), key=lambda p: -len(p[1].arabic))[:2]
        board.filled = None
        board.fill()
        settle()
        self.assertEqual(0, board.scroll.verticalScrollBar().maximum(),
                         "the longest two run off the screen")

    def test_a_short_dua_is_drawn_far_larger_than_a_long_one(self):
        """The box earns its keep only if it really does change size. Measured off the font
        the box settled on, not off the stylesheet."""
        w = self.window()
        board = self.board(w, "mosque")             # two very short du'as
        short = max(c.arabic.fitted_size() for c in board.cards)
        board = self.board(w, "forgiveness")
        board.showing = sorted(board.wanted(), key=lambda p: -len(p[1].arabic))[:2]
        board.filled = None
        board.fill()
        settle()
        long = max(c.arabic.fitted_size() for c in board.cards)
        self.assertGreater(short, long * 1.5, f"short {short}px vs long {long}px")

    def test_the_same_kind_opens_on_the_same_two_every_time(self):
        """The opposite of what this asked until 1.69, and on purpose.

        The two on screen used to be dealt off a shuffled bag so that a kind gave you
        something different each visit. That answered the wrong question: stood on a mat you
        want the du'a you were reading a moment ago, not a surprise. The kind opens on its
        first two now and the arrows are the way to the rest -- see WalkingTheBoardsTest.
        """
        w = self.window()
        seen = set()
        for _ in range(6):
            board = self.board(w, "gratitude")
            seen.add(tuple(i for i, _ in board.showing))
        self.assertEqual(1, len(seen), f"the pair still changes between visits: {seen}")

    def test_nothing_along_the_bottom_takes_height_from_the_arabic(self):
        """Back was removed to give that strip's height to the words. If anything creeps back
        along the bottom, the reason for two-at-a-time is gone."""
        w = self.window()
        board = self.board(w, "worry")
        self.assertFalse(hasattr(board, "back_button"), "a Back button is on the board again")
        floor = max(c.mapTo(board, c.rect().bottomLeft()).y() for c in board.cards)
        self.assertGreater(floor, board.height() * 0.9,
                           f"the cards stop {board.height() - floor}px short of the bottom")

    def test_the_board_is_not_a_dead_end(self):
        """Taking Back off is only safe because the strip above carries the way out. If that
        ever goes too, somebody is stuck on a du'a screen with no way off it."""
        w = self.window()
        board = self.board(w, "travel")
        outs = [b for b in w.corner_page.findChildren(QtWidgets.QPushButton)
                if b.isVisible() and b.objectName() in ("mainScreen", "backButton")]
        self.assertTrue(outs, "no way off the du'a board at all")
        outs[0].click()
        settle()
        self.assertIs(w.welcome, w.stack.currentWidget(), "the way out did not lead anywhere")

    def test_the_pair_does_not_change_under_you_while_the_screen_is_shown(self):
        """Stepping into a du'a and coming back must bring back the same two. The pick belongs
        to opening the kind, not to the screen being shown.

        Driven through the screens rather than by hiding and showing the widget. hide() then
        show() on a page inside a stack delivers no showEvent at all, so the first version of
        this test passed a sabotage that re-picked the pair on every show -- it was watching a
        door nobody uses. Opening a du'a and pressing Back is the path that really happens.
        """
        w = self.window()
        board = self.board(w, "gratitude")
        was = [i for i, _ in board.showing]
        card = board.cards[0]
        card.opened.emit(card.index)
        settle()
        reader = w.section_readers["duas"]
        self.assertIs(reader, w.corner_screen.currentWidget(), "the du'a did not open")
        reader.back_button.click()
        settle()
        self.assertIs(board, w.corner_screen.currentWidget(), "Back did not return to the board")
        self.assertEqual(was, [i for i, _ in board.showing], "the du'as changed on their own")
        self.assertEqual(was, [c.index for c in board.cards], "the cards and the pick disagree")


class PlayMarkTest(unittest.TestCase):
    """One mark means play, wherever it is."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=True, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_it_is_a_ring_with_a_mark_inside_and_not_a_filled_blob(self):
        from salaah.ui import play_icon
        shot = play_icon(120, "#ffffff").toImage()
        def lit(x, y):
            c = shot.pixelColor(x, y)
            return c.alpha() > 40 and c.red() > 120
        self.assertTrue(lit(60, 4) or lit(60, 6), "no ring at the top")
        self.assertFalse(lit(20, 20), "the corner is filled in -- this is a blob, not a ring")
        self.assertTrue(lit(56, 60), "nothing inside the ring")
        # the gap between ring and triangle: a filled circle would have no dark band here
        self.assertFalse(lit(26, 60), "the ring and the mark have run together")

    def test_the_stop_mark_is_a_different_shape_from_the_play_mark(self):
        from salaah.ui import play_icon
        go = play_icon(120, "#ffffff").toImage()
        stop = play_icon(120, "#ffffff", stop=True).toImage()
        def ink(image):
            return sum(1 for y in range(0, 120, 2) for x in range(0, 120, 2)
                       if image.pixelColor(x, y).alpha() > 40)
        self.assertNotEqual(ink(go), ink(stop), "play and stop draw the same thing")
        # the play triangle has a sloped edge, so its bottom-left corner is empty and the
        # square's is not
        self.assertNotEqual(go.pixelColor(46, 78).alpha() > 40,
                            stop.pixelColor(46, 78).alpha() > 40)

    def test_the_quran_recite_button_is_the_drawn_mark_not_a_blue_rectangle(self):
        w = self.window()
        w.open_surah(1)
        settle()
        button = w.reader.recite_button
        self.assertFalse(button.icon().isNull(), "the recite button has no mark on it")
        self.assertEqual("", button.text(), "the recite button still spells something out")
        shot = button.grab().toImage()
        # It used to be a solid lapis slab with a glyph on it. Two things settle that it is not:
        # the button's background is the page's, not a colour of its own, and there is a mark
        # drawn on it. Counting distinct colours does not settle either -- a white ring on a
        # black page is two colours, and so is a blue slab.
        page = w.palette().color(w.backgroundRole())
        lapis = QtGui.QColor(w.colours().lapis)
        blue = ink = total = 0
        for y in range(0, shot.height(), 2):
            for x in range(0, shot.width(), 2):
                c = shot.pixelColor(x, y)
                total += 1
                if abs(c.red() - lapis.red()) < 40 and abs(c.blue() - lapis.blue()) < 40 \
                        and c.blue() > c.red() + 30:
                    blue += 1
                if abs(c.red() - page.red()) > 60:
                    ink += 1
        self.assertLess(blue / total, 0.05, "the button is still a blue slab")
        self.assertGreater(ink / total, 0.02, "nothing is drawn on the button")
        self.assertLess(ink / total, 0.6, "the button is filled in rather than marked")

    def test_the_recite_mark_is_twice_the_size_it_was(self):
        """It was 0.62 of a button the height of Back. The button is now square and twice
        Back's height, so the mark inside it doubles -- measured against Back, which has not
        changed, rather than against a number written in here."""
        w = self.window()
        w.open_surah(1)
        settle()
        button, back = w.reader.recite_button, w.reader.back_button
        self.assertEqual(back.height() * 2, button.height(), "the button did not double")
        self.assertEqual(button.height(), button.width(), "the button is not square")
        was = int(back.height() * 0.62)          # what the mark used to be
        self.assertGreaterEqual(button.iconSize().height(), was * 2 - 2,
                                f"the mark is {button.iconSize().height()}px, was {was}px")
        self.assertLessEqual(button.iconSize().height(), button.height(),
                             "the mark is bigger than the button and would be cropped")

    def test_the_mark_turns_to_stop_and_back(self):
        """Driven through the flag rather than by starting the audio. Playing a recitation for
        real needs a player, which is not always there in a test run -- this failed once in a
        full run and passed on its own, and a test that only sometimes looks is no test."""
        w = self.window()
        w.open_surah(1)
        settle()
        reader = w.reader
        before = reader.recite_button.icon().pixmap(40, 40).toImage()
        reader.reciting_now = True
        reader.draw_recite_mark()
        during = reader.recite_button.icon().pixmap(40, 40).toImage()
        self.assertNotEqual(before, during, "the mark did not change")
        reader.reciting_now = False
        reader.draw_recite_mark()
        self.assertEqual(before, reader.recite_button.icon().pixmap(40, 40).toImage())

    def test_starting_and_stopping_are_what_set_that_flag(self):
        """The half the test above does not cover: that reciting actually flips the flag the
        mark is drawn from. Checked without a player, which start_reciting copes with."""
        w = self.window()
        w.open_surah(1)
        settle()
        reader = w.reader
        self.assertFalse(reader.reciting_now)
        reader.start_reciting()
        settle()
        # `reciting` is the flag that says it really began -- `saying` is the label in the bar
        # and is always truthy, which is how the first version of this test managed to pass
        # and fail on the same code.
        if reader.reciting:                    # no recitation audio here: nothing to check
            self.assertTrue(reader.reciting_now, "reciting did not change the mark")
        reader.stop_reciting()
        settle()
        self.assertFalse(reader.reciting_now, "the mark was left on stop")


class EmptyKindScreenTest(unittest.TestCase):
    """The screen a kind with nothing behind it lands on."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", recitation=False, place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def empty(self, w, cat="travel"):
        listing = w.section_lists["duas"]
        kept = list(listing.passages.items)
        listing.passages._items = [d for d in kept if cat not in d.cats]
        w.dua_board.filled = None
        self.addCleanup(lambda: setattr(listing.passages, "_items", kept))
        w.open_corner("duas")
        settle()
        w.open_dua_category(cat)
        settle()
        return w

    def test_the_name_is_on_a_white_plate_with_black_letters(self):
        w = self.empty(w=self.window())
        plate = w.soon_title
        self.assertTrue(plate.isVisible())
        shot = plate.grab().toImage()
        white = black = 0
        for y in range(0, shot.height(), 2):
            for x in range(0, shot.width(), 2):
                c = shot.pixelColor(x, y)
                if c.red() > 230 and c.green() > 230 and c.blue() > 230:
                    white += 1
                elif c.red() < 60 and c.green() < 60 and c.blue() < 60:
                    black += 1
        self.assertGreater(white, black, "the plate is not mostly white")
        self.assertGreater(black, 20, "there are no black letters on it")

    def test_the_plate_sits_top_left(self):
        """It was centred across the top until Harry asked for it on the left, like the world
        screen's. A heading centred over an empty page has nothing to be centred on."""
        w = self.empty(w=self.window())
        plate, page = w.soon_title, w.corner_soon
        middle = plate.mapTo(page, plate.rect().center())
        left = plate.mapTo(page, QtCore.QPoint(0, 0)).x()
        self.assertLess(left, page.width() * 0.1, "the name is not against the left")
        self.assertLess(middle.x(), page.width() * 0.45, "the name is still in the middle")
        self.assertLess(middle.y(), page.height() * 0.25, "the name is not near the top")

    def test_the_button_says_back_and_returns_to_the_kinds(self):
        w = self.empty(w=self.window())
        button = w.soon_back_button
        self.assertEqual(w.t("corner.back"), button.text())
        self.assertNotIn(w.t("settings.main_screen"), button.text())
        button.click()
        settle()
        self.assertIs(w.dua_menu, w.corner_screen.currentWidget())

    def test_the_button_is_in_the_bottom_right(self):
        w = self.empty(w=self.window())
        button, page = w.soon_back_button, w.corner_soon
        at = button.mapTo(page, button.rect().center())
        self.assertGreater(at.x(), page.width() * 0.7, "not on the right")
        self.assertGreater(at.y(), page.height() * 0.7, "not at the bottom")


class WifiScreenTest(unittest.TestCase):
    """The Wi-Fi screen, driven against a fake nmcli. No radio is involved."""

    SCAN = ("NOVA_26DU_A2:95:WPA2\nNOVA_26DU_A2:77:WPA2\nBT-HUB-9K2:64:WPA2\n"
            "Free Library Wifi:38:\n")
    SAVED = "NOVA_26DU_A2:802-11-wireless\nlo:loopback\n"

    def window(self, online=True, join=(0, "ok", "")):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        self.asked = []

        def runner(args, timeout=None):
            self.asked.append(list(args))
            if "list" in args:
                return 0, self.SCAN, ""
            if "--active" in args:
                return 0, "NOVA_26DU_A2:802-11-wireless:wlan0\n", ""
            if any("NAME,TYPE" in a for a in args):
                return 0, self.SAVED, ""
            if "connect" in args:
                return join
            return 0, "", ""

        from salaah.network import Wifi
        w.open_wifi()
        settle()
        w.wifi_screen.wifi = Wifi(runner=runner, resolver=lambda n=None: online)
        return w

    def scanned(self, w):
        screen = w.wifi_screen
        screen.look()
        settle()
        if screen.errand is not None:
            screen.errand.wait(5000)
        settle()
        return screen

    def test_the_wifi_row_in_settings_opens_it_without_leaving_the_app(self):
        w = self.window()
        w.open_settings()
        settle()
        self.assertTrue(w.wifi_button.isVisible(), "no way to Wi-Fi from Settings")
        w.wifi_button.click()
        settle()
        self.assertIs(w.wifi_page, w.stack.currentWidget())

    def test_it_wears_the_same_strip_as_every_other_screen(self):
        """A screen without it reads as having left the app, which is the one thing it must
        never do."""
        w = self.window()
        strips = [x for x in w.wifi_page.findChildren(QtWidgets.QWidget)
                  if x.objectName() == "banner"]
        self.assertTrue(strips, "the Wi-Fi screen has no strip")
        home = [b for b in w.wifi_page.findChildren(QtWidgets.QPushButton)
                if b.objectName() == "mainScreen"]
        self.assertTrue(home, "no way back to the mat from the Wi-Fi screen")

    def test_one_row_per_network_however_many_times_it_is_seen(self):
        w = self.window()
        screen = self.scanned(w)
        names = [r.network.name for r in screen.network_rows()]
        self.assertEqual(["NOVA_26DU_A2", "BT-HUB-9K2", "Free Library Wifi"], names)

    def test_a_saved_secured_network_joins_without_asking_for_a_password(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[0].click()          # NOVA: secured but already saved
        settle()
        self.assertEqual(0, screen.pages.currentIndex(),
                         "it asked for a password it already has")

    def test_an_open_network_joins_without_asking_either(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[2].click()          # Free Library Wifi: no password
        settle()
        self.assertEqual(0, screen.pages.currentIndex())

    def test_a_new_secured_network_asks_for_one(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[1].click()          # BT-HUB: secured, never seen
        settle()
        self.assertEqual(1, screen.pages.currentIndex())
        self.assertIn("BT-HUB-9K2", screen.asking.text())

    def test_the_password_is_hidden_until_show_is_pressed(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        for ch in "Pa55":
            screen.add(ch)
        settle()
        self.assertNotIn("Pa55", screen.field.text(), "the password is on screen in the clear")
        self.assertEqual(4, len(screen.field.text()))
        screen.reveal.setChecked(True)
        settle()
        self.assertEqual("Pa55", screen.field.text(),
                         "Show password must really show it -- on a touchscreen there is no "
                         "other way to tell a key missed")

    def test_backspace_takes_one_character_off(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        for ch in "abc":
            screen.add(ch)
        screen.rub()
        screen.reveal.setChecked(True)
        settle()
        self.assertEqual("ab", screen.field.text())

    def test_shift_gives_one_capital_and_then_lets_go(self):
        """A shift that stays on is how a whole password ends up in capitals unnoticed."""
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        keys = screen.keys
        keys.flip_shift()
        self.assertIn("Q", keys.letters_on_show())
        keys.press("Q")
        settle()
        self.assertIn("q", keys.letters_on_show(), "shift stayed on")
        keys.press("b")
        screen.reveal.setChecked(True)
        settle()
        self.assertEqual("Qb", screen.field.text())

    def test_the_numbers_layer_has_digits_and_comes_back_to_letters(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        keys = screen.keys
        keys.next_layer()
        self.assertIn("1", keys.letters_on_show())
        keys.next_layer()
        keys.next_layer()
        self.assertIn("q", keys.letters_on_show(), "it never got back to the letters")

    def test_joining_with_no_internet_is_not_called_a_success(self):
        """The evening that prompted all this: associated to the wifi, unable to reach a thing."""
        w = self.window(online=False)
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        screen.go()
        settle()
        if screen.errand is not None:
            screen.errand.wait(5000)
        settle()
        self.assertIn(w.t("why.no_internet"), screen.trouble.text() + screen.saying.text())

    def test_a_wrong_password_says_so_rather_than_could_not_connect(self):
        w = self.window(join=(4, "", "Error: Secrets were required, but not provided"))
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        screen.go()
        settle()
        if screen.errand is not None:
            screen.errand.wait(5000)
        settle()
        said = screen.trouble.text() + screen.saying.text()
        self.assertIn(w.t("why.password"), said)
        self.assertNotIn(w.t("why.unknown"), said)

    def test_the_password_is_dropped_the_moment_it_has_been_used(self):
        w = self.window()
        screen = self.scanned(w)
        screen.network_rows()[1].click()
        settle()
        for ch in "hunter2":
            screen.add(ch)
        screen.go()
        settle()
        if screen.errand is not None:
            screen.errand.wait(5000)
        settle()
        self.assertEqual("", screen.typed, "the password is still held after joining")
        screen.reveal.setChecked(True)
        settle()
        self.assertNotIn("hunter2", screen.field.text())

    def test_searching_again_does_not_bring_the_mat_down(self):
        """The worker used to delete itself while the screen still pointed at it, and the
        second press died on a deleted C++ object -- which on the mat is the app going."""
        w = self.window()
        for _ in range(3):
            screen = self.scanned(w)
        self.assertEqual(3, len(screen.network_rows()))

    def test_it_is_left_alone_while_a_prayer_is_going_on(self):
        w = self.window()
        w.go_home()
        settle()
        was = w.stack.currentWidget()
        with mock.patch.object(type(w), "playing", property(lambda _s: True)):
            w.open_wifi()
            settle()
            self.assertIs(was, w.stack.currentWidget(), "a stray knee opened Wi-Fi mid-prayer")


class TheMatCanBeToldItIsAnywhereTest(unittest.TestCase):
    """2.20: a town anywhere in the world, as well as a UK postcode.

    Harry: "a person in sydney, australia wont be able to use it. postcode good for uk but
    not any where else. instead of postcode system, can we have a list of towns/cities with
    a population over a certain amount."

    One box takes either. These check it works out which was typed without a mode switch for
    a child to get wrong, and -- the important one -- that a mat put in a far-off town says
    so when its own clock has not followed.
    """

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="light", place="Bury",
                                latitude=53.5933, longitude=-2.2966),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def screen(self, w, text=""):
        w.open_place()
        settle()
        page = w.place_page
        inside = page.findChild(QtWidgets.QWidget, "placeScreen") or page
        screen = getattr(w, "place_screen", None) or inside
        screen.typed = ""
        screen.chosen = None
        for ch in text:
            screen.add(ch)
        settle()
        return screen

    def offered(self, screen):
        return [b.text() for b in screen.town_buttons if b.isVisible()]

    def test_a_postcode_is_read_as_a_postcode(self):
        w = self.window()
        screen = self.screen(w, "BL9")
        self.assertTrue(screen.looks_like_a_postcode())
        self.assertIsNotNone(screen.found)
        self.assertFalse(screen.found.is_a_town)
        self.assertEqual([], self.offered(screen), "a postcode offered a list of towns")
        self.assertTrue(screen.save.isEnabled())

    def test_the_quiet_half_of_the_map_switch_is_quieter_than_the_heading(self):
        """Two sizes on one line, which is the whole point of putting it there.

        2.22 put what the mat shares into the heading itself rather than a note underneath,
        to keep the rule that nothing but the Arabic lettering gets a paragraph on this page.
        The result shouted the small print at heading size. Harry, 12 November 2026: "reduce
        '- approximate area only' in font size to the same as description text on same page."

        Measured on the mark-up the label is given, and the sizes read out of the stylesheet
        rather than typed in here, so this keeps meaning something if the page is ever
        resized again.
        """
        import re
        w = self.window()
        w.open_settings()
        settle(3)
        page = w.stack.currentWidget()
        heads = [x for x in page.findChildren(QtWidgets.QLabel)
                 if x.objectName() == "settingHead" and "—" in (x.text() or "")]
        self.assertEqual(1, len(heads), "expected exactly one heading with a quiet half")
        said = heads[0].text()
        hint = re.search(r"settingHint \{\s*font-size:(\d+)px", w.styleSheet())
        self.assertIsNotNone(hint, "cannot find the hint size in the stylesheet")
        self.assertIn(f"font-size:{hint.group(1)}px", said,
                      "the clause is not at the size of the page's own description text")
        self.assertTrue(said.startswith("Show this mat on the map"),
                        "the loud half of the heading has changed")

    def test_the_version_is_the_quietest_thing_on_the_page(self):
        """It is the one line nobody needs until something has gone wrong.

        Its own object name rather than settingValue, so it could be made quieter without
        taking the Ring, the audio and the wifi values down with it -- which is what asking
        for "the same size as the description text" would otherwise have done to four rows
        nobody mentioned.
        """
        import re
        w = self.window()
        w.open_settings()
        settle(3)
        page = w.stack.currentWidget()
        found = [x for x in page.findChildren(QtWidgets.QLabel)
                 if x.objectName() == "settingVersion"]
        self.assertEqual(1, len(found), "the version label is not named settingVersion")
        css = w.styleSheet()
        hint = re.search(r"settingHint \{\s*font-size:(\d+)px", css)
        mine = re.search(r"settingVersion \{\s*font-size:(\d+)px", css)
        value = re.search(r"settingValue \{\s*font-size:(\d+)px", css)
        self.assertEqual(hint.group(1), mine.group(1),
                         "the version is not at description size")
        self.assertNotEqual(value.group(1), mine.group(1),
                            "the version and the values are still the same size, so nothing "
                            "was actually separated")

    def test_the_circle_by_location_says_whether_the_area_is_being_shared(self):
        """A privacy light, and the only circle in that column that is not about a cable.

        The three above it mean "is this connected". This one means "is this mat's area
        leaving the house" -- green while it is, red while it is not. RED IS THE DEFAULT AND
        THE PRIVATE STATE, which is the thing to keep in mind if the rule is ever revisited:
        on the rows above, red reads as a to-do, and here it does not.

        Checked on the built widget rather than on the setting that drove it, and checked for
        a page OPENED with the switch already on -- the wifi circle sat red on an online mat
        for three releases because it was drawn once and then never told anything.
        """
        from salaah.qt import QtGui
        from salaah.ui import BRICK, MINT
        for shared in (True, False):
            with self.subTest(shared=shared):
                w = MainWindow(load(ASSETS), available_packs(ASSETS),
                               Settings(theme="dark", place="Bury", on_the_map=shared,
                                        latitude=53.5933, longitude=-2.2966),
                               scale=1.0, save_settings=False, aspect=None, side=True)
                w.resize(1920, 1080)
                w.show()
                settle()
                w.open_settings()
                settle(3)
                want = MINT if shared else BRICK
                self.assertEqual(QtGui.QColor(want).name(), w.place_dot.color.name(),
                                 "the circle beside Location is the wrong colour")
                shut(w)

    def test_the_keyboard_is_not_crushed_by_a_list_of_towns(self):
        """The whole suite passed while this screen was visibly broken.

        Eight towns and a full keyboard do not both fit in 1080. Qt does not refuse: it gives
        the keyboard less than its minimum and the key rows draw ON TOP of one another. Four
        rows jammed into three, and every test still green, because nothing was measuring the
        one thing a person would notice first. It was found by rendering the screen and
        looking at it.

        Two changes, and this holds both: the list offers five rather than eight, and a key's
        minimum height came down so that where room IS short the keyboard shrinks instead of
        overlapping. Putting either back makes this fail.

        The assertion is about the rows and not about the numbers, so it keeps meaning
        something if the list or the key size is ever tuned again.
        """
        w = self.window()
        screen = self.screen(w, "sy")
        self.assertTrue(self.offered(screen), "no towns were offered, so this proved nothing")

        keys = [k for k in screen.keys.findChildren(QtWidgets.QWidget)
                if k.objectName() == "key" and k.isVisible()]
        self.assertTrue(keys, "no keys found, so this proved nothing")
        rows: dict[int, int] = {}
        for key in keys:
            rows.setdefault(key.mapTo(w, key.rect().topLeft()).y(), key.height())
        tops = sorted(rows)
        self.assertGreater(len(tops), 1, "a one-row keyboard cannot overlap, so check the find")
        for above, below in zip(tops, tops[1:]):
            self.assertLessEqual(
                above + rows[above], below,
                f"a row of keys at y={above} is drawn over the row at y={below}")

        self.assertGreaterEqual(
            screen.keys.height(), screen.keys.minimumSizeHint().height(),
            "the keyboard was given less room than it says it needs")

        for button in screen.town_buttons:
            if button.isVisible():
                self.assertGreaterEqual(button.height(), button.minimumHeight(),
                                        "a town row was squeezed below its own minimum")

    def test_a_postcode_is_capitalised_and_a_town_is_not_shouted_back(self):
        """Both halves, because fixing either one alone broke the other.

        Postcodes have read in capitals since the screen existed and should keep doing it:
        BL9, not bl9. But the same box now takes "bury st edmunds", and upper-casing the
        field -- which is what it used to do unconditionally -- turns that into BURY ST
        EDMUNDS, which is not how anybody writes a town.

        So the box capitalises only while what is typed could still grow into a postcode. A
        town's name is therefore capitalised for its first letter or two and then left alone,
        which is why the assertion below starts at the third character.
        """
        w = self.window()
        self.assertEqual("BL9", self.screen(w, "bl9").field.text(),
                         "postcodes are written in capitals")
        self.assertEqual("CF10", self.screen(w, "cf10").field.text())
        for name in ("bury st edmunds", "sydney", "kuala lumpur"):
            with self.subTest(name):
                self.assertEqual(name, self.screen(w, name).field.text(),
                                 "a town's name was shouted back in capitals")

    def test_a_name_is_read_as_a_town(self):
        w = self.window()
        screen = self.screen(w, "syd")
        self.assertFalse(screen.looks_like_a_postcode())
        offered = self.offered(screen)
        self.assertTrue(offered, "nothing was offered for a part-typed town")
        self.assertTrue(any("Sydney" in said for said in offered))
        self.assertFalse(screen.save.isEnabled(), "saved before anything was chosen")

    def test_choosing_one_shows_its_times_before_anything_is_saved(self):
        """The oldest rule on this screen, and it has to survive the new path."""
        w = self.window()
        screen = self.screen(w, "sydney")
        screen.pick(0)
        settle()
        self.assertIsNotNone(screen.found)
        self.assertEqual("Sydney", screen.found.outward)
        self.assertTrue(screen.save.isEnabled())
        self.assertIn(":", screen.preview.text(), "no times were shown before saving")
        self.assertEqual("Bury", w.settings.place, "it saved without being asked to")

    def test_a_mat_whose_clock_is_wrong_is_told_so(self):
        """The failure a world-wide list introduces and a UK-only one could not.

        Times come from the Pi's system timezone and the coordinates together. Pick Sydney
        on a mat still set to London and every time is eleven hours out, with nothing on
        screen looking broken.
        """
        w = self.window()
        screen = self.screen(w, "sydney")
        screen.pick(0)
        settle()
        self.assertTrue(screen.clock.isVisible(), "no warning for a mat in the wrong zone")
        self.assertIn("Australia/Sydney", screen.clock.text())

    def test_a_town_in_this_mats_own_timezone_says_nothing(self):
        """The warning has to stay quiet where it belongs, or it is noise."""
        w = self.window()
        screen = self.screen(w, "BL9")
        self.assertFalse(screen.clock.isVisible())
        screen = self.screen(w, "bury")
        screen.pick(0)
        settle()
        self.assertEqual("Bury", screen.found.outward)
        self.assertFalse(screen.clock.isVisible(), "warned about a mat that is in Bury")

    def test_a_name_longer_than_a_postcode_can_be_typed(self):
        """It used to force capitals and stop at eight characters."""
        w = self.window()
        screen = self.screen(w, "Bury St Edmunds")
        self.assertEqual("Bury St Edmunds", screen.typed)
        self.assertTrue(any("Edmunds" in said for said in self.offered(screen))
                        or (screen.found and "Edmunds" in screen.found.outward))

    def test_typing_again_forgets_what_was_chosen(self):
        """Otherwise the times on screen belong to a town the box no longer names."""
        w = self.window()
        screen = self.screen(w, "sydney")
        screen.pick(0)
        settle()
        self.assertIsNotNone(screen.found)
        screen.rub()
        settle()
        self.assertIsNone(screen.chosen, "the old choice survived the name changing")

    def test_nowhere_of_that_name_says_so(self):
        w = self.window()
        screen = self.screen(w, "zzzzzz")
        self.assertIsNone(screen.found)
        self.assertFalse(screen.save.isEnabled())
        self.assertEqual([], self.offered(screen))
        self.assertTrue(screen.answer.text().strip())

    def test_saving_a_town_keeps_its_name_and_not_a_code(self):
        w = self.window()
        screen = self.screen(w, "sydney")
        screen.pick(0)
        settle()
        said = []
        screen.saved.connect(lambda name, lat, lon: said.append((name, lat, lon)))
        screen.keep()
        settle()
        self.assertEqual(1, len(said))
        self.assertEqual("Sydney", said[0][0])
        self.assertAlmostEqual(-33.868, said[0][1], places=2)


class PlaceScreenTest(unittest.TestCase):
    """Telling the mat where it is. The failure this stops is a mat confidently showing the
    wrong town's times with nothing on screen to suggest it."""

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury",
                                latitude=53.5933, longitude=-2.2966),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def typed(self, screen, text):
        for ch in text:
            screen.add(ch)
        settle()

    def test_the_location_row_in_settings_opens_it(self):
        w = self.window()
        w.open_settings()
        settle()
        self.assertTrue(w.place_button.isVisible(), "no way to set the location from Settings")
        w.place_button.click()
        settle()
        self.assertIs(w.place_page, w.stack.currentWidget())

    def test_it_wears_the_same_strip_as_every_other_screen(self):
        w = self.window()
        w.open_place()
        settle()
        strips = [x for x in w.place_page.findChildren(QtWidgets.QWidget)
                  if x.objectName() == "banner"]
        self.assertTrue(strips, "the place screen has no strip")

    def test_typing_a_postcode_shows_what_it_would_mean_before_saving(self):
        """Showing the times first is the point: a typo is caught by the times looking wrong,
        not a fortnight later."""
        w = self.window()
        w.open_place()
        settle()
        screen = w.place_screen
        self.typed(screen, "cf10")
        self.assertEqual("CF10", screen.field.text(), "postcodes are written in capitals")
        self.assertIsNotNone(screen.found)
        for prayer in ("fajr", "dhuhr", "maghrib"):
            self.assertIn(w.t(f"prayer.{prayer}"), screen.preview.text())
        self.assertEqual("Bury", w.settings.place, "it saved before being asked to")

    def test_saving_really_moves_the_prayer_times_and_the_strip(self):
        w = self.window()
        before = dict(w.prayer_times())
        w.open_place()
        settle()
        self.typed(w.place_screen, "cf10")
        w.place_screen.keep()
        settle()
        w.tick()
        settle()
        self.assertEqual("CF10", w.settings.place)
        self.assertAlmostEqual(51.47, w.settings.latitude, places=1)
        after = dict(w.prayer_times())
        moved = max(abs((before[p].hour * 60 + before[p].minute)
                        - (after[p].hour * 60 + after[p].minute))
                    for p in before if before[p] and after[p])
        self.assertGreater(moved, 4, "the times did not follow the mat to Cardiff")
        said = " ".join(x.text() for x in w.home.findChildren(QtWidgets.QLabel) if x.text())
        self.assertIn("CF10", said, "the strip still names the old place")

    def test_the_times_cache_does_not_serve_the_old_towns_times(self):
        """The cache is keyed on the coordinates, so it should invalidate itself -- but a cache
        that decides for itself when it is stale is exactly what would show Bury's times in
        Cardiff for the rest of the day."""
        w = self.window()
        w.prayer_times()
        w.open_place()
        settle()
        self.typed(w.place_screen, "cf10")
        w.place_screen.keep()
        settle()
        fresh = w.prayer_times()
        straight = __import__("salaah.prayer_times", fromlist=["times_for"])
        from salaah.prayer_times import Place, times_for
        from datetime import datetime
        want = times_for(datetime.now().date(),
                         Place(w.settings.latitude, w.settings.longitude, "CF10"),
                         w.school.id, high_latitude=w.settings.high_latitude)
        self.assertEqual(want["fajr"], fresh["fajr"], "a stale time was served")

    def test_a_postcode_it_does_not_know_is_refused_and_cannot_be_saved(self):
        w = self.window()
        w.open_place()
        settle()
        screen = w.place_screen
        self.typed(screen, "zz99")
        self.assertIsNone(screen.found)
        self.assertFalse(screen.save.isEnabled(), "it would have saved a place it cannot find")
        self.assertEqual("", screen.preview.text())
        screen.keep()
        settle()
        self.assertEqual("Bury", w.settings.place, "it moved the mat somewhere unknown")

    def test_nothing_typed_yet_offers_nothing_to_save(self):
        w = self.window()
        w.open_place()
        settle()
        self.assertFalse(w.place_screen.save.isEnabled())

    def test_a_full_postcode_is_understood_not_refused(self):
        """People type their postcode the way they write it."""
        w = self.window()
        w.open_place()
        settle()
        screen = w.place_screen
        self.typed(screen, "bl9 0ab")
        self.assertIsNotNone(screen.found, "a whole postcode was refused")
        self.assertEqual("BL9", screen.found.outward)

    def test_backspace_works_and_takes_the_answer_with_it(self):
        w = self.window()
        w.open_place()
        settle()
        screen = w.place_screen
        # BL9 backspaces to "BL", which is not a postcode. CF10 would backspace to CF1, which
        # IS one -- a real Cardiff district that is in the table -- so using that here tested
        # nothing and failed for being right.
        self.typed(screen, "bl9")
        self.assertIsNotNone(screen.found)
        screen.rub()
        settle()
        self.assertEqual("BL", screen.field.text())
        self.assertIsNone(screen.found, "it still offers the answer for a postcode now changed")
        self.assertFalse(screen.save.isEnabled())

    def test_it_is_left_alone_while_a_prayer_is_going_on(self):
        w = self.window()
        w.go_home()
        settle()
        was = w.stack.currentWidget()
        with mock.patch.object(type(w), "playing", property(lambda _s: True)):
            w.open_place()
            settle()
            self.assertIs(was, w.stack.currentWidget())

    def test_the_keyboard_fills_the_screen_it_is_given(self):
        """A touchscreen keyboard huddled in the middle of a 1920 screen is a keyboard you miss.
        Measured off the drawn keys, not off the layout's intentions."""
        w = self.window()
        w.open_place()
        settle()
        keys = w.place_screen.keys
        drawn = [k for k in keys.keys if k.isVisible()]
        self.assertTrue(drawn)
        widest = max(k.width() for k in drawn)
        self.assertGreater(widest, w.px(140), f"the keys are only {widest}px wide")
        self.assertGreater(max(k.height() for k in drawn), w.px(120))
        left = min(k.mapTo(keys, k.rect().topLeft()).x() for k in drawn)
        right = max(k.mapTo(keys, k.rect().topRight()).x() for k in drawn)
        self.assertGreater(right - left, keys.width() * 0.92,
                           "the keyboard is not using the width it has")

    def test_every_row_of_keys_is_the_same_size(self):
        """They are laid out in units so a key is a key wherever it is. Rows that size
        themselves independently give a keyboard that looks broken and reads worse."""
        w = self.window()
        w.open_place()
        settle()
        drawn = [k for k in w.place_screen.keys.keys if k.isVisible()]
        widths = {k.width() for k in drawn}
        self.assertLessEqual(max(widths) - min(widths), 4,
                             f"key widths range over {sorted(widths)}")


class WifiCircleTest(unittest.TestCase):
    """The circle beside the Wi-Fi row in Settings.

    It was drawn and then never told anything, so it sat red on a mat that was online. Harry
    spotted it on his: "the wifi circle is red even though it is connected". A circle that is
    always red is worse than no circle, because it is an answer rather than a blank.
    """

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def radio(self, w, card=True, joined="NOVA_26DU_A2", reaches=True):
        """A mat whose wifi says what we tell it to, with no radio in sight."""
        from salaah.network import Wifi

        def runner(args, timeout=None):
            if "status" in args:
                return (0, "wifi\nethernet\n" if card else "ethernet\n", "")
            if "--active" in args:
                return 0, (f"{joined}:802-11-wireless:wlan0\n" if joined else ""), ""
            return 0, "", ""

        w.wifi = Wifi(runner=runner, resolver=lambda n=None: reaches)
        return w

    def settled(self, w):
        w.open_settings()
        settle()
        if getattr(w, "wifi_errand", None) is not None:
            w.wifi_errand.wait(5000)
        settle()
        return w.wifi_dot.color.name().upper()

    def test_green_when_it_is_on_a_network_and_can_reach_the_world(self):
        from salaah.ui import MINT
        w = self.radio(self.window())
        self.assertEqual(MINT, self.settled(w), "green when connected")
        self.assertIn("NOVA_26DU_A2", w.wifi_dot.toolTip())

    def test_red_when_it_is_on_no_network(self):
        from salaah.ui import BRICK
        w = self.radio(self.window(), joined="")
        self.assertEqual(BRICK, self.settled(w), "red when not connected")

    def test_red_when_the_mat_has_no_wifi_at_all(self):
        from salaah.ui import BRICK
        w = self.radio(self.window(), card=False)
        self.assertEqual(BRICK, self.settled(w))

    def test_amber_when_it_has_joined_a_network_that_reaches_nothing(self):
        """The evening the mat spent associated to the router and unable to fetch a thing.
        Green would have said everything was fine."""
        from salaah.ui import AMBER
        w = self.radio(self.window(), reaches=False)
        self.assertEqual(AMBER, self.settled(w))

    def test_a_mat_with_no_wifi_is_never_asked_what_it_is_joined_to(self):
        """nmcli is slow enough that the order matters: each question is only asked when the
        one before it makes it worth asking."""
        from salaah.network import Wifi
        asked = []

        def runner(args, timeout=None):
            asked.append(list(args))
            return 0, "ethernet\n", ""

        w = self.window()
        w.wifi = Wifi(runner=runner, resolver=lambda n=None: self.fail("looked a name up"))
        self.settled(w)
        self.assertEqual(1, len(asked), f"asked more than it needed: {asked}")

    def test_opening_settings_twice_quickly_starts_one_errand(self):
        w = self.radio(self.window())
        w.open_settings()
        first = w.wifi_errand
        w.open_settings()
        self.assertIs(first, w.wifi_errand, "a second errand was started over the first")
        if first is not None:
            first.wait(5000)
        settle()

    def test_the_circle_is_asked_again_on_the_way_back_from_the_wifi_screen(self):
        """Joining a network and coming back should not leave the old answer on screen."""
        from salaah.ui import BRICK, MINT
        w = self.radio(self.window(), joined="")
        self.assertEqual(BRICK, self.settled(w))
        w.open_wifi()
        settle()
        self.radio(w, joined="NOVA_26DU_A2")          # as if it had just been joined
        w.wifi_screen.leave.click()
        settle()
        if getattr(w, "wifi_errand", None) is not None:
            w.wifi_errand.wait(5000)
        settle()
        self.assertEqual(MINT, w.wifi_dot.color.name().upper(), "the circle kept a stale answer")


class BluetoothScreenTest(unittest.TestCase):
    """The Bluetooth screen and the circle beside its row in Settings.

    Harry: "i want a Bluetooth button that will allow users to connect wireless audio
    speakers/headset if they wish too. the button should be located in settings page underneath
    the wifi. use the same filled circle either red or green if connected."

    Driven against a fake bluetoothctl. The container has no adapter, no BlueZ and no sound
    card, so the recordings are what his mat printed on 14 October 2026 -- see BluetoothTest in
    test_core, which these share their shape with.
    """

    SHOW = ("Controller 2C:CF:67:F0:AA:5F (public)\n\tName: mysalaah\n\tPowered: yes\n"
            "\tPairable: yes\n"
            "\tUUID: Audio Source              (0000110a-0000-1000-8000-00805f9b34fb)\n")
    RING = ("Device F4:6E:48:77:80:60 (public)\n\tName: ATG-SJL\n\tClass: 0x00000540\n"
            "\tIcon: input-keyboard\n\tPaired: yes\n\tTrusted: yes\n\tConnected: yes\n")
    SPEAKER = ("Device 11:22:33:44:55:66 (public)\n\tName: XinYi\n\tClass: 0x00240414\n"
               "\tIcon: audio-card\n\tPaired: yes\n\tTrusted: yes\n\tConnected: {live}\n"
               "\tUUID: Audio Sink                (0000110b-0000-1000-8000-00805f9b34fb)\n")
    SCAN = ("Discovery started\n"
            "[NEW] Device 11:22:33:44:55:66 XinYi\n"
            "[CHG] Device 11:22:33:44:55:66 RSSI: -47\n"
            "[CHG] Device 11:22:33:44:55:66 Class: 0x00240414\n"
            "[NEW] Device AA:BB:CC:DD:EE:FF AA-BB-CC-DD-EE-FF\n"
            "[CHG] Device AA:BB:CC:DD:EE:FF RSSI: -88\n"
            "[NEW] Device F4:6E:48:77:80:60 ATG-SJL\n"
            "[CHG] Device F4:6E:48:77:80:60 RSSI: -40\n")
    WPCTL = ("Audio\n ├─ Sinks:\n"
             " │      56. Built-in Audio Digital Stereo (HDMI) [vol: 0.95]\n"
             " │  *   79. XinYi                               [vol: 0.40]\n │  \n")

    def window(self, lang="en"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury", lang=lang),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def sound(self, speaker_on=True, adapter=True, connect=(0, "Connection successful\n", "")):
        """A Sound that answers the way the mat did, with a note of what was asked."""
        from salaah.bluetooth import Sound
        asked = []
        live = "yes" if speaker_on else "no"
        connected = "Device F4:6E:48:77:80:60 ATG-SJL\n" + (
            "Device 11:22:33:44:55:66 XinYi\n" if speaker_on else "")

        def runner(args, timeout=None):
            asked.append(list(args))
            # Matched on membership, not on args[0]. A scan is asked for as
            # ["--timeout", "10", "scan", "on"], so a branch keyed on the first word never
            # fired and every row in these tests was coming from the remembered-devices list
            # instead -- which made the scan fixture below dead weight and several of these
            # tests weaker than they read.
            if "show" in args:
                return (0, self.SHOW, "") if adapter else (0, "No default controller\n", "")
            if "scan" in args:
                return 0, self.SCAN, ""
            if "devices" in args:
                return 0, (connected if len(args) > 1 else
                           "Device F4:6E:48:77:80:60 ATG-SJL\n"
                           "Device 11:22:33:44:55:66 XinYi\n"), ""
            if "info" in args:
                return 0, (self.RING if args[1].startswith("F4")
                           else self.SPEAKER.format(live=live)), ""
            if "connect" in args:
                return connect
            return 0, "", ""

        s = Sound(runner=runner, outputs=lambda a, timeout=None: (0, self.WPCTL, ""))
        s.asked = asked
        return s

    def opened(self, w, **kw):
        """The Bluetooth screen, open, with its first look round finished."""
        w.open_bluetooth()
        settle()
        screen = w.bt_screen
        screen.sound = self.sound(**kw)
        screen.look()
        self.wait(screen)
        return screen

    def wait(self, screen):
        for _ in range(6):
            settle()
            if screen.errand is not None:
                screen.errand.wait(5000)
            settle()

    def circle(self, w, **kw):
        from salaah.bluetooth import Sound
        w.sound = self.sound(**kw)
        w.open_settings()
        settle()
        if getattr(w, "bt_errand", None) is not None:
            w.bt_errand.wait(5000)
        settle()
        return w.bt_dot.color.name().upper()

    # -- the row Harry asked for --------------------------------------------------------------

    def test_the_four_things_the_mat_attaches_to_are_in_the_order_harry_listed(self):
        """Harry, 1.82: "the button should be located in settings page underneath the wifi".
        Harry, 1.83: "on left side we will have MySalaah Ring, Bluetooth, Wi-Fi, Location".

        The second one moved Bluetooth above Wi-Fi, so this test was turned round rather than
        deleted: what it is for is that the order on the screen is the order Harry asked for,
        and the order he asked for changed. Read off where the boxes actually landed, not off
        the order they were added in.
        """
        w = self.window()
        w.open_settings()
        settle()
        for button in (w.ring_button, w.bt_button, w.wifi_button, w.place_button):
            self.assertTrue(button.isVisible(), f"{button.text()} is not on the page")
        down = [b.text() for b in sorted(
            (w.ring_button, w.bt_button, w.wifi_button, w.place_button),
            key=lambda b: b.mapTo(w.settings_screen, QtCore.QPoint(0, 0)).y())]
        self.assertEqual([w.t("settings.buttons"), w.t("bt.row"), w.t("wifi.row"),
                          w.t("place.row")], down, f"they run {down}")

    def test_it_carries_the_same_filled_circle_as_the_wifi_row(self):
        w = self.window()
        w.open_settings()
        settle()
        self.assertEqual(type(w.wifi_dot), type(w.bt_dot), "a different kind of circle")
        self.assertEqual(w.wifi_dot.size(), w.bt_dot.size(), "a different size of circle")

    def test_the_row_opens_the_screen_without_leaving_the_app(self):
        w = self.window()
        w.open_settings()
        settle()
        w.bt_button.click()
        settle()
        self.assertIs(w.bt_page, w.stack.currentWidget())

    def test_it_wears_the_same_strip_as_every_other_screen(self):
        w = self.window()
        w.open_bluetooth()
        settle()
        strips = [x for x in w.bt_page.findChildren(QtWidgets.QWidget)
                  if x.objectName() == "banner"]
        self.assertTrue(strips, "the Bluetooth screen has no strip")
        home = [b for b in w.bt_page.findChildren(QtWidgets.QPushButton)
                if b.objectName() == "mainScreen"]
        self.assertTrue(home, "no way back to the mat from the Bluetooth screen")

    # -- the circle ---------------------------------------------------------------------------

    def test_green_when_a_speaker_is_connected(self):
        from salaah.ui import MINT
        w = self.window()
        self.assertEqual(MINT, self.circle(w, speaker_on=True))
        self.assertIn("XinYi", w.bt_dot.toolTip())

    def test_red_when_only_the_ring_is_connected(self):
        """The one that would be easy to get wrong. The ring is Bluetooth and is connected
        nearly always; a circle that counted links would be green on a mat with no speaker."""
        from salaah.ui import BRICK
        w = self.window()
        self.assertEqual(BRICK, self.circle(w, speaker_on=False))

    def test_red_and_a_different_word_when_the_mat_has_no_bluetooth(self):
        from salaah.ui import BRICK
        w = self.window()
        self.assertEqual(BRICK, self.circle(w, adapter=False))
        self.assertEqual(w.t("bt.no_adapter"), w.bt_dot.toolTip())

    def test_opening_settings_twice_quickly_starts_one_errand(self):
        w = self.window()
        w.sound = self.sound()
        w.open_settings()
        first = w.bt_errand
        w.open_settings()
        self.assertIs(first, w.bt_errand, "a second errand was started over the first")
        if first is not None:
            first.wait(5000)
        settle()

    def test_connecting_a_speaker_repaints_the_circle_without_reopening_settings(self):
        from salaah.ui import BRICK, MINT
        w = self.window()
        self.assertEqual(BRICK, self.circle(w, speaker_on=False))
        screen = self.opened(w, speaker_on=False)
        w.sound = self.sound(speaker_on=True)       # as if it had just connected
        screen.changed.emit()
        settle()
        if getattr(w, "bt_errand", None) is not None:
            w.bt_errand.wait(5000)
        settle()
        self.assertEqual(MINT, w.bt_dot.color.name().upper(),
                         "Settings still shows the old answer")

    # -- the list -----------------------------------------------------------------------------

    def test_a_speaker_that_was_found_gets_a_row(self):
        w = self.window()
        screen = self.opened(w)
        names = [r.device.shown for r in screen.device_rows()]
        self.assertIn("XinYi", names, f"listed {names}")

    def test_a_thing_with_no_name_but_its_own_address_is_left_out(self):
        """Mostly fitness bands and tyre sensors. Eleven rows of hexadecimal is a list somebody
        gives up on before reaching the speaker underneath it."""
        w = self.window()
        screen = self.opened(w)
        shown = [r.device.shown for r in screen.device_rows()]
        self.assertNotIn("AA:BB:CC:DD:EE:FF", shown, f"listed {shown}")
        self.assertNotIn("AA-BB-CC-DD-EE-FF", shown, f"listed {shown}")

    def test_the_ring_is_in_the_list_but_is_not_marked_as_making_a_noise(self):
        """Hiding it would be a lie about what the mat has connected. Marking it as audio would
        put it above the speaker in the list."""
        w = self.window()
        screen = self.opened(w)
        rows = {r.device.shown: r.device for r in screen.device_rows()}
        self.assertIn("ATG-SJL", rows, f"listed {list(rows)}")
        self.assertFalse(rows["ATG-SJL"].audio, "the ring is marked as a speaker")
        self.assertTrue(rows["XinYi"].audio)

    def test_the_connected_speaker_is_offered_first(self):
        w = self.window()
        screen = self.opened(w)
        self.assertEqual("XinYi", screen.device_rows()[0].device.shown)

    def test_tapping_a_speaker_connects_it(self):
        w = self.window()
        screen = self.opened(w, speaker_on=False)
        row = next(r for r in screen.device_rows() if r.device.shown == "XinYi")
        row.click()
        self.wait(screen)
        asked = [a for a in screen.sound.asked if a[0] == "connect"]
        self.assertEqual([["connect", "11:22:33:44:55:66"]], asked)

    def test_tapping_the_connected_one_disconnects_it_rather_than_connecting_it_again(self):
        w = self.window()
        screen = self.opened(w, speaker_on=True)
        row = next(r for r in screen.device_rows() if r.device.shown == "XinYi")
        self.assertTrue(row.device.connected, "the fixture did not report it connected")
        row.click()
        self.wait(screen)
        verbs = [a[0] for a in screen.sound.asked if a[0] in ("connect", "disconnect")]
        self.assertIn("disconnect", verbs)
        self.assertNotIn("connect", verbs)

    def test_a_speaker_that_is_switched_off_is_told_about_in_words(self):
        w = self.window()
        screen = self.opened(w, speaker_on=False,
                             connect=(1, "", "Failed to connect: "
                                            "org.bluez.Error.ConnectionAttemptFailed "
                                            "br-connection-page-timeout"))
        row = next(r for r in screen.device_rows() if r.device.shown == "XinYi")
        row.click()
        self.wait(screen)
        self.assertEqual(w.t("bt.why.off"), screen.saying.text())
        self.assertNotEqual("bt.why.off", screen.saying.text(), "the key leaked onto the screen")

    def test_the_corner_says_where_the_sound_is_going(self):
        w = self.window()
        screen = self.opened(w, speaker_on=True)
        self.assertIn("XinYi", screen.where.text())

    def test_it_says_so_plainly_when_no_speaker_is_connected(self):
        w = self.window()
        screen = self.opened(w, speaker_on=False)
        self.assertEqual(w.t("bt.off"), screen.where.text())

    # -- the words ----------------------------------------------------------------------------

    def test_every_language_that_has_the_wifi_wording_has_this_wording_too(self):
        """Arabic is a partial pack with no wifi.* either and falls back to English, which is
        the design. Any pack that does carry the Wi-Fi words must carry these."""
        keys = ("bt.row", "bt.title", "bt.again", "bt.looking", "bt.none", "bt.off",
                "bt.no_adapter", "bt.connected", "bt.connecting", "bt.disconnecting",
                "bt.saved", "bt.this_one", "bt.sound_goes",
                "bt.why.adapter", "bt.why.already", "bt.why.busy", "bt.why.missing",
                "bt.why.no_audio", "bt.why.off", "bt.why.permission", "bt.why.refused",
                "bt.why.slow", "bt.why.unknown")
        for lang, pack in full_packs(available_packs(ASSETS)).items():
            if "wifi.row" not in pack.ui:
                continue
            for key in keys:
                self.assertTrue(pack.ui.get(key, "").strip(), f"{lang} is missing {key}")

    def test_the_lines_that_name_a_device_keep_the_place_to_put_the_name(self):
        for lang, pack in full_packs(available_packs(ASSETS)).items():
            if "wifi.row" not in pack.ui:
                continue
            for key in ("bt.connected", "bt.connecting", "bt.disconnecting", "bt.sound_goes"):
                self.assertIn("{name}", pack.ui.get(key, ""), f"{lang}: {key}")

    def test_the_row_fits_a_common_monitor_in_every_language(self):
        """Settings was 80px short of a 1920x1080 screen before the rows taken out in 1.81
        bought it back, and this spends some of that. Checked in every language because the
        wording is a different length in each."""
        for lang in sorted(full_packs(available_packs(ASSETS))):
            with self.subTest(lang):
                w = self.window(lang=lang)
                w.resize(1920, 1080)
                w.stack.setCurrentWidget(w.settings_screen)
                settle()
                self.assertEqual(0, w.settings_scroll.verticalScrollBar().maximum(),
                                 "Settings now scrolls on a 1920x1080 monitor")
                self.assertTrue(w.bt_button.isVisible())
                self.assertGreaterEqual(
                    w.bt_button.height(), w.bt_button.minimumSizeHint().height() - 1,
                    f"{lang}: the Bluetooth row is squeezed to {w.bt_button.height()} "
                    f"of {w.bt_button.minimumSizeHint().height()}")

    # -- the things it must not do ------------------------------------------------------------

    def test_it_does_not_open_during_a_prayer(self):
        """The big screen is busy and the touch is almost certainly a stray knee."""
        w = self.window()
        # `playing` is "there is a session AND the prayer screen is the one showing", so it is
        # put into that state rather than set -- a flag that could be set would not be the same
        # question the real thing asks.
        w.start("dhuhr", w.school.prayers["dhuhr"][0])
        settle()
        self.assertTrue(w.playing, "the mat is not in a prayer, so this proves nothing")
        was = w.stack.currentWidget()
        w.open_bluetooth()
        settle()
        self.assertIs(was, w.stack.currentWidget())
        self.assertIsNone(getattr(w, "bt_screen", None),
                          "the screen was built mid-prayer")

    def test_connecting_a_speaker_never_touches_the_ring(self):
        """The ring is on the same adapter. Pairing a speaker must not cost somebody the button
        they pray with."""
        w = self.window()
        screen = self.opened(w, speaker_on=False)
        row = next(r for r in screen.device_rows() if r.device.shown == "XinYi")
        row.click()
        self.wait(screen)
        meddling = [a for a in screen.sound.asked
                    if "F4:6E:48:77:80:60" in a and a[0] not in ("info", "devices")]
        self.assertEqual([], meddling, f"it reached for the ring: {meddling}")


class WhatTheMatIsAttachedToTest(unittest.TestCase):
    """The two-column block at the foot of Settings, and the space the 1.83 removals bought.

    Harry: "in settings menu when both Bluetooth devices are connected they are being displayed
    both on a single sentence under 'MySalaah Ring'. i want 2 columns, on left side we will
    have MySalaah Ring, Bluetooth, Wi-Fi, Location, on their respective right will their chosen
    / designated value. keep the same box and text look of W-Fi button. retain the filled
    circles to the left."

    The complaint underneath the layout request is a real fault, and it is the part worth
    testing hardest: a Bluetooth speaker is an input device as well as a speaker -- A/V Remote
    Control gives it play, pause and volume keys -- so buttons.py saw the speaker on the same
    bus as the ring and both names were joined into one sentence under the ring's heading.
    """

    def window(self, lang="en", theme="dark"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=theme, place="Bury", lang=lang),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1920, 1080)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def speaker(self, name="XinYi"):
        from salaah.bluetooth import Speaker
        return Speaker(mac="11:22:33:44:55:66", name=name, audio=True, connected=True,
                       paired=True)

    def filled_in(self, w, ring=("MySalaah Ring",), speaker="XinYi", network="NOVA_26DU_A2"):
        """The page with something on every line of the block."""
        w.open_settings()
        settle()
        w.on_devices(list(ring))
        if speaker:
            w.show_bt_state(self.speaker(speaker))
        else:
            w.show_bt_state(None)
        w.show_wifi_state(network, True)
        settle()
        return w

    def boxes(self, w):
        return (w.ring_button, w.bt_button, w.wifi_button, w.place_button)

    def values(self, w):
        return (w.devices_label, w.bt_value, w.wifi_value, w.place_label)

    # -- the fault Harry reported ------------------------------------------------------------

    def test_the_speaker_is_not_named_on_the_ring_line_as_well_as_its_own(self):
        """The whole of what he reported. Both devices arrive through on_devices because both
        are Bluetooth input devices; only one of them is a ring."""
        w = self.filled_in(w=self.window(), ring=("MySalaah Ring", "XinYi"), speaker="XinYi")
        said = w.devices_label.text()
        self.assertIn("MySalaah Ring", said)
        self.assertNotIn("XinYi", said, f"the speaker is still on the ring's line: {said!r}")
        self.assertEqual("XinYi", w.bt_value.text(), "and it should be on its own line")

    def test_two_devices_are_two_lines_and_not_one_sentence(self):
        w = self.filled_in(w=self.window(), ring=("MySalaah Ring", "XinYi"), speaker="XinYi")
        for value in self.values(w):
            self.assertNotIn(",", value.text(),
                             f"{value.text()!r} is still a list in one box")

    def test_a_speaker_on_its_own_leaves_the_ring_line_saying_nothing_is_connected(self):
        """The case that catches a filter that merely hides the name: with the speaker taken
        out there is no ring, and the line has to say so rather than go blank or keep a comma."""
        w = self.filled_in(w=self.window(), ring=("XinYi",), speaker="XinYi")
        self.assertEqual(w.t("settings.no_buttons"), w.devices_label.text())

    def test_the_rings_circle_is_red_when_only_the_speaker_is_connected(self):
        from salaah.ui import BRICK, MINT
        w = self.filled_in(w=self.window(), ring=("XinYi",), speaker="XinYi")
        self.assertEqual(BRICK, w.ring_dot.color.name().upper(),
                         "the ring's circle is green with no ring connected")
        w.on_devices(["XinYi", "MySalaah Ring"])
        settle()
        self.assertEqual(MINT, w.ring_dot.color.name().upper(),
                         "and green again once the ring is actually there")

    def test_the_main_screens_circle_still_counts_the_speaker_as_a_button(self):
        """The other side of the same coin, and the reason there are two lists rather than one.
        A speaker's media keys really do work as a button -- pressing one advances the prayer
        -- so the circle that asks "is there a button" must not be narrowed along with the one
        that asks "is the ring here"."""
        from salaah.ui import MINT
        w = self.window()
        w.open_settings()
        settle()
        w.show_bt_state(self.speaker())
        w.on_devices(["XinYi"])
        settle()
        self.assertEqual(MINT, w.dot.color.name().upper(),
                         "the main screen says no button on a mat whose speaker is a button")

    def test_nothing_is_filtered_before_a_speaker_is_known(self):
        """A mat that has not been asked about Bluetooth yet keeps every name, so the worst
        case is what 1.82 did rather than a ring that has gone missing."""
        w = self.window()
        w.open_settings()
        settle()
        w.speaker_name = ""
        w.on_devices(["MySalaah Ring", "Some Speaker"])
        settle()
        self.assertIn("MySalaah Ring", w.devices_label.text())
        self.assertIn("Some Speaker", w.devices_label.text())

    # -- the two columns -----------------------------------------------------------------------

    def test_the_values_line_up_in_a_column_of_their_own(self):
        """The point of the two columns. In four separate rows each value began wherever the
        label before it happened to end, which is the mess this replaced."""
        w = self.filled_in(self.window())
        edges = {v.objectName() + str(i): v.mapTo(w, QtCore.QPoint(0, 0)).x()
                 for i, v in enumerate(self.values(w))}
        self.assertEqual(1, len(set(edges.values())),
                         f"the values start at different places: {edges}")

    def test_every_value_is_to_the_right_of_its_own_label(self):
        w = self.filled_in(self.window())
        for box, value in zip(self.boxes(w), self.values(w)):
            with self.subTest(box.text()):
                self.assertGreater(value.mapTo(w, QtCore.QPoint(0, 0)).x(),
                                   box.mapTo(w, QtCore.QPoint(0, 0)).x(),
                                   "the value is not on the right of its label")
                # On the same line, not merely to the right of it somewhere below.
                self.assertLess(
                    abs(value.mapTo(w, value.rect().center()).y()
                        - box.mapTo(w, box.rect().center()).y()),
                    w.px(20), "the value is not level with its label")

    def test_each_line_says_what_that_thing_has_got(self):
        w = self.filled_in(self.window())
        self.assertEqual("MySalaah Ring", w.devices_label.text())
        self.assertEqual("XinYi", w.bt_value.text())
        self.assertEqual("NOVA_26DU_A2", w.wifi_value.text())
        self.assertEqual("Bury", w.place_label.text())

    def test_an_empty_line_says_so_rather_than_going_blank(self):
        w = self.window()
        w.open_settings()
        settle()
        w.on_devices([])
        w.show_bt_state(None)
        w.show_wifi_state("", False)
        settle()
        for value in (w.devices_label, w.bt_value, w.wifi_value):
            self.assertTrue(value.text().strip(),
                            "a line with nothing on it should say nothing is connected")

    def test_the_labels_wear_the_wifi_buttons_look(self):
        """Harry: "keep the same box and text look of W-Fi button". The Wi-Fi button is a
        pill, so all four are, and they are checked against each other rather than against a
        remembered style name."""
        w = self.filled_in(self.window())
        for box in self.boxes(w):
            with self.subTest(box.text()):
                self.assertEqual("pill", box.objectName())
                self.assertEqual(w.wifi_button.font().pixelSize(), box.font().pixelSize())
                self.assertEqual(w.wifi_button.height(), box.height())

    def test_the_three_that_can_be_connected_keep_their_filled_circle(self):
        """Harry: "retain the filled circles to the left". Drawn, not styled, so the middle
        pixel is what is looked at."""
        from salaah.ui import MINT
        w = self.filled_in(self.window())
        for dot in (w.ring_dot, w.bt_dot, w.wifi_dot):
            self.assertTrue(dot.isVisible())
            middle = dot.grab().toImage().pixel(dot.width() // 2, dot.height() // 2)
            self.assertEqual(MINT, QtGui.QColor(middle).name().upper(),
                             "the circle is not filled in")
            self.assertLess(dot.mapTo(w, dot.rect().center()).x(),
                            w.ring_button.mapTo(w, QtCore.QPoint(0, 0)).x(),
                            "the circle is not to the left of the labels")

    def test_every_line_including_location_now_has_a_circle(self):
        """THIS TEST USED TO ASSERT THE OPPOSITE, and why it changed is worth keeping.

        It was `test_the_location_line_has_no_circle_because_it_has_no_answer`, and its
        reasoning was sound then: a location is not a thing that is either connected or not,
        so the circle would always be green and would be "saying nothing in the shape of an
        answer". 2.21 gave the row a yes-or-no fact worth a glance -- whether this mat's area
        is being shared -- and Harry asked for the circle on 12 November 2026. The reasoning
        did not stop being true; the row stopped being the row it described. On the three
        lines above, red means "not connected yet"; on this one red is the private default.

        Asked of the grid rather than measured in pixels. The first try compared the circle's
        top edge with the label's and allowed 20 pixels between them; a circle put on this line
        sat 22 below, being 28 tall in a 72-tall row, so the sabotage walked straight through a
        tolerance that had been guessed rather than measured. Which cell a widget is in is a
        thing the layout knows exactly.
        """
        w = self.filled_in(self.window())
        from salaah.ui import Dot
        rows = {"ring": 0, "bluetooth": 1, "wifi": 2, "location": 3}
        for name, at in rows.items():
            cell = w.attached.itemAtPosition(at, 0)
            self.assertIsNotNone(cell, f"the {name} line has lost its circle")
            self.assertIsInstance(cell.widget(), Dot)
        # And the label really is the thing on that row, so row 3 is the Location line.
        self.assertIs(w.place_button, w.attached.itemAtPosition(3, 1).widget())

    def test_every_label_opens_the_screen_that_sets_it(self):
        """All four look pressable, so all four are. The ring and Bluetooth share a screen --
        the ring IS a Bluetooth device, and that is where it would be reconnected."""
        w = self.window()
        for box, page in ((w.ring_button, "bt_page"), (w.bt_button, "bt_page"),
                          (w.wifi_button, "wifi_page"), (w.place_button, "place_page")):
            with self.subTest(box.text()):
                w.open_settings()
                settle()
                box.click()
                settle()
                self.assertIs(getattr(w, page), w.stack.currentWidget(),
                              f"{box.text()} did not open {page}")

    # -- what went, and the room it bought ------------------------------------------------------

    def test_the_school_picker_is_gone_wording_and_all(self):
        """Harry: "remove ... school and hanifi text option completely". One school ships, so
        it was a heading over a single filled circle: a question with one answer."""
        w = self.window()
        w.open_settings()
        settle()
        words = [x.text() for x in w.settings_screen.findChildren(QtWidgets.QLabel)
                 if x.isVisible()]
        words += [b.text() for b in w.settings_screen.findChildren(QtWidgets.QRadioButton)
                  if b.isVisible()]
        # Case-insensitively, and the bare keys too. Put the picker back with the wording
        # already taken out of the packs and it shows "settings.school" and "school.hanafi" --
        # which a check for "School" and "Hanafi" sailed past, so the first version of this
        # test let a restored picker through.
        showing = " ".join(words).lower()
        for mark in ("school", "hanafi"):
            self.assertNotIn(mark, showing, f"the school row is still on the page: {words}")
        for lang, pack in full_packs(available_packs(ASSETS)).items():
            self.assertNotIn("settings.school", pack.ui, f"{lang} still carries the wording")
            self.assertNotIn("school.hanafi", pack.ui, f"{lang} still carries the wording")
        # The setting itself stays: it is what picks the prayer times, and a mat whose
        # settings.json named another school would still be obeyed if its file existed.
        self.assertEqual("hanafi", w.school.id)
        self.assertFalse(hasattr(w, "set_school"), "the dead setter is still here")

    def test_settings_is_set_larger_than_it_was(self):
        """Harry: "increase font sizes to take advantage of extra room now". Measured against
        the sizes the page carried up to 1.82 rather than against the constants, which would
        be the measurement that produced the value."""
        w = self.window()
        w.open_settings()
        settle()
        was = {"settingHead": 30, "settingValue": 24}
        for name, before in was.items():
            found = {x.font().pixelSize() for x
                     in w.settings_screen.findChildren(QtWidgets.QLabel)
                     if x.objectName() == name and x.isVisible()}
            self.assertTrue(found, f"nothing on the page is a {name}")
            for size in found:
                self.assertGreater(size, w.px(before),
                                   f"{name} is {size}px; it was {w.px(before)}px")
        radios = {b.font().pixelSize() for b
                  in w.settings_screen.findChildren(QtWidgets.QRadioButton) if b.isVisible()}
        self.assertTrue(all(s > w.px(26) for s in radios), f"the choices are still {radios}")

    def test_the_larger_type_is_kept_to_this_page(self):
        """#pill is worn on the Wi-Fi, Bluetooth, radio and place screens too, and those have
        their own room to answer for, so the rise is scoped to Settings."""
        w = self.window()
        w.open_settings()
        settle()
        here = w.wifi_button.font().pixelSize()
        w.open_wifi()
        settle()
        elsewhere = {b.font().pixelSize() for b
                     in w.wifi_screen.findChildren(QtWidgets.QPushButton)
                     if b.objectName() == "pill"}
        self.assertTrue(elsewhere, "no pills on the Wi-Fi screen to compare with")
        self.assertTrue(all(s < here for s in elsewhere),
                        f"the Wi-Fi screen's pills grew too: {elsewhere} against {here}")

    def test_it_still_fits_a_common_monitor_in_every_language(self):
        """The measurement the type sizes were chosen against, and the one that will object if
        anybody raises them again. Chinese is the language that decides it -- CJK glyphs carry
        more line height than Latin at the same size, so English has room to spare at the size
        Chinese can just afford.

        1920x1080 rather than the mat's own 1920x1200, because that is the screen that has
        least to give, and with a monitor that refuses to dim -- which puts a three-line
        explanation under the brightness slider that a working monitor does not.
        """
        for lang in sorted(full_packs(available_packs(ASSETS))):
            with self.subTest(lang):
                w = self.window(lang=lang)
                w.resize(1920, 1080)
                w.stack.setCurrentWidget(w.settings_screen)
                settle()
                self.assertEqual(0, w.settings_scroll.verticalScrollBar().maximum(),
                                 "Settings scrolls on a 1920x1080 monitor")
                for box in self.boxes(w):
                    self.assertGreaterEqual(
                        box.height(), box.minimumSizeHint().height() - 1,
                        f"{lang}: {box.text()!r} is squeezed to {box.height()} of "
                        f"{box.minimumSizeHint().height()}")

    def test_the_two_columns_are_near_enough_the_same_length(self):
        """What bought most of the room. The left column ended two thirds of the way up while
        the right ran past the bottom of a 1920x1080 screen, so the page could not be set larger
        however much white space was showing. Mouse pointer moved across to even them up.

        The threshold is measured, not guessed. Balanced, the columns differ by 66 points in
        English and 85 in Chinese, against a body 880 tall -- ratios of 0.075 and 0.097. With
        Mouse pointer back on the right they differ by 175 and 205, ratios of 0.199 and 0.233.
        0.15 sits between the two with room either side; the first version of this test allowed
        0.35 and so passed in both arrangements, which is to say it measured nothing.
        """
        w = self.window()
        w.resize(1920, 1080)
        w.stack.setCurrentWidget(w.settings_screen)
        settle()
        body = w.settings_scroll.widget()
        middle = body.width() / 2
        lows = {"left": 0, "right": 0}
        for kind in (QtWidgets.QLabel, QtWidgets.QComboBox, QtWidgets.QRadioButton,
                     QtWidgets.QPushButton):
            for x in body.findChildren(kind):
                if not x.isVisible():
                    continue
                spot = x.mapTo(body, QtCore.QPoint(0, x.height()))
                side = "left" if x.mapTo(body, x.rect().center()).x() < middle else "right"
                lows[side] = max(lows[side], spot.y())
        self.assertTrue(lows["left"] and lows["right"], f"one column is empty: {lows}")
        self.assertLess(abs(lows["left"] - lows["right"]), body.height() * 0.15,
                        f"the columns are badly uneven: {lows}")


class CalledWordsTest(unittest.TestCase):
    """How large the call is written.

    It was coming out at eighteen pixels on a 1024x600 screen -- fine at arm's length, and the
    call is heard from wherever you happen to be standing. The size is not set anywhere: each
    line is drawn as large as its row is tall, so the words got bigger by the rows getting
    taller. Which is exactly why this is measured rather than read off a constant.
    """

    def box(self, wide, tall, prayer="fajr", recording="azaan-fajr.mp3"):
        from salaah.call import CallBox
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None)
        w.resize(wide, tall)
        w.show()
        settle()
        self.addCleanup(lambda: shut(w))
        b = CallBox(w, prayer, recording, w.adhan)
        b.show()
        settle()
        self.addCleanup(lambda: (b.close(), b.deleteLater(), settle()))
        return b

    def test_the_words_are_worth_reading_from_across_a_room(self):
        for wide, tall, floor in ((1024, 600, 24), (1280, 720, 28), (1920, 1080, 40)):
            with self.subTest(f"{wide}x{tall}"):
                b = self.box(wide, tall)
                sizes = [x.fitted_size() for x in b.boxes.values()]
                self.assertGreaterEqual(min(sizes), floor,
                                        f"the call is drawn at {min(sizes)}px on {wide}x{tall}")

    def test_fajr_has_the_most_lines_and_they_all_get_the_same_room(self):
        """Fajr carries "prayer is better than sleep" and so runs to seven lines against six.
        Nothing ever hangs out of the box -- Qt shrinks the rows instead, which is the failure
        worth looking for: one line squeezed while the rest are comfortable."""
        for wide, tall in ((1024, 600), (1280, 720), (1920, 1080)):
            with self.subTest(f"{wide}x{tall}"):
                b = self.box(wide, tall)
                self.assertEqual(7, len(b.boxes), "Fajr should have seven lines")
                heights = [x.height() for x in b.boxes.values()]
                self.assertGreater(min(heights) / max(heights), 0.9,
                                   f"the rows are uneven: {heights}")

    def test_each_meaning_sits_under_its_own_line(self):
        """The English is nearer the Arabic it translates than the Arabic below it. It used to
        sit midway between the two, which on seven lines reads as a list of fourteen things."""
        b = self.box(1920, 1080)
        keys = list(b.boxes)
        meanings = [x for x in b.findChildren(QtWidgets.QLabel)
                    if x.objectName() == "callMeaning"]
        self.assertEqual(len(keys), len(meanings))
        for i in range(len(keys) - 1):
            # The label's own margin is where the gap lives, so it is the text's box that is
            # measured from, not the widget's.
            text = meanings[i].contentsRect().translated(meanings[i].pos())
            above = text.top() - b.boxes[keys[i]].geometry().bottom()
            below = b.boxes[keys[i + 1]].y() - text.bottom()
            self.assertLess(above, below,
                            f"{keys[i]}: {above}px under its line, {below}px above the next")

    def test_it_fills_a_small_screen_too(self):
        """The second place that said the call must leave the mat showing round the edge, and
        it meant it: bigger words were not thought worth the box becoming the whole screen.
        Harry has decided the other way, so the only thing left to check here is that a small
        screen gets the same treatment as the mat's own -- the sizing is a fraction of the
        parent, and a fraction is the kind of thing that works at one size and not another."""
        b = self.box(1024, 600)
        self.assertEqual(1024, b.width())
        self.assertEqual(600 - b.parentWidget().banner_height(), b.height(),
                         "a small screen does not get the same treatment as the mat's own")


class WorldScreenTest(unittest.TestCase):
    """The world tile: the earth turning, with the mat's own place on it and a line to the
    Kaaba. The maths is tested in test_core; this is about what actually gets drawn."""

    def window(self, theme="dark", place="Bury", where=(53.593, -2.298), size=(1024, 600)):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=theme, place=place, latitude=where[0], longitude=where[1]),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(*size)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def with_a_remembered_map(self, mats, on=True):
        """A window whose cache already holds other mats, without any network."""
        import json
        import tempfile
        from pathlib import Path
        from salaah import onthemap
        room = Path(tempfile.mkdtemp())
        self.addCleanup(lambda: __import__("shutil").rmtree(room, ignore_errors=True))
        cache = room / "mats.json"
        cache.write_text(json.dumps({"mats": [list(m) for m in mats]}), encoding="utf-8")
        was = onthemap.CACHE
        onthemap.CACHE = cache
        self.addCleanup(lambda: setattr(onthemap, "CACHE", was))
        w = self.window()
        w.settings.on_the_map = on
        return w

    def test_the_globe_draws_the_mats_that_have_checked_in(self):
        """The community arriving, from the cache and never from a network."""
        w = self.with_a_remembered_map([(54, -2), (1, 103), (40, -74)])
        mats = w.world_screen.mats()
        self.assertEqual(3, len(mats), "the remembered mats did not reach the globe")
        self.assertTrue(mats[0].mine)
        self.assertFalse(any(m.mine for m in mats[1:]))
        self.assertEqual({(1.0, 103.0), (40.0, -74.0)},
                         {(m.latitude, m.longitude) for m in mats[1:]})

    def test_this_mat_is_drawn_once_and_not_twice(self):
        """This mat checked in, so the service's answer HOLDS this mat. Drawn as well as the
        dot made from its own settings, the same household would appear twice and the count
        beside the globe would be one too high."""
        w = self.with_a_remembered_map([(54, -2)])
        mats = w.world_screen.mats()
        self.assertEqual(1, len(mats), "this mat was drawn twice, once rounded")
        self.assertTrue(mats[0].mine)

    def test_a_neighbour_in_the_same_square_still_gets_a_dot(self):
        """Exactly ONE matching row is dropped, not all of them. Somebody seventy miles away
        shares this mat's whole degree and has as much right to a dot as anybody."""
        w = self.with_a_remembered_map([(54, -2), (54, -2), (54, -2)])
        mats = w.world_screen.mats()
        self.assertEqual(3, len(mats),
                         "neighbours in this mat's own square were thrown away with it")

    def test_the_globe_is_centred_and_the_column_is_still_wider(self):
        """REPLACES test_the_globe_is_against_the_left_edge_and_the_column_is_wider.

        2.23 did two things on one line of Harry's and only one of them was right. The column
        of names needed the extra width -- "some places will have longer names than Bury ;)"
        -- and it keeps it. Moving the globe off centre did not remove the black, it moved it
        from the globe's left to its right, where it sat between the world and the column and
        read as a gap instead of a margin. Harry, 12 November 2026: "spinning globe in world
        page, needs to recentred in screen, you were right".

        Measured on the PICTURE rather than on circle(), because circle() is the arithmetic
        under test: it is asked for the globe's box and would agree with itself whatever it
        returned. This renders the widget and finds the middle of what was actually painted.
        """
        w = self.with_a_remembered_map([(54, -2), (1, 103), (40, -74)])
        w.open_world()
        settle(4)
        screen = w.world_screen
        globe = screen.world
        shot = QtGui.QImage(globe.size(), QtGui.QImage.Format.Format_ARGB32)
        shot.fill(0)
        globe.render(shot)
        empty = shot.pixel(1, 1)
        drawn = [x for x in range(shot.width())
                 if any(shot.pixel(x, y) != empty for y in range(0, shot.height(), 3))]
        self.assertTrue(drawn, "nothing was painted at all")
        middle = (drawn[0] + drawn[-1]) / 2
        self.assertLess(abs(middle - globe.width() / 2), globe.width() * 0.02,
                        f"the world is painted from {drawn[0]} to {drawn[-1]}, centred on "
                        f"{middle}, in a widget {globe.width()} wide")
        # And the half of 2.23 that was right is untouched.
        # Measured against another number set in the same breath rather than against px(300)
        # read back later: setFixedWidth keeps the pixels it was given, and px() answers for
        # the window's size NOW, so the two disagree the moment a window is resized.
        indent = screen.who.contentsMargins().left()      # px(40) when the column was built
        self.assertEqual(round(indent * 300 / 40), screen.column.width(),
                         "the column is no longer half as wide again")
        self.assertGreater(globe.width(), screen.column.width(),
                           "the globe has been shrunk to pay for the column")

    def test_a_longer_place_name_fits_in_the_column(self):
        """What the extra width was for. "Bury" fits anything; the town list this mat carries
        since 2.20 has Kuala Lumpur and Nizhny Novgorod in it."""
        w = self.with_a_remembered_map([(3, 101)])
        w.settings.place = "Kuala Lumpur"
        w.open_world()
        settle(4)
        screen = w.world_screen
        named = [p for p, mat in screen.pips if mat.mine]
        self.assertTrue(named, "this mat is not named in the column")
        label = named[0].findChild(QtWidgets.QLabel) or named[0]
        room = screen.column.width() - screen.who.contentsMargins().left()
        self.assertLessEqual(label.sizeHint().width(), room,
                             f"'{w.settings.place}' needs {label.sizeHint().width()}px and "
                             f"the column gives it {room}px")

    def test_the_number_counts_mats_on_the_map_and_not_dots_on_the_globe(self):
        """Harry found this on the mat the day after 2.21 shipped.

        He turned the switch off, the row really was deleted from the service, and the screen
        still said 1. The 1 was HIS OWN MAT: the globe always draws a dot for where you are,
        and the number was counting dots. A mat that has opted out is not on the map, so the
        honest answer is 0 -- and the column underneath has to agree with it, or the screen
        says "0" directly above a row naming Bury.

        The dot itself stays either way. It is where you are, and the line to the Kaaba is
        drawn from it.
        """
        w = self.with_a_remembered_map([(54, -2), (1, 103), (40, -74)], on=False)
        w.open_world()
        settle(4)
        screen = w.world_screen
        self.assertEqual("0", screen.count.text(),
                         "a mat that opted out is still counted on the map")
        self.assertEqual(0, len(screen.pips),
                         "the column lists mats while the number above it says none")
        self.assertEqual(1, len(screen.mats()), "the globe lost the dot for where you are")

        w.settings.on_the_map = True
        screen.retell()
        settle(2)
        self.assertEqual("3", screen.count.text())
        self.assertEqual(3, len(screen.pips), "the column does not match the number")

    def test_a_sulking_network_cannot_freeze_the_switch(self):
        """THE PROMISE THIS RELEASE RESTS ON. A hotel wifi that accepts a connection and then
        never answers is the normal case, not the exotic one, and the switch is tapped by a
        child. If the request were made on the thread that draws, the whole mat would stop
        for the length of the timeout -- eight seconds -- with no way to tell it had.

        So the work goes on a thread nobody waits for. This measures the switch rather than
        reading the code: a service that takes three seconds to answer must not cost the
        switch more than a moment.
        """
        import time
        from salaah import onthemap
        w = self.window()

        slow = []

        def crawl(*a, **k):
            slow.append(time.monotonic())
            time.sleep(3.0)
            return None

        was_check, was_stop = onthemap.check_in, onthemap.stop
        onthemap.check_in, onthemap.stop = crawl, crawl
        self.addCleanup(lambda: (setattr(onthemap, "check_in", was_check),
                                 setattr(onthemap, "stop", was_stop)))
        for answer in (True, False):
            with self.subTest(answer):
                began = time.monotonic()
                w.set_on_the_map(answer)
                took = time.monotonic() - began
                self.assertLess(took, 0.5,
                                f"the switch sat on the network for {took:.1f}s")
        for _ in range(40):          # let the threads actually start before we judge them
            if len(slow) == 2:
                break
            time.sleep(0.05)
        self.assertEqual(2, len(slow), "the switch never reached the service at all")

    def test_a_mat_that_left_the_map_is_not_shown_the_community(self):
        """Opting out drops the cache, so this is the second lock rather than the only one --
        but a stale file on disk must not put the world back on a screen whose family said no.
        """
        w = self.with_a_remembered_map([(54, -2), (1, 103), (40, -74)], on=False)
        mats = w.world_screen.mats()
        self.assertEqual(1, len(mats), "a mat that opted out is still drawing other mats")
        self.assertTrue(mats[0].mine)

    def blue(self, widget):
        """Where the line and the marker are: the globe is black and white, so anything blue
        was drawn by us."""
        shot = widget.grab().toImage()
        found = []
        for y in range(0, shot.height(), 2):
            for x in range(0, shot.width(), 2):
                c = shot.pixelColor(x, y)
                if c.blue() > c.red() + 40 and c.blue() > 80:
                    found.append((x, y))
        return found

    def test_the_world_tile_opens_the_globe(self):
        w = self.window()
        w.open_corner("world")
        settle()
        self.assertIs(w.world_page, w.corner_screen.currentWidget(),
                      "the world tile still lands on the empty screen")
        self.assertIs(w.corner_page, w.stack.currentWidget())

    def test_there_are_no_words_under_the_globe(self):
        """There was a line saying "Bury to Makkah, about 5,030 km" and Harry asked for it to
        go. It was a fact rather than something to look at, sat across the bottom of a screen
        whose whole job is the picture above it."""
        w = self.window()
        w.open_corner("world")
        settle()
        said = " ".join(x.text() for x in w.world_page.findChildren(QtWidgets.QLabel)
                        if x.isVisible() and x.text())
        for gone in ("Makkah", "km", "5,030"):
            self.assertNotIn(gone, said, f"{gone!r} is still under the globe: {said!r}")

    def test_the_mat_still_knows_how_far_it_is(self):
        """The words went; the arithmetic did not, and the line on the globe is drawn from it.
        Measured here so that losing the caption cannot quietly lose the thing behind it."""
        from salaah.globe import KAABA, apart
        bury = apart((53.593, -2.298), KAABA)
        cape = apart((-33.9249, 18.4241), KAABA)
        self.assertEqual(5030, round(bury, -1))
        self.assertEqual(6560, round(cape, -1))

    def test_the_line_is_drawn_and_it_reaches_the_kaaba(self):
        """Blue on the screen, running from the mat's place to where Mecca is projected. The
        Kaaba end is the marker the animator drew, so the line landing on it is the whole
        calibration showing its work."""
        from salaah.globe import KAABA
        w = self.window()
        w.open_corner("world")
        settle()
        world = w.world_screen.world
        left, top, side = world.circle()
        drawn = world.film.currentPixmap().scaled(side, side, Qt.AspectRatioMode.KeepAspectRatio)
        at = world.film.currentFrameNumber()
        spots = self.blue(world)
        self.assertGreater(len(spots), 40, "nothing blue was drawn on the globe")
        mecca = w.world_screen.globe.at(at, *KAABA)
        target = (left + mecca.x * drawn.width(), top + mecca.y * drawn.width())
        near = min((abs(x - target[0]) + abs(y - target[1])) for x, y in spots)
        self.assertLess(near, side * 0.06,
                        f"the line stops {near:.0f}px short of the Kaaba on a {side}px globe")

    def test_the_marker_moves_when_the_mat_does(self):
        here = self.window(place="Bury", where=(53.593, -2.298))
        here.open_corner("world")
        settle()
        one = self.blue(here.world_screen.world)
        there = self.window(place="Cairo", where=(30.0444, 31.2357))
        there.open_corner("world")
        settle()
        two = self.blue(there.world_screen.world)
        self.assertTrue(one and two)
        # The topmost blue is the home end of the line in both cases, and Bury is a long way
        # north of Cairo.
        self.assertLess(min(y for _, y in one), min(y for _, y in two) - 20,
                        "the mat is drawn in the same place wherever it is")

    def test_the_film_is_stopped_when_the_screen_is_left(self):
        """Ten repaints a second for a screen nobody is looking at is the Pi woken for nothing,
        and on the call box it was worse than that -- it was a crash."""
        w = self.window()
        w.open_corner("world")
        settle()
        self.assertEqual(QtGui.QMovie.MovieState.Running, w.world_screen.world.film.state())
        w.go_home()
        settle()
        self.assertNotEqual(QtGui.QMovie.MovieState.Running, w.world_screen.world.film.state(),
                            "the globe is still turning off screen")

    def test_the_globe_leaves_nothing_behind_when_the_window_goes(self):
        """A window that has shown the globe must take all of it with it. The suite was killed
        for running out of memory once already, by a screen that was a top-level window without
        meaning to be, and this one holds a seventy-two frame film."""
        # Counted in two passes rather than measured against a baseline. A plain count would be
        # satisfied by whatever earlier tests have left lying about, and comparing the objects
        # themselves does not work either: PySide6 hands out a fresh Python wrapper for a widget
        # whose old one has been collected, so the same window looks like a new one. What a leak
        # does is grow, so growth is what this looks for -- the same work twice, and the second
        # time must add nothing the first did not.
        def pass_of(n):
            for _ in range(n):
                w = MainWindow(load(ASSETS), available_packs(ASSETS),
                               Settings(theme="dark", place="Bury"),
                               scale=1.0, save_settings=False, aspect=None, side=True)
                w.resize(1024, 600)
                w.show()
                w.side.resize(600, 1024)
                w.side.show()
                w.tick()
                w.open_corner("world")
                settle()
                shut(w)
            settle()
            return len(QtWidgets.QApplication.topLevelWidgets())

        first = pass_of(3)
        second = pass_of(3)
        self.assertLessEqual(second, first,
                             f"windows pile up as the globe is opened: {first} then {second}")

        # And the plain statement of what must be true, which the counting is only evidence for:
        # everything the world screen makes belongs to the page it was put on, so that closing
        # the window closes all of it.
        w = self.window()
        w.open_corner("world")
        settle()
        floating = []
        for name in dir(w.world_screen):
            if name.startswith("__"):
                continue
            thing = getattr(w.world_screen, name, None)
            if isinstance(thing, QtWidgets.QWidget) and thing.window() is not w:
                floating.append(f"{name} ({type(thing).__name__})")
        if isinstance(w.world_screen, QtWidgets.QWidget) and w.world_screen.window() is not w:
            floating.append(f"the screen itself ({type(w.world_screen).__name__})")
        self.assertEqual([], floating, f"not part of the window: {floating}")

    def test_it_is_drawn_the_right_way_round_for_the_screen_it_is_on(self):
        """The globe is drawn black on white like every other picture here, and turned inside
        out for the dark screen. A white disc on a black screen at Fajr would be no good."""
        inside = {}
        for theme in ("dark", "light"):
            w = self.window(theme=theme)
            w.open_corner("world")
            settle()
            world = w.world_screen.world
            shot = world.grab().toImage()
            left, top, side = world.circle()
            middle, spread = side / 2, side * 0.32
            inside[theme] = [shot.pixelColor(int(left + middle + dx),
                                             int(top + middle + dy)).red()
                             for dx in range(-int(spread), int(spread), 7)
                             for dy in range(-int(spread), int(spread), 7)]
        dark, light = inside["dark"], inside["light"]
        self.assertEqual(len(dark), len(light))
        # Point for point, one is the other turned inside out. Allowing a few to disagree: the
        # line drawn over the top is a different blue on the two screens.
        odd = sum(1 for a, b in zip(dark, light) if abs(a + b - 255) > 30)
        self.assertLess(odd, len(dark) * 0.08,
                        f"{odd} of {len(dark)} points are not inverses of each other")
        # And it is a picture of the world on both, not a grey wash on either.
        for theme, seen in inside.items():
            black = sum(1 for v in seen if v < 60) / len(seen)
            white = sum(1 for v in seen if v > 195) / len(seen)
            self.assertGreater(black, 0.2, f"{theme}: hardly anything is dark")
            self.assertGreater(white, 0.2, f"{theme}: hardly anything is light")


class CommunityColumnTest(unittest.TestCase):
    """The column beside the globe: how many mats are on, and which of them can be seen.

    The service that would tell a mat about any other does not exist yet, on purpose -- it is a
    decision about children's home locations before it is a piece of code. So the count is one.
    What is tested here is the shape it will arrive into, because a seam that has never had
    anything put through it is not a seam.
    """

    def window(self, theme="dark", place="Bury", where=(53.593, -2.298), size=(1024, 600)):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       # ON THE MAP, because every test in this class is about the community
                       # column, and since 2.22 that column belongs to a mat that is on the
                       # map: one that has opted out is shown nought and an empty list, which
                       # is its own test elsewhere. Before 2.21 there was no switch to be on
                       # the wrong side of, so saying nothing here said nothing.
                       Settings(theme=theme, place=place, on_the_map=True,
                                latitude=where[0], longitude=where[1]),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(*size)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    FOUR = ((53.593, -2.298, "Bury", True), (-33.8688, 151.2093, "Sydney", False),
            (30.0444, 31.2357, "Cairo", False), (31.5204, 74.3587, "Lahore", False))

    def pretend(self, w, rows=FOUR):
        """Put a community in the list the screen draws from, as the service would."""
        from salaah.worldscreen import Mat
        mats = [Mat(lat, lon, name, mine=mine) for lat, lon, name, mine in rows]
        w.world_screen.mats = lambda: mats
        return mats

    def opened(self, w):
        w.open_corner("world")
        settle()
        return w.world_screen

    def wind_to(self, screen, frame):
        """QMovie will only seek forward a frame at a time, so the film is walked there."""
        screen.world.film.stop()
        while screen.world.film.currentFrameNumber() % 72 != frame:
            screen.world.film.jumpToNextFrame()
        settle()
        screen.relight()
        screen.world.repaint()
        settle()

    def blue(self, widget):
        shot = widget.grab().toImage()
        found = []
        for y in range(0, shot.height(), 2):
            for x in range(0, shot.width(), 2):
                c = shot.pixelColor(x, y)
                if c.blue() > c.red() + 40 and c.blue() > 80:
                    found.append((x, y))
        return found

    # -- the header ---------------------------------------------------------------------------

    def test_there_is_no_heading_and_no_way_out_but_the_seven_inch_menu(self):
        """Harry: "remove the text 'MySalaah Community' and remove 'Back' button completely".

        The heading said what the picture says, and the button was a second way out of a
        screen the 7" panel can already leave -- the same reason the radio lost its in 1.75.
        Swept rather than named, because what matters is that nothing of that kind is left on
        the page, not that two particular attributes have gone.
        """
        w = self.window()
        self.opened(w)
        said = " ".join(x.text() for x in w.world_page.findChildren(QtWidgets.QLabel)
                        if x.isVisible())
        self.assertNotIn("MySalaah Community", said)
        buttons = [x.text() for x in w.world_page.findChildren(QtWidgets.QPushButton)
                   if x.isVisible()]
        self.assertEqual([], buttons, "there is still a button on the world screen")

    def test_the_way_out_is_the_seven_inch_menu(self):
        """Which is what lets the Back button go. Touching a tile on the small screen has to
        leave the world behind."""
        w = self.window()
        self.opened(w)
        w.chose_on_the_small_screen("wudu")
        settle()
        self.assertIsNot(w.world_page, w.corner_screen.currentWidget(),
                         "the 7in menu could not get off the world screen")

    # -- the count ---------------------------------------------------------------------------

    def test_one_mat_on_its_own_counts_one(self):
        w = self.window()
        screen = self.opened(w)
        # "Checked in" since 2.22, and the word was argued over rather than drifted into.
        # "Active" and Harry's first suggestion, "On-line", both claim the mats are connected
        # at this moment; what the number actually holds is mats that have reported in at
        # some point in the last sixty days, a switched-off one among them until the service
        # forgets it. The heading is pinned here on purpose: a count is only as honest as the
        # word above it.
        self.assertEqual("Checked in", screen.heading.text())
        self.assertEqual("1", screen.count.text())

    def test_the_count_follows_the_list(self):
        w = self.window()
        self.pretend(w)
        screen = self.opened(w)
        self.assertEqual("4", screen.count.text())

    def test_a_thousand_mats_are_written_as_a_thousand(self):
        """Not 1000. The number is the thing a child reads off the screen."""
        w = self.window()
        self.pretend(w, tuple((10 + i % 60, (i * 7) % 300 - 150, "", i == 0)
                              for i in range(1000)))
        screen = self.opened(w)
        self.assertEqual("1,000", screen.count.text())

    # -- what is drawn ------------------------------------------------------------------------

    def test_a_line_is_drawn_for_every_mat_that_can_be_seen(self):
        """Four mats at a frame where all four are on the near side: four routes to the Kaaba,
        four markers. Counted as separate runs of blue rather than by area, so that a single
        fatter line cannot pass for four."""
        from salaah.globe import KAABA
        w = self.window()
        mats = self.pretend(w)
        screen = self.opened(w)
        self.wind_to(screen, 19)
        seen = [m for m in mats if screen.globe.at(19, m.latitude, m.longitude).seen]
        self.assertEqual(4, len(seen), "the frame chosen does not show all four")
        spots = self.blue(screen.world)
        left, top, side = screen.world.circle()
        # Each mat's marker is its own island of blue. Finding blue within a marker's width of
        # every one of the four is the claim that all four were drawn.
        for mat in seen:
            here = screen.globe.at(19, mat.latitude, mat.longitude)
            target = (left + here.x * side, top + here.y * side)
            near = min(abs(x - target[0]) + abs(y - target[1]) for x, y in spots)
            self.assertLess(near, side * 0.05,
                            f"nothing drawn at {mat.name or 'a remote mat'}")
        # And the Kaaba end, which every line has to reach.
        mecca = screen.globe.at(19, *KAABA)
        target = (left + mecca.x * side, top + mecca.y * side)
        near = min(abs(x - target[0]) + abs(y - target[1]) for x, y in spots)
        self.assertLess(near, side * 0.06, "no line reaches the Kaaba")

    def test_more_mats_means_more_blue_on_the_globe(self):
        """The plain version of the same thing, measured a different way: four lines put more
        blue on the picture than one does."""
        one = self.window()
        alone = self.opened(one)
        self.wind_to(alone, 19)
        few = len(self.blue(alone.world))
        many_window = self.window()
        self.pretend(many_window)
        crowd = self.opened(many_window)
        self.wind_to(crowd, 19)
        lots = len(self.blue(crowd.world))
        self.assertGreater(lots, few * 1.8, f"one mat drew {few}, four drew {lots}")

    # -- the dots ----------------------------------------------------------------------------

    def test_a_mat_round_the_back_has_its_dot_dimmed(self):
        """Bury and Sydney are 153 degrees apart, so they share the visible face for six frames
        in seventy-two. A count of four beside one line would read as a fault; the dots are what
        makes the number and the picture agree."""
        w = self.window()
        self.pretend(w)
        screen = self.opened(w)
        self.wind_to(screen, 39)      # the Pacific facing us: Sydney only
        lit = {mat.name or "remote": pip.lit for pip, mat in screen.pips}
        self.assertEqual({"Bury": False, "Sydney": True, "Cairo": False, "Lahore": False}, lit)

    def test_the_dots_come_back_as_the_earth_turns(self):
        w = self.window()
        self.pretend(w)
        screen = self.opened(w)
        self.wind_to(screen, 39)
        self.assertFalse(dict((m.name, p) for p, m in screen.pips)["Bury"].lit)
        self.wind_to(screen, 66)
        self.assertTrue(dict((m.name, p) for p, m in screen.pips)["Bury"].lit,
                        "Bury never came back round")

    # -- what is not shown --------------------------------------------------------------------

    def test_only_this_mat_is_named(self):
        """A town beside a dot is a household. This screen is looked at by children, and the
        only one it is allowed to name is the one it is standing on."""
        w = self.window()
        self.pretend(w)
        screen = self.opened(w)
        said = [x.text() for x in screen.column.findChildren(QtWidgets.QLabel)
                if x.objectName() == "worldWho"]
        self.assertIn("Bury", said, "the mat's own place should be named")
        for elsewhere in ("Sydney", "Cairo", "Lahore"):
            self.assertNotIn(elsewhere, said, f"{elsewhere} is named on screen")
        whole = " ".join(x.text() for x in w.world_page.findChildren(QtWidgets.QLabel))
        for elsewhere in ("Sydney", "Cairo", "Lahore"):
            self.assertNotIn(elsewhere, whole, f"{elsewhere} appears somewhere on the page")

    def test_the_list_stops_before_it_runs_out_of_page(self):
        """Thirty-one mats must not run off the bottom of the page. It used to be the Back
        button they would have pushed off; that went in 1.76, and the column is still the
        thing that has to know when to stop."""
        w = self.window()
        self.pretend(w, tuple((10 + i, 20 + i * 3, "", i == 0) for i in range(31)))
        screen = self.opened(w)
        self.assertEqual("31", screen.count.text(), "the count should still be the truth")
        self.assertLessEqual(len(screen.pips), screen.ROWS)
        self.assertLessEqual(screen.column.height(), w.world_page.height(),
                             "the column is taller than the page it is on")

    # -- the room it takes --------------------------------------------------------------------

    def test_the_column_costs_the_globe_nothing(self):
        """The globe is square and every screen the mat has is wider than it is tall, so its
        size is settled by the height left over and never by the width. The column goes in room
        that was already empty beside it.

        This was written against the three sizes the globe came out at, and a version later that
        caught something real and named it wrongly: the globe had shrunk, but by the Back button
        doubling in height underneath it, not by the column. So what it asks now is the thing it
        always meant -- that the globe is still hemmed in by the height and not by the width. If
        the column ever starts squeezing it, the globe turns width-limited and this fails.
        """
        for size in ((1024, 600), (1280, 720), (1920, 1080)):
            with self.subTest(f"{size[0]}x{size[1]}"):
                w = self.window(size=size)
                screen = self.opened(w)
                world = screen.world
                side = world.circle()[2]
                self.assertEqual(world.height(), side,
                                 "the globe is no longer as tall as the room it has -- the "
                                 "column is squeezing it")
                self.assertGreater(world.width(), side,
                                   "there is no width to spare beside the globe any more")
                # And a floor, so it cannot quietly dwindle: still over half the page.
                self.assertGreater(side, w.world_page.height() * 0.6,
                                   f"the globe is down to {side}px on a "
                                   f"{w.world_page.height()}px page")


class ThumbButtonsTest(unittest.TestCase):
    """The buttons that are pressed hardest, given room to be pressed.

    Back on the world and hadith screens came out 29 pixels tall on the 7" panel, and the
    update button 23. That is a fingernail, on a screen somebody prods with a thumb while
    standing over a mat on the floor. These are twice that and no narrower than they are tall.

    Measured against a plain Back button in the same window rather than against a pixel count,
    because the point is the ratio: the sizes follow the screen, so a number written here would
    only be true on one of them.
    """

    def window(self, size=(1024, 600), lang="en"):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury", lang=lang),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(*size)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def plain_back(self, w):
        """An ordinary Back button in this same window, for the comparison."""
        w.open_place()
        settle()
        return w.place_screen.leave

    SIZES = ((1024, 600), (1280, 720), (1920, 1080))

    def test_the_hadith_back_button_is_the_same(self):
        for size in self.SIZES:
            with self.subTest(f"{size[0]}x{size[1]}"):
                w = self.window(size)
                plain = self.plain_back(w).height()
                w.open_corner("hadith")
                settle()
                big = w.soon_back_button
                self.assertGreater(big.height(), plain * 1.8,
                                   f"{big.height()}px against a plain {plain}px")
                self.assertGreaterEqual(big.width(), big.height())

    def test_the_update_button_says_update_and_is_twice_as_tall(self):
        for size in self.SIZES:
            with self.subTest(f"{size[0]}x{size[1]}"):
                w = self.window(size)
                plain = self.plain_back(w).height()
                w.open_settings()
                settle()
                button = w.update_button
                self.assertEqual("UPDATE", button.text())
                self.assertGreater(button.height(), plain * 1.5,
                                   f"{button.height()}px against a plain back button's {plain}px")

    def test_the_update_button_is_a_block_in_every_language(self):
        """The height is only half of it: "Check for updates" was three times wider than it was
        tall, which is a strip rather than something to aim a thumb at. Measured as the ratio in
        all six languages at all three sizes -- Spanish is the widest at 2.21 and Chinese the
        narrowest at 0.98, against 3.0 for the words it used to carry."""
        for lang in sorted(full_packs(available_packs(ASSETS))):
            for size in self.SIZES:
                with self.subTest(f"{lang} {size[0]}x{size[1]}"):
                    w = self.window(size, lang=lang)
                    w.open_settings()
                    settle()
                    button = w.update_button
                    self.assertTrue(button.text(), f"{lang} has no word for it")
                    shape = button.width() / button.height()
                    self.assertLess(shape, 2.6,
                                    f"{lang}: {button.text()!r} makes it {shape:.2f} times "
                                    f"wider than it is tall")
                    # Never narrower than it is tall. Chinese is the word that tests it: 更新
                    # comes out 47px wide against 48 tall on its own, and the floor in the
                    # stylesheet takes it to 62 -- a third more to aim at.
                    self.assertGreaterEqual(shape, 1.0,
                                            f"{lang}: {button.text()!r} makes it "
                                            f"{button.width()}x{button.height()}, narrower "
                                            f"than it is tall")

    def test_the_ordinary_back_buttons_are_left_as_they_were(self):
        """The bigger size is its own object name rather than a change to every Back button in
        the app. The reader's bar and the keyboard screens are laid out around the small one."""
        w = self.window()
        plain = self.plain_back(w)
        self.assertEqual("backButton", plain.objectName())
        w.open_wifi()
        settle()
        self.assertEqual("backButton", w.wifi_screen.leave.objectName())
        w.open_corner("hadith")
        settle()
        self.assertEqual("bigBack", w.soon_back_button.objectName())
        # And the plain one is still the small size beside the big one.
        self.assertLess(plain.height(), w.soon_back_button.height() * 0.7)


class TheFrontDoorIsOneFilmTest(unittest.TestCase):
    """The screen the mat opens on.

    It was a mosque with MySalaah across its front, a moving sky behind it, a clock on its
    dome and the black strip of prayer times above. Harry replaced the lot with his own
    drawing: "remove the main default page with this one, dont add banner or anything, keep as
    is" -- and then, the same evening, "i gave you an image, i wanted an animation". So the
    tests of it are that there is nothing else on it, that it moves, and that it goes in.
    """

    def window(self, size=(1920, 1080), aspect=16 / 9, theme="light", **settings):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme=theme, recitation=False, place="Bury", **settings),
                       scale=1.0, save_settings=False, aspect=aspect)
        w.resize(*size)
        w.show()
        w.veil.stop()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def test_the_mat_opens_on_it(self):
        w = self.window()
        self.assertIsNotNone(w.welcome, "there is no front door at all")
        self.assertIs(w.welcome, w.stack.currentWidget())

    # It moves

    def at(self, w, frame: int):
        """The screen with the film wound to [frame]. QMovie will only step forward.

        Stopped first, and left stopped. A running film advances on its own timer, and settle()
        is an invitation for that timer to fire -- so the frame grabbed would not always be the
        frame asked for. No test here looks at the film's state after calling this; the two
        that care about whether it is running never do.
        """
        film = w.welcome.film
        film.stop()
        for _ in range(film.frameCount() + 1):
            if film.currentFrameNumber() == frame:
                break
            film.jumpToNextFrame()
        else:
            self.fail(f"the film would not wind to frame {frame}")
        settle()
        return w.welcome.grab().toImage()

    def test_it_is_a_film_and_not_a_still(self):
        """Harry: "i gave you an image, i wanted an animation"."""
        w = self.window()
        self.assertTrue(w.welcome.moving, "the front door is a still picture")
        self.assertGreater(w.welcome.film.frameCount(), 1)

    def test_the_screen_really_changes_as_it_runs(self):
        """Off the screen rather than off the frame number: a film can be running, counting
        its frames, and painting the same thing every time."""
        w = self.window()
        self.assertNotEqual(self.pixels(self.at(w, 0)), self.pixels(self.at(w, 12)),
                            "the screen is the same picture at both ends of it")

    @staticmethod
    def pixels(image) -> bytes:
        """A picture as something two of them can be compared by. Encoded rather than read
        out of the image's own buffer, which is the one place the two Qt kits differ in the
        hand -- PySide gives a memoryview and PyQt6 a sip.voidptr."""
        hold = QtCore.QBuffer()
        hold.open(QtCore.QIODevice.OpenModeFlag.WriteOnly)
        image.save(hold, "PNG")
        return bytes(hold.data())

    @staticmethod
    def timing() -> list[int]:
        """How long each frame of the shipped film is held for, in milliseconds."""
        from PIL import Image, ImageSequence
        with Image.open(ASSETS / "welcome" / "front.gif") as film:
            return [f.info.get("duration", 100) for f in ImageSequence.Iterator(film)]

    def test_a_new_frame_asks_the_screen_to_redraw(self):
        """The one thing a grab cannot see.

        Grabbing a widget paints it whether or not anything asked it to, so every other test
        here would pass on a front door that advances its film and never repaints -- which on
        the mat is a frozen picture over a running film. So nothing is grabbed: the paints are
        counted as they arrive, and the film is stepped on with nobody watching.
        """
        w = self.window()
        seen = []

        class Counter(QtCore.QObject):
            def eventFilter(self, _obj, event):
                if event.type() == QtCore.QEvent.Type.Paint:
                    seen.append(1)
                return False

        count = Counter()
        w.welcome.installEventFilter(count)
        self.addCleanup(lambda: w.welcome.removeEventFilter(count))
        settle()
        seen.clear()
        self.assertEqual(0, len(seen), "the front door is repainting with nothing happening")
        w.welcome.film.jumpToNextFrame()
        settle()
        self.assertTrue(seen, "a new frame arrived and the screen was not asked to redraw")

    def test_it_rests_on_seven_different_pictures(self):
        """The word turns over through the seven languages the mat speaks, resting a beat on
        each. Counted rather than read: the long-held frames are found by their own timing and
        then compared with each other, so this says there are seven distinct things to see
        without claiming to know which languages they are.
        """
        w = self.window()
        held = self.timing()
        rests = [n for n, ms in enumerate(held) if ms == max(held)]
        self.assertEqual(7, len(rests),
                         f"the film rests {len(rests)} times, not seven: {held}")
        self.assertEqual(7, len({self.pixels(self.at(w, n)) for n in rests}),
                         "two of the seven it rests on are the same picture")

    def test_the_pauses_are_kept_rather_than_flattened(self):
        """The thing a careless re-encode loses. It holds each language for most of a second
        and crosses to the next over three quick frames; written out with one duration for all
        twenty-eight it becomes a flicker with no pauses in it."""
        held = self.timing()
        self.assertGreater(len(set(held)), 1, "every frame is held for the same time")
        self.assertGreater(max(held), min(held) * 3,
                           f"there is no pause worth the name in {sorted(set(held))}")

    def test_it_stops_when_it_is_not_on_the_screen(self):
        """A film left running is a timer waking the Pi ten times a second to repaint
        something nobody is looking at -- and this is the screen the mat sleeps on."""
        w = self.window()
        running = QtGui.QMovie.MovieState.Running
        self.assertEqual(running, w.welcome.film.state(), "not playing on the screen it is on")
        w.leave_welcome()
        w.veil.stop()
        settle()
        self.assertNotEqual(running, w.welcome.film.state(),
                            "still playing with the mosque up in front of it")
        w.go_home()
        settle()
        self.assertEqual(running, w.welcome.film.state(), "it did not start again")

    def test_after_dark_it_is_the_same_film_turned_over(self):
        """Harry sent it twice, black on white and white on black, and the two are the same
        pixels inverted -- so one ships and the mat turns it over, the way it does with every
        other drawing it has. Checked on the screen: the night picture has to be the day
        picture's negative, not merely darker.
        """
        day = self.at(self.window(theme="light"), 0)
        night = self.at(self.window(theme="dark"), 0)
        self.assertEqual(day.size(), night.size())
        step = max(1, day.width() // 120)
        out = [abs(255 - QtGui.QColor(day.pixel(x, y)).lightness()
                   - QtGui.QColor(night.pixel(x, y)).lightness())
               for y in range(0, day.height(), step)
               for x in range(0, day.width(), step)]
        self.assertLess(max(out), 12,
                        f"the night screen is not the day screen inverted; worst pixel is "
                        f"{max(out)} of 255 out")

    def test_the_still_it_falls_back_to_is_one_it_rests_on(self):
        """Not a half-crossfade. A mat whose film is missing shows this instead, and two words
        fading through each other is not a thing to leave on a screen."""
        w = self.window()
        held = self.timing()
        rests = [n for n, ms in enumerate(held) if ms == max(held)]
        still = QtGui.QImage(str(ASSETS / "welcome" / "front.png"))
        self.assertFalse(still.isNull(), "there is no still to fall back to")
        # Sampled rather than compared byte for byte: the still comes off the disk and the
        # frame out of a QMovie, and two images of the same picture from two sources agree
        # about every pixel and about nothing else -- format, palette, metadata.
        off = []
        for n in rests:
            self.at(w, n)
            off.append(self.how_far(still, w.welcome.film.currentPixmap().toImage()))
        self.assertLess(min(off), 4,
                        f"the still is not one of the pictures the film rests on; the "
                        f"nearest is {min(off)} of 255 out")

    @staticmethod
    def how_far(a, b) -> int:
        """The worst a sampled pixel differs between two pictures of the same size."""
        if a.size() != b.size():
            return 255
        step = max(1, a.width() // 150)
        return max(abs(QtGui.QColor(a.pixel(x, y)).lightness()
                       - QtGui.QColor(b.pixel(x, y)).lightness())
                   for y in range(0, a.height(), step)
                   for x in range(0, a.width(), step))

    def test_there_is_nothing_on_it_but_the_picture(self):
        """No banner, which is the one Harry named, and nothing else either: the strip carries
        the place, the five prayer times, a volume slider and a gear, and all four of them went
        with it."""
        w = self.window()
        self.assertEqual([], w.welcome.findChildren(QtWidgets.QWidget),
                         "something has been put on the front door")
        shot = w.welcome.grab().toImage()
        # The corners are the field the mark was drawn on, and nothing is allowed to sit in
        # them: a banner would have put a black strip across the top of a white screen or the
        # other way about, and either shows up here.
        corners = [shot.pixelColor(2, 2), shot.pixelColor(w.welcome.width() - 3, 2),
                   shot.pixelColor(2, w.welcome.height() - 3),
                   shot.pixelColor(w.welcome.width() - 3, w.welcome.height() - 3)]
        self.assertEqual(1, len({c.name() for c in corners}),
                         f"the four corners are {[c.name() for c in corners]}")

    def test_it_is_the_drawing_that_ships_rather_than_anything_drawn_here(self):
        """Against the frame the film is actually showing, not against a file chosen by name:
        the two could agree about the still and disagree about everything else."""
        w = self.window()
        self.assertTrue((ASSETS / "welcome" / "front.gif").is_file(),
                        "the front door's film does not ship")
        want = w.welcome.now().toImage()
        self.assertFalse(want.isNull(), "the front door has no frame to draw")
        shot = w.welcome.grab().toImage().scaled(
            want.width(), want.height(), Qt.AspectRatioMode.IgnoreAspectRatio,
            Qt.TransformationMode.SmoothTransformation)
        step = max(1, want.width() // 120)
        same = agree = 0
        for y in range(0, want.height(), step):
            for x in range(0, want.width(), step):
                agree += 1
                a, b = QtGui.QColor(want.pixel(x, y)), QtGui.QColor(shot.pixel(x, y))
                same += abs(a.lightness() - b.lightness()) < 60
        self.assertGreater(same / agree, 0.97,
                           f"what is on the screen matches the file in {same / agree:.0%} "
                           f"of it, so it is not that picture")

    @staticmethod
    def mark_in(image) -> tuple[int, int]:
        """How wide and how tall the drawn mark is, measured off whatever it is drawn on."""
        field = QtGui.QColor(image.pixel(0, 0)).lightness()
        step = max(1, image.width() // 200)
        on = [(x, y) for y in range(0, image.height(), step)
              for x in range(0, image.width(), step)
              if abs(QtGui.QColor(image.pixel(x, y)).lightness() - field) > 60]
        xs, ys = [p[0] for p in on], [p[1] for p in on]
        return max(xs) - min(xs), max(ys) - min(ys)

    def test_the_picture_is_not_stretched_to_fit_a_screen_it_does_not_match(self):
        """The mat is 16:9 and so is the picture, so on the mat this cannot be seen at all --
        and it cannot be seen at the edges of the screen either, because the mark is drawn on
        a field and a bar of that field down the side of it looks like more field. The only
        place it shows is in the mark's own proportions, so that is what is measured, on two
        panels that are not 16:9.

        Measured: the mark in the file is 528x624, a ratio of 0.846, and the drawn mark comes
        within 0.009 of it at every size tried. Stretching it to fill a 1024x600 panel instead
        would put it out by 0.035, and a 800x480 one by 0.057, so the bar is 0.02.
        """
        want = self.mark_in(QtGui.QImage(str(ASSETS / "welcome" / "front.png")))
        for size in ((1024, 600), (800, 480)):
            with self.subTest(f"{size[0]}x{size[1]}"):
                # aspect=None, or the app letterboxes the whole window to 16:9 before the
                # front door is asked to draw anything and there is nothing left to get wrong.
                w = self.window(size, aspect=None)
                drawn = self.mark_in(w.welcome.grab().toImage())
                self.assertAlmostEqual(drawn[0] / drawn[1], want[0] / want[1], delta=0.02,
                                       msg=f"the mark is drawn {drawn[0]}x{drawn[1]} from a "
                                           f"picture whose mark is {want[0]}x{want[1]}")

    def test_touching_it_anywhere_goes_in(self):
        """It is one picture rather than a mosque with an opening to find, so there is no
        wrong place to press."""
        for where in ((40, 40), (960, 540), (1880, 1040)):
            with self.subTest(where):
                w = self.window()
                QtTest_click(w.welcome, *where)
                settle()
                self.assertIs(w.home, w.stack.currentWidget(),
                              "touching the front door did not go in")

    def test_no_picture_means_no_front_door_rather_than_a_black_screen(self):
        """The picture arrives in a release, so a mat part way through an update has a front
        door with nothing behind it. Two halves: it declines to build one, and the mat then
        opens on the mosque with the five arches."""
        w = self.window()
        with tempfile.TemporaryDirectory() as empty:
            w.assets = Path(empty)
            self.assertIsNone(w.build_welcome(),
                              "a front door was built with no picture behind it")
        from salaah.ui import MainWindow as MW
        with mock.patch.object(MW, "build_welcome", lambda self: None):
            bare = self.window()
            self.assertIsNone(bare.welcome)
            self.assertIs(bare.home, bare.stack.currentWidget())


def QtTest_click(widget, x, y) -> None:
    """A press at a point in [widget]. Spelled out rather than QTest, which the two bindings
    expose under different module names."""
    here = QtCore.QPointF(x, y)
    event = QtGui.QMouseEvent(QtCore.QEvent.Type.MouseButtonPress, here,
                              QtCore.QPointF(widget.mapToGlobal(QtCore.QPoint(x, y))),
                              Qt.MouseButton.LeftButton, Qt.MouseButton.LeftButton,
                              Qt.KeyboardModifier.NoModifier)
    QtWidgets.QApplication.sendEvent(widget, event)


class TheGlobeTakesTheWholePageTest(unittest.TestCase):
    """What was a heading, a globe and a Back button is now a globe.

    The name plate went through two rounds before it went altogether: centred over the whole
    page, then moved left over the globe at Harry's asking, then taken off with the Back
    button in 1.76 -- "remove the text 'MySalaah Community' and remove 'Back' button
    completely and make spinning globe 25% bigger". The two rows between them were most of
    what the globe has gained.
    """

    # Measured on the 1.75 layout, at 1920x1080 with the 7" panel attached: the drawn globe
    # was 769px across. A quarter bigger than that is 961, which is the bar below.
    WAS = 769
    MORE = 1.25

    def window(self, size=(1920, 1080)):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(*size)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        w.open_corner("world")
        settle()
        settle()
        return w

    def test_the_globe_is_a_quarter_bigger_than_it_was(self):
        w = self.window()
        side = w.world_screen.world.circle()[2]
        self.assertGreaterEqual(side, int(self.WAS * self.MORE),
                                f"the globe is {side}px across; it was {self.WAS}px with the "
                                f"heading and the button on the page, and a quarter bigger "
                                f"than that is {int(self.WAS * self.MORE)}px")

    def test_it_is_as_big_as_the_page_will_let_it_be(self):
        """Which is the reason it got bigger: the globe's size is whatever height is left over
        after everything else on the page, and there is nothing else on the page now.

        A number out of the layout would only be the arithmetic read back, so the globe is
        measured against the PAGE it is drawn on -- the thing the rows were taken off.
        """
        for size in ((1024, 600), (1920, 1080)):
            with self.subTest(f"{size[0]}x{size[1]}"):
                w = self.window(size)
                side = w.world_screen.world.circle()[2]
                self.assertGreater(side, w.world_page.height() * 0.9,
                                   f"{side}px of a {w.world_page.height()}px page")

    def test_the_tally_column_keeps_its_room(self):
        """The globe is bigger because it took the room two rows above and below it were
        using, not because it took the column's.

        What is measured is where the two SIT, not what is painted: Qt clips a widget's
        painting to its own box, so a globe told to draw itself wider than its widget is
        quietly cut off at the edge rather than appearing over the column. The thing that
        could really go wrong is the layout -- the column squeezed to nothing, or hidden
        altogether with the heading it stood next to.
        """
        w = self.window()
        globe = w.world_screen.world
        column = w.world_screen.column
        self.assertTrue(column.isVisible(), "the column went with the heading")
        self.assertGreater(column.width(), w.px(100), "the column has been squeezed thin")
        globe_right = globe.mapTo(w.world_page, QtCore.QPoint(globe.width(), 0)).x()
        column_left = column.mapTo(w.world_page, QtCore.QPoint(0, 0)).x()
        self.assertLessEqual(globe_right, column_left,
                             "the globe's box now runs under the Active column")
        self.assertLessEqual(column.mapTo(w.world_page, QtCore.QPoint(column.width(), 0)).x(),
                             w.world_page.width(), "the column runs off the page")


class DuaPlayTest(unittest.TestCase):
    """The play mark on a du'a card. It opened the du'a and stopped there for as long as there
    were no recordings; there are recordings now, so it should read it aloud."""

    def window(self, size=(1024, 600)):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(*size)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def board(self, w, kind="morning"):
        w.open_the_kinds_of_dua()
        settle()
        w.open_dua_category(kind)
        settle()
        return w.dua_board

    def test_the_mark_is_twice_the_size_it_was(self):
        """46 pixels on a 440 pixel card is a stamp to aim a thumb at, and it is now the only
        way to hear a du'a read."""
        from salaah.duaboard import DuaCard
        for size in ((1024, 600), (1920, 1080)):
            with self.subTest(f"{size[0]}x{size[1]}"):
                w = self.window(size)
                card = self.board(w).cards[0]
                self.assertEqual(w.px(DuaCard.MARK) + w.px(10), card.button.width())
                self.assertGreaterEqual(card.button.height(), w.px(92),
                                        "the mark has gone back to its old size")
                self.assertEqual(card.button.width(), card.button.height(), "it is square")
                self.assertLess(card.button.width(), card.width() * 0.25,
                                "the mark has taken over the card")

    def test_every_du_a_can_be_read_aloud_now(self):
        w = self.window()
        reader = w.section_readers["duas"]
        cannot = []
        for i in range(len(w.duas.items)):
            reader.open(i)
            settle()
            if not reader.can_say():
                cannot.append(w.duas.items[i].key)
        self.assertEqual([], cannot, f"no recording or no timings for: {cannot}")

    def test_the_mark_reads_the_du_a_where_it_stands(self):
        """It used to open the du'a's own page and read it there, which meant the two-column
        screen vanished the moment you pressed play -- and with it the du'a beside the one you
        wanted. It reads it here now, and here is where it stays."""
        w = self.window()
        board = self.board(w)
        board.cards[0].button.click()
        settle()
        self.assertIs(board, w.corner_screen.currentWidget(), "it left the two-column screen")
        self.assertTrue(board.saying, "nothing is being read")
        self.assertIs(board.cards[0], board.said_by)
        board.stop_saying()
        settle()

    def test_pressing_it_again_stops_and_the_other_card_takes_over(self):
        w = self.window()
        board = self.board(w)
        board.cards[0].button.click()
        settle()
        board.cards[1].button.click()
        settle()
        self.assertIs(board.cards[1], board.said_by, "the voice did not move across")
        board.cards[1].button.click()
        settle()
        self.assertFalse(board.saying, "pressing it again should stop it")

    def test_a_du_a_with_no_recording_opens_instead(self):
        """A mat part way through an update, or a set of du'as that grew past its recordings.
        The mark must not become a dead button."""
        w = self.window()
        board = self.board(w)
        opened = []
        board.chose.connect(opened.append)
        with mock.patch.object(type(board), "can_say", lambda self, card: False):
            board.cards[0].button.click()
            settle()
            self.assertFalse(board.saying)
            self.assertEqual([board.cards[0].index], opened,
                             "with no recording it should open the du'a instead")

    def test_leaving_the_screen_stops_the_voice(self):
        """A recording left playing to an empty room."""
        w = self.window()
        board = self.board(w)
        board.cards[0].button.click()
        settle()
        self.assertTrue(board.saying)
        w.go_home()
        settle()
        self.assertFalse(board.saying, "it is still reading to nobody")

    def test_it_does_not_fall_asleep_over_a_du_a_on_the_board(self):
        w = self.window()
        board = self.board(w)
        board.cards[0].button.click()
        settle()
        w.maybe_sleep()
        settle()
        self.assertFalse(w.asleep, "it went to sleep while reading a du'a aloud")
        board.stop_saying()
        settle()

    def test_the_word_being_said_goes_red_on_the_card(self):
        """The whole point of reading it here rather than on its own page."""
        w = self.window()
        board = self.board(w)
        board.cards[0].button.click()
        settle()
        card = board.said_by
        self.assertTrue(card.arabic.by_word, "the card cannot light a single word")
        for k in (0, 1):
            start, end = card.item.times[k]
            with mock.patch.object(type(w.recitation), "position",
                                   lambda self, k=k: (card.item.times[k][0]
                                                      + card.item.times[k][1]) / 2000.0):
                board.tick()
                settle()
                self.assertEqual((0, k), card.arabic.highlight,
                                 f"word {k + 1} was not the one lit")
        board.stop_saying()
        settle()
        self.assertIsNone(card.arabic.highlight, "a word is still red after it stopped")

    def test_the_word_being_said_is_the_one_in_red(self):
        """Walked against the timings rather than against the clock: at a moment inside word
        five's span, word five is the one lit."""
        w = self.window()
        reader = w.section_readers["duas"]
        reader.open(1)                       # the 37-word one, which has the most to get wrong
        settle()
        item = w.duas.items[1]
        for k in (0, 5, 17, 36):
            start, end = item.times[k]
            middle = (start + end) / 2000.0
            reader.arabic.set_highlight((0, item.word_at(middle)))
            settle()
            self.assertEqual(k, item.word_at(middle),
                             f"half way through word {k + 1} the app thinks it is somewhere else")
            self.assertEqual((0, k), reader.arabic.highlight)


class PlainerDuasTest(unittest.TestCase):
    """No transliteration on the du'as. Ten of the forty-eight had one and thirty-eight did
    not, so it was a line that turned up on some and not others; and now that every du'a can be
    heard read aloud, pressing play is a better answer to "how does it sound" than English
    letters are. The kalima keep theirs -- same reader, but only six of them and all six have it.
    """

    def window(self):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(1024, 600)
        w.show()
        w.side.resize(600, 1024)
        w.side.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        return w

    def said_on(self, page):
        return [x for x in page.findChildren(QtWidgets.QLabel)
                if x.objectName() in ("duaCardSaid", "passageSaid") and x.isVisible()
                and x.text().strip()]

    def test_no_transliteration_on_a_du_a_card(self):
        w = self.window()
        w.open_the_kinds_of_dua()
        settle()
        for kind in ("general", "morning", "forgiveness"):
            with self.subTest(kind):
                w.open_dua_category(kind)
                settle()
                for card in w.dua_board.cards:
                    self.assertEqual([], self.said_on(card),
                                     "a card is still showing a transliteration")

    def test_no_transliteration_on_a_du_a_s_own_page(self):
        w = self.window()
        for i in (0, 3, 9):          # three of the ten that have one in the file
            with self.subTest(i):
                w.open_passage("duas", i)
                settle()
                self.assertEqual([], self.said_on(w.section_readers["duas"]))

    def test_the_kalima_keep_theirs(self):
        """The same reader serves both, so this is the line that stops the du'a change from
        quietly taking the kalima's transliteration with it."""
        w = self.window()
        w.open_passage("kalima", 0)
        settle()
        said = self.said_on(w.section_readers["kalima"])
        self.assertTrue(said, "the first kalima has lost its transliteration")
        self.assertIn("ilaha", said[0].text().lower())

    def test_the_arabic_got_the_room(self):
        """The point of removing it. Measured against a card built with the line put back."""
        w = self.window()
        w.open_the_kinds_of_dua()
        settle()
        w.open_dua_category("gratitude")
        settle()
        card = w.dua_board.cards[0]
        self.assertGreater(card.arabic.height(), card.height() * 0.45,
                           "the Arabic is not using the room the transliteration left")


class HadithHeadingTest(unittest.TestCase):
    """The Hadith plate sits against the left of the page, as the world screen's does.

    Hadith opens its twelve headings now, so the page this is about is reached the way a mat
    whose assets were half copied reaches it: with the section emptied. That is still a screen
    the mat can land on, and the plate on it is still the one Harry asked to have moved left.
    """

    def window(self, size=(1024, 600)):
        w = MainWindow(load(ASSETS), available_packs(ASSETS),
                       Settings(theme="dark", place="Bury"),
                       scale=1.0, save_settings=False, aspect=None, side=True)
        w.resize(*size)
        w.show()
        w.tick()
        settle()
        self.addCleanup(lambda: shut(w))
        w.section_lists["hadith"].passages._items = []
        w.open_corner("hadith")
        settle()
        return w

    def test_the_plate_is_against_the_left(self):
        for size in ((1024, 600), (1920, 1080)):
            with self.subTest(f"{size[0]}x{size[1]}"):
                w = self.window(size)
                plate = w.soon_title
                page = w.corner_soon
                left = plate.mapTo(page, QtCore.QPoint(0, 0)).x()
                middle = plate.mapTo(page, plate.rect().center()).x()
                self.assertEqual("Hadith", plate.text())
